function getTabs(sub, category) {
    // Not: 'music' bu ekrana hiç gelmez — CategoryScreen'deki SPECIAL_SCREENS
    // haritası onu ayrı bir ekrana (MusicHomeScreen) yönlendiriyor. "Sanatçılar"
    // sekmesi orada, amateurTab satırına eklendi (bkz. o dosya).
    if (category === 'ARTS')
        return ['rivals', 'coaches', 'media', 'archive'];
    // Sanal Alem — rekabetçi maç/turnuva/hakem yapısı yok, Instagram tarzı
    // foto/video akışının olduğu tek sekme.
    if (sub === 'sanal_alem')
        return ['media'];
    if (ROUTE_ENABLED_SUBS.has(sub))
        return ['rivals', 'routes', 'coaches', 'equipment', 'media', 'posts', 'tickets', 'news', 'archive'];
    // Airsoft: Destek (koç) ve Bilet Al sekmelerine ihtiyaç yok, Etkinlikler'in
    // sağına Turnuvalar eklendi.
    if (sub === 'airsoft')
        return ['rivals', 'tournaments', 'equipment', 'media', 'posts', 'news', 'archive'];
    // Atıcılık & Avcılık: airsoft ile aynı mantık — Destek/Bilet Al kaldırıldı,
    // Etkinlikler'in sağına Turnuvalar eklendi.
    if (sub === 'shooting_hunting')
        return ['rivals', 'tournaments', 'equipment', 'media', 'posts', 'news', 'archive'];
    // Ayak Tenisi: Destek/Ekipman/Bilet Al'a ihtiyaç yok; Haberler de gerçek "ayak tenisi"
    // haberi neredeyse hiç çıkmadığı için (RSS zayıf eşleşince alakasız tenis haberi
    // gösteriyordu) kaldırıldı.
    if (sub === 'foot_tennis')
        return ['rivals', 'media', 'posts', 'archive'];
    if (SIMPLE_TAB_SUBS.has(sub))
        return ['rivals', 'coaches', 'equipment', 'media', 'posts', 'tickets', 'news', 'archive'];
    if (sub === 'football')
        return ['rivals', 'player_wanted', 'tournaments', 'coaches', 'archive', 'referee', 'media'];
    if (sub === 'volleyball')
        return ['rivals', 'player_wanted', 'tournaments', 'coaches', 'equipment', 'media', 'tickets', 'archive'];
    // Kullanıcı isteği: badminton ve masa tenisi, padel ile aynı sekme setini kullanıyor.
    if (sub === 'tennis' || sub === 'padel' || sub === 'badminton' || sub === 'table_tennis')
        return ['rivals', 'tournaments', 'coaches', 'equipment', 'media', 'posts', 'tickets', 'news', 'archive'];
    return ['rivals', 'tournaments', 'coaches', 'archive', 'media'];
}

