// noEmoji: voleybol kartlarında (Açık İlanlar/Yaklaşan Maçlar) mod/tarih/saat/ücret/kort
// gibi alanların başındaki emojiler kalabalık ve gereksiz bulunduğu için kaldırılıyor —
// diğer dallarda bu prop verilmiyor, davranış aynı kalıyor.
function ModeBadge({ mode, noEmoji }) {
    const t = useT();
    const label = (raw) => noEmoji ? noEmojiStr(raw) : raw;
    if (mode === 'BOTH') return (
        <View style={[s.modeBadge, { backgroundColor:'#a855f720', borderColor:'#a855f740' }]}>
            <Text style={[s.modeBadgeText, { color:'#c084fc' }]}>{label(t.modeBoth)}</Text>
        </View>
    );
    if (mode === 'COMPETITIVE') return (
        <View style={[s.modeBadge, { backgroundColor:'#dc262620', borderColor:'#dc262640' }]}>
            <Text style={[s.modeBadgeText, { color:'#f87171' }]}>{label(t.modeCompetitive)}</Text>
        </View>
    );
    return (
        <View style={[s.modeBadge, { backgroundColor:'#2563eb20', borderColor:'#2563eb40' }]}>
            <Text style={[s.modeBadgeText, { color:'#60a5fa' }]}>{label(t.modePractice)}</Text>
        </View>
    );
}

// ─── Rival Detail Modal ────────────────────────────────────────────────────────

const det = StyleSheet.create({
    section:      { backgroundColor: colors.surface2, borderRadius:moderateScale(14), padding:moderateScale(12), marginBottom:moderateScale(12), borderWidth:1, borderColor: colors.border },
    sectionTitle: { color:'#fff', fontSize:moderateScale(13), fontWeight:'800', marginBottom:moderateScale(10) },
    playerRow:    { flexDirection:'row', alignItems:'center', gap:moderateScale(10), paddingVertical:moderateScale(7), borderTopWidth:1, borderTopColor: colors.border },
    playerName:   { color:'#fff', fontSize:moderateScale(13), fontWeight:'700' },
    playerSub:    { color: colors.textMuted, fontSize:moderateScale(11), marginTop:1 },
    emptyTxt:     { color: colors.textMuted, fontSize:moderateScale(12), textAlign:'center', paddingVertical:moderateScale(8) },
    chatBtn:      { backgroundColor:'#2563eb30', borderRadius:moderateScale(8), width:moderateScale(28), height:moderateScale(28), justifyContent:'center', alignItems:'center', borderWidth:1, borderColor:'#2563eb50' },
    chatBtnTxt:   { fontSize:moderateScale(13) },
});

function RivalDetailModal({ visible, item, myId, sub, cfg, t, onClose, navigation, handleJoin, handleCancel, handleRespondJoin, handleWithdraw, onEdit, onRefresh, myRefereeListing, onConfirmLateJoin, highlightSlot: highlightSlotFromNotif = null, autoOpenOrder = false }) {
    const insets = useSafeAreaInsets();
    // Kullanıcı raporu: "Atanmamış" ızgarasında derece puanı (⭐) küçük ekranlı telefonlarda
    // görünmüyordu — sabit 3 sütun (width:'32%') dar ekranda isim+cinsiyet metnini doldurup
    // numberOfLines={1} yüzünden sondaki puanı kesiyordu. Dar ekranlarda 2 sütuna düşülerek
    // her hücreye daha fazla genişlik ayrılır (bkz. unassignedGridCols kullanımı aşağıda).
    const { width: screenWidth } = useWindowDimensions();
    const unassignedGridCols = screenWidth < 380 ? 2 : 3;
    // DOUBLE kadro kartında boş bir formaya dokunarak doğrudan o slota başvurabilmek için
    // (bkz. SlotBox) — kendi cinsiyetimiz slotun gereksinimine uymuyorsa buton hiç gösterilmez.
    const myGender = useSelector(s => s.auth.user?.gender);
    const [localParticipants, setLocalParticipants] = useState(null);
    // "Atanmamış" havuzu için ayrı local override — önceden yoktu, bu yüzden kabul edilen bir
    // oyuncu atanmamışa düştüğünde (voleybol bireysel kabul, DOUBLE) kartta anında görünmüyor,
    // sadece onRefresh()'in tüm ilan listesini yeniden çekmesini bekleyip ortaya çıkıyordu —
    // "kabul edince isim yerleşmesi çok yavaş" hissinin asıl sebebi buydu.
    const [localUnassigned, setLocalUnassigned] = useState(null);
    const [localSenderTeam, setLocalSenderTeam] = useState(null); // partner slotu — swap-positions sonrası anında güncellensin diye
    const [localJoinRequests, setLocalJoinRequests] = useState(null);
    // Kullanıcı raporu: pozisyon önerisi/atama gibi bazı backend uçları (respondPositionSuggestion,
    // setParticipantPosition vb.) senderTeam/participants/unassignedPlayers'ı güncelleyip
    // broadcast ederken skillRating'i YENİDEN hesaplamıyor (o alan sadece GET uçlarında canlı
    // eklenir, DB'de kalıcı tutulmaz) — bu yüzden ilan sahibinin AÇIK OLAN detay ekranı bu
    // broadcast'i alınca elo puanı anında kayboluyordu (oyuncunun kendi telefonu ise bildirime
    // tıklayıp TAZE bir GET ile açtığı için puanı görüyordu). Burada en son bilinen doğru
    // skillRating'ler bir cache'te tutulup, broadcast'te eksik gelen (null) puanlar bu
    // cache'ten doldurulur.
    const ratingsCacheRef = useRef({});
    // Kullanıcı isteği: "bildirime tıklayınca ne oluyorsa maça tıklayıp detay açılınca da
    // aynısı olsun" — highlightSlotFromNotif SADECE bildirimden gelindiyse dolu (navigasyon
    // parametreleri). Burada AYRICA ilanın kendi joinRequests verisinden benim bekleyen
    // (PENDING, ilan sahibi tarafından başlatılmış) bir slot davetim var mı diye bakılıyor —
    // varsa, ilana nereden girilmiş olursa olsun (liste, arama, doğrudan dokunuş...) aynı
    // vurgu/çevirme dizisi tetiklenir. Tenis/padel (DOUBLE) VE voleybol/airsoft (takım slotu)
    // için ortak — isPartnerInvite iki türde de kullanılıyor, matchType'a göre ayrıştırılıyor.
    const myPendingSlotInvite = (localJoinRequests ?? (Array.isArray(item.joinRequests) ? item.joinRequests : []))
        .find(jr => jr.userId === myId && jr.initiatedBy === 'OWNER' && jr.status === 'PENDING' && (jr.isPartnerInvite || jr.isOppTeamInvite || jr.requestedSlot));
    // useMemo: aşağıdaki highlightPulse animasyon efekti highlightSlot'u dependency olarak
    // kullanıyor — her render'da yeni bir {} referansı üretilirse (myPendingSlotInvite aynı
    // kalsa bile) animasyon loop'u gereksiz yere durup yeniden başlıyor, yanıp sönme kekeliyordu.
    const derivedHighlightSlot = useMemo(() => (myPendingSlotInvite ? (
        item.matchType === 'DOUBLE'
            ? { doubleSlot: myPendingSlotInvite.isPartnerInvite ? 'partner' : myPendingSlotInvite.requestedSlot }
            : { side: myPendingSlotInvite.isPartnerInvite ? 'my' : 'opp', slotIndex: Number.isInteger(myPendingSlotInvite.slotIndex) ? myPendingSlotInvite.slotIndex : null }
    ) : null), [myPendingSlotInvite?.isPartnerInvite, myPendingSlotInvite?.isOppTeamInvite, myPendingSlotInvite?.requestedSlot, myPendingSlotInvite?.slotIndex, item.matchType]);
    const highlightSlot = useMemo(() => highlightSlotFromNotif || derivedHighlightSlot, [highlightSlotFromNotif, derivedHighlightSlot]);
    const [localGender, setLocalGender] = useState(null); // {genderReq, partnerGenderReq, opp1GenderReq, opp2GenderReq}
    const [swapSlot, setSwapSlot] = useState(null); // 'partner'|'opp1'|'opp2' — seçili slot
    // Boş bir DOUBLE slotuna uzun basınca açılan çoklu-seç arkadaş listesi (bkz. SlotBox).
    const [showDoubleFriendsPicker, setShowDoubleFriendsPicker] = useState(false);
    // HANGİ boş slotun ikonundan açıldığı — kullanıcı raporu: "2./3./4. oyuncu formundan davet
    // ediyorum, hep 'kadın kabul ediyor' hatası veriyor". Sebep: picker'daki ilk seçim HER ZAMAN
    // sabit ['partner','opp1','opp2'] sırasındaki İLK boş slotun (genelde partner) cinsiyet
    // kuralına göre kontrol ediliyordu — kullanıcı hangi kutunun ikonuna dokunduğuna bakılmadan.
    // Artık tıklanan slot sıranın BAŞINA alınıyor, ilk seçim her zaman GERÇEKTEN tıklanan slotun
    // kuralına göre kontrol ediliyor (bkz. aşağıdaki FriendsMultiPickerModal emptyKeys).
    const [doubleInviteFromSlot, setDoubleInviteFromSlot] = useState(null);
    // Voleybol kadro kartındaki Yedek Sayısı seçici — ilan oluşturma formundaki subCount
    // ile aynı mantık, açık ilanda da kurucu ayarlayabiliyor (bkz. updateSubCount).
    const [showSubCountPicker, setShowSubCountPicker] = useState(false);
    // Kurucu/Rakip Takım ismi düzenleme — Yaklaşan Maçlar'daki (UpcomingCard) ✎ ile aynı,
    // sadece burada açık ilan için (bkz. saveTeamNameEdit, /rivals/:id/team-name).
    const [teamNameEdit, setTeamNameEdit] = useState(null); // { side: 'founder'|'opponent', value } | null
    const [savingTeamNameEdit, setSavingTeamNameEdit] = useState(false);
    // Çiftlerde kabul edilen oyuncular varsayılan olarak Partner/Rakip 1/Rakip 2 kartlarına
    // otomatik yerleşmiş gösterilmez — önce sırayla "Katılımcı 1/2/3" olarak listelenir,
    // kurucu isterse "Takımları Düzenle" ile mevcut kart/takas ekranını açar.
    const [showTeamCards, setShowTeamCards] = useState(false);
    // Kullanıcı isteği: "İstekler" ve "Yedek İstekleri" listeleri yer kaplıyordu — en sağa
    // dokununca açılıp kapanan bir ok eklendi. Varsayılan durum istek sayısına göre değişir:
    // 5'ten fazla istek varsa varsayılan KAPALI (ok sola dönük, yer tasarrufu için), 5 ya da
    // daha az istek varsa varsayılan AÇIK (ok aşağı dönük, az sayıda istek gizlenmesin).
    const [requestsExpanded, setRequestsExpanded] = useState(() => {
        const initialCount = (Array.isArray(item.joinRequests) ? item.joinRequests : []).filter(jr => jr.initiatedBy !== 'OWNER').length;
        return initialCount <= 5;
    });
    // Oyuncular kartı "Takımları Düzenle"ye basınca kart çevrilir gibi arka
    // yüzüne (takım düzenleme ızgarası) döner; tekrar çevirince ön yüze
    // (katılımcı listesi) geri gelir. rotateY 0->90 derece dönerken (kart
    // "yan"a gelince, en ince görünümdeyken) içerik değişir, sonra 90->0
    // devam edip düzleşir — bu yüzden ön/arka içeriğin farklı yükseklikte
    // olması sorun olmuyor (aynı anda sadece biri DOM'da).
    const flipAnim = useRef(new Animated.Value(0)).current;
    const toggleTeamCards = (next) => {
        setSwapSlot(null);
        Animated.timing(flipAnim, { toValue: 1, duration: 160, useNativeDriver: true }).start(() => {
            setShowTeamCards(next);
            Animated.timing(flipAnim, { toValue: 0, duration: 160, useNativeDriver: true }).start();
        });
    };
    const cardRotateY = flipAnim.interpolate({ inputRange: [0, 1], outputRange: ['0deg', '90deg'] });
    // Davetten gelindiyse (highlightSlot) kart otomatik olarak birkaç kez çevrilip kullanıcının
    // dikkatini "arka yüzde bir şey var" a çeksin — kullanıcı isteği: önce ön yüz (diğer
    // ilanlarla aynı, şaşırtıcı olmasın), hemen arkaya dönüp 2sn dursun, öne dönüp 1sn,
    // tekrar arkaya dönüp 2sn, sonra öne dönüp kullanıcıya bırakılsın. Kullanıcı bu 5 saniye
    // içinde kendisi çevirme butonuna dokunursa dizi hemen iptal edilir (bkz. userFlippedRef,
    // manuel buton onPress'i). Modal her açılışta bir kere çalışsın diye ref ile korunuyor.
    const highlightSeqRanRef = useRef(false);
    const highlightTimersRef = useRef([]);
    const userFlippedRef = useRef(false);
    const [flipHintActive, setFlipHintActive] = useState(false);
    const cancelHighlightSequence = () => {
        userFlippedRef.current = true;
        highlightTimersRef.current.forEach(clearTimeout);
        highlightTimersRef.current = [];
    };
    useEffect(() => {
        if (!visible || !highlightSlot || highlightSeqRanRef.current) return;
        highlightSeqRanRef.current = true;
        const schedule = (fn, delay) => highlightTimersRef.current.push(setTimeout(() => { if (!userFlippedRef.current) fn(); }, delay));
        schedule(() => toggleTeamCards(true), 400);
        schedule(() => toggleTeamCards(false), 400 + 2000);
        schedule(() => toggleTeamCards(true), 400 + 2000 + 1000);
        schedule(() => { toggleTeamCards(false); setFlipHintActive(true); }, 400 + 2000 + 1000 + 2000);
        return () => highlightTimersRef.current.forEach(clearTimeout);
    }, [visible, highlightSlot]);
    // Vurgulanan boş slotun (ve çevirme butonundaki ipucu rozetinin) yanıp sönmesi için ortak
    // pulse animasyonu.
    const highlightPulse = useRef(new Animated.Value(0.4)).current;
    useEffect(() => {
        if (!highlightSlot) return;
        const loop = Animated.loop(Animated.sequence([
            Animated.timing(highlightPulse, { toValue: 1, duration: 550, useNativeDriver: true }),
            Animated.timing(highlightPulse, { toValue: 0.4, duration: 550, useNativeDriver: true }),
        ]));
        loop.start();
        return () => loop.stop();
    }, [highlightSlot]);
    // Ön yüzde takıma atanmamış (side'ı henüz belli olmayan) katılımcıların ismi kırmızı
    // yanıp söner — kullanıcı isteği: "ataması olmayan isimler uyarıcı hatırlatma olsun".
    // Atama artık arka yüzdeki "Atanmamış" listesinden yapılıyor (bkz. promptAssignTeam).
    const unassignedBlink = useRef(new Animated.Value(1)).current;
    // Kullanıcı isteği: bu ilan/tesis üzerinden verdiği sipariş İŞLETME TARAFINDAN
    // ONAYLANMIŞ (CONFIRMED/READY, bkz. backend orderedUserIds filtresi) bir oyuncunun
    // kadro kartındaki isminin SAĞINDA küçük yanıp sönen bir 📋 ikonu/buton belirsin — aynı
    // unassignedBlink deseni (bkz. yukarıdaki yorum). Sadece kendi siparişiyse tıklanabilir.
    const [localOrderedUserIds, setLocalOrderedUserIds] = useState([]);
    const orderBlink = useRef(new Animated.Value(1)).current;
    useEffect(() => {
        if (localOrderedUserIds.length === 0) return;
        const loop = Animated.loop(Animated.sequence([
            Animated.timing(orderBlink, { toValue: 0.25, duration: 500, useNativeDriver: true }),
            Animated.timing(orderBlink, { toValue: 1, duration: 500, useNativeDriver: true }),
        ]));
        loop.start();
        return () => loop.stop();
    }, [localOrderedUserIds.length]);
    const [orderVenueId, setOrderVenueId] = useState(null);
    // Kullanıcı isteği: kendi siparişini veren oyuncu, ismi yanındaki yanıp sönen ikona
    // dokununca kendi siparişinin (teslim/ödeme) durumunu görebilsin — bkz. MyOrderStatusModal.
    const [showMyOrder, setShowMyOrder] = useState(false);
    // Kullanıcı isteği: "Sipariş Güncellendi/Onaylandı/Hazır" bildiriminden gelindiyse
    // (autoOpenOrder), detay açılır açılmaz kendi sipariş durumu otomatik gösterilsin.
    useEffect(() => {
        if (visible && autoOpenOrder) setShowMyOrder(true);
    }, [visible, autoOpenOrder]);
    const [comments, setComments] = useState([]);
    const [loadingComments, setLoadingComments] = useState(false);
    const [commentText, setCommentText] = useState('');
    const [sendingComment, setSendingComment] = useState(false);
    // Seyirci listesi — sadece voleybolda: onaylı antrenörlerin izledikleri maçlardaki
    // oyuncuları değerlendirebilmesi için (bkz. resolveRaterRole, backend/utils/volleyballRating.js).
    const [spectators, setSpectators] = useState([]);
    const [amISpectator, setAmISpectator] = useState(false);
    const [spectatorActionLoading, setSpectatorActionLoading] = useState(false);
    const [disputingSpectatorId, setDisputingSpectatorId] = useState(null);
    const [disputingReferee, setDisputingReferee] = useState(false);
    const [inviteModalVisible, setInviteModalVisible] = useState(false);
    const [inviteQuery, setInviteQuery] = useState('');
    const [inviteResults, setInviteResults] = useState([]);
    const [inviteSearching, setInviteSearching] = useState(false);
    const [invitingUserId, setInvitingUserId] = useState(null);
    const [invitedUserIds, setInvitedUserIds] = useState(() => new Set()); // davet gönderilenler — anında "Davet Gönderildi" göstermek için
    const [inviteForReferee, setInviteForReferee] = useState(false); // true iken davet paneli hakem ilanına gönderir

    // Çiftler: bireysel başvurmuşlar arası partner davet/kabul/geri çek
    const [partnerActionLoading, setPartnerActionLoading] = useState(false);
    const [showJoinInvitePicker, setShowJoinInvitePicker] = useState(false);
    const [joinInviteCandidates, setJoinInviteCandidates] = useState([]);
    const [seedingDemoRival, setSeedingDemoRival] = useState(false);
    const seedingDemoRivalRef = useRef(false);
    // Voleybol: "Demo Başvuru Gönder" burada tek seferlik değil, durdurulana kadar 2 saniyede
    // bir yeni demo oyuncu başvurusu gönderen bir spam/test butonu — bkz. POST /demo/volleyball-join.
    const [demoSpamActive, setDemoSpamActive] = useState(false);
    const demoSpamIntervalRef = useRef(null);
    // Kullanıcı raporu: sabit setInterval, önceki demo isteği bitmeden yenisini ateşliyordu —
    // her demo isteği kendi içinde sırayla birden çok deneme yaptığı için (bkz.
    // seedVolleyballDemoJoin, en fazla 15 deneme) bazen 2 saniyeden uzun sürebiliyor, bu da
    // gittikçe büyüyen bir eşzamanlı istek yığınına ve "Kabul Et" gibi gerçek işlemlerin
    // birkaç saniye donmasına yol açıyordu. demoSpamRunningRef true olduğu sürece bir sonraki
    // istek ÖNCEKİsi tamamlanmadan asla ateşlenmiyor.
    const demoSpamRunningRef = useRef(false);
    useEffect(() => () => { demoSpamRunningRef.current = false; if (demoSpamIntervalRef.current) clearTimeout(demoSpamIntervalRef.current); }, []);

    // Hakem ilanı: fiyat teklifi/mesaj/CV ile başvuru; asıl maç ilanı: ilan sahibi + katılımcıların
    // ortak gördüğü hakem başvuruları listesi.
    const [refereeApplyVisible, setRefereeApplyVisible] = useState(false);
    const [refereeOfferPrice, setRefereeOfferPrice] = useState('');
    const [refereeOfferMessage, setRefereeOfferMessage] = useState('');
    const [refereeSendCv, setRefereeSendCv] = useState(true);
    const [refereeApplySubmitting, setRefereeApplySubmitting] = useState(false);
    const [refereeApplications, setRefereeApplications] = useState([]);
    const [refereeAdId, setRefereeAdId] = useState(null);

    // Hakem başvuruları asıl maçın id'siyle sorgulanır — Hakemler sekmesinden ilanın
    // kendi detayı açıldıysa (isRefereeAd) linkedRivalId asıl maçın id'sidir.
    const refereeMatchIdForApps = item?.refereeRequested ? item?.id : item?.linkedRivalId;
    useEffect(() => {
        setRefereeApplications([]);
        setRefereeAdId(null);
        setInviteForReferee(false);
        if (refereeMatchIdForApps && visible) {
            api.get(`/rivals/${refereeMatchIdForApps}/referee-applications`)
                .then(({ data }) => {
                    setRefereeApplications(Array.isArray(data.applications) ? data.applications : []);
                    setRefereeAdId(data.refereeAdId || null);
                })
                .catch(() => {});
        }
    }, [refereeMatchIdForApps, visible]);

    const submitRefereeApply = async () => {
        setRefereeApplySubmitting(true);
        try {
            await api.post(`/rivals/${item.id}/respond`, {
                asReferee: true,
                offerPrice: refereeOfferPrice ? `${refereeOfferPrice}₺` : undefined,
                offerMessage: refereeOfferMessage || undefined,
                offerCvUrl: refereeSendCv && myRefereeListing?.cvUrl ? myRefereeListing.cvUrl : undefined,
            });
            setRefereeApplyVisible(false);
            onRefresh();
        } catch (e) {
            Alert.alert(t.error, e?.response?.data?.message || t.actionFailed);
        } finally {
            setRefereeApplySubmitting(false);
        }
    };

    const [counterInputFor, setCounterInputFor] = useState(null);
    const [counterPriceInput, setCounterPriceInput] = useState('');
    const [counterMessageInput, setCounterMessageInput] = useState('');

    const reloadRefereeApplications = () => {
        if (!refereeMatchIdForApps) return;
        api.get(`/rivals/${refereeMatchIdForApps}/referee-applications`)
            .then(({ data }) => {
                setRefereeApplications(Array.isArray(data.applications) ? data.applications : []);
                setRefereeAdId(data.refereeAdId || null);
            })
            .catch(() => {});
    };

    const [respondingAppId, setRespondingAppId] = useState(null);
    const respondRefereeApplication = async (jrId, action, price, message) => {
        // Kullanıcı isteği: reddet/kabul et sonrası liste sadece reloadRefereeApplications'ın
        // ağ turu tamamlanınca güncelleniyordu — bu gecikme sırasında aynı butona tekrar
        // dokununca (kullanıcı "gitmedi" sanıp tekrar deniyordu) backend "bu istek artık
        // bekleyen durumda değil" hatası veriyordu. respondingAppId ile istek sürerken aynı
        // başvurunun butonları devre dışı bırakılır, başarı sonrası da state anında (ağ
        // turunu beklemeden) güncellenir.
        if (respondingAppId) return;
        setRespondingAppId(jrId);
        try {
            await api.patch(`/rivals/join/${jrId}`, { action, price, message });
            setCounterInputFor(null);
            setCounterPriceInput('');
            setCounterMessageInput('');
            if (action === 'reject') {
                setRefereeApplications(prev => prev.filter(app => app.id !== jrId));
            } else if (action === 'accept') {
                setRefereeApplications(prev => prev.map(app => app.id === jrId ? { ...app, status: 'ACCEPTED' } : app));
            } else if (action === 'counter') {
                setRefereeApplications(prev => prev.map(app => app.id === jrId ? { ...app, status: 'COUNTERED', counterPrice: price, counterMessage: message } : app));
            }
            // Diğer bekleyen başvurular (ör. hakem kabul edilince otomatik reddedilenler)
            // ile senkron kalmak için arka planda tam bir yeniden çekme de yapılır.
            reloadRefereeApplications();
            onRefresh();
        } catch (e) {
            Alert.alert(t.error, e?.response?.data?.message || t.actionFailed);
        } finally {
            setRespondingAppId(null);
        }
    };

    useEffect(() => {
        setLocalParticipants(null);
        setLocalUnassigned(null);
        setLocalSenderTeam(null);
        setLocalJoinRequests(null);
        setLocalGender(null);
        setSwapSlot(null);
        setShowTeamCards(false);
        setComments([]);
        setCommentText('');
        setSpectators([]);
        setAmISpectator(false);
        setLocalOrderedUserIds([]);
        if (item?.id && visible) {
            // Fresh fetch: güncel cinsiyet, katılımcılar ve istekler
            api.get(`/rivals/${item.id}`)
                .then(({ data }) => {
                    setLocalGender({
                        genderReq: data.genderReq ?? item.genderReq,
                        partnerGenderReq: data.partnerGenderReq ?? item.partnerGenderReq,
                        opp1GenderReq: data.opp1GenderReq ?? item.opp1GenderReq,
                        opp2GenderReq: data.opp2GenderReq ?? item.opp2GenderReq,
                    });
                    if (Array.isArray(data.joinRequests)) setLocalJoinRequests(data.joinRequests);
                    if (Array.isArray(data.participants)) setLocalParticipants(data.participants);
                    if (Array.isArray(data.unassignedPlayers)) setLocalUnassigned(data.unassignedPlayers);
                    setLocalOrderedUserIds(Array.isArray(data.orderedUserIds) ? data.orderedUserIds : []);
                })
                .catch(() => {});
            setLoadingComments(true);
            api.get(`/rivals/${item.id}/comments`)
                .then(res => setComments(res.data || []))
                .catch(e => Alert.alert('Hata', e?.response?.data?.message || 'Yorumlar yüklenemedi'))
                .finally(() => setLoadingComments(false));
            if (item.subCategory === 'volleyball') {
                api.get(`/rivals/${item.id}/spectators`)
                    .then(({ data }) => {
                        setSpectators(Array.isArray(data?.spectators) ? data.spectators : []);
                        setAmISpectator(!!data?.amISpectator);
                    })
                    .catch(() => {});
            }
        }
    }, [item?.id, visible]);

    const toggleSpectator = () => {
        if (!item?.id || spectatorActionLoading) return;
        setSpectatorActionLoading(true);
        const req = amISpectator ? api.delete(`/rivals/${item.id}/spectators`) : api.post(`/rivals/${item.id}/spectators`);
        req.then(({ data }) => {
            setSpectators(Array.isArray(data?.spectators) ? data.spectators : []);
            setAmISpectator(!!data?.amISpectator);
        })
            .catch(e => Alert.alert(t.error, e?.response?.data?.message || t.actionFailed))
            .finally(() => setSpectatorActionLoading(false));
    };

    // Maç kadrosundan biri "bu kişi seyirci olarak gelmedi, sahte" diye itiraz eder — kadronun
    // yarısından fazlası itiraz edince seyirci kaydı silinir ve varsa buna dayanan antrenör
    // değerlendirmesi geçersiz kılınır (bkz. disputeSpectator, backend/spectator.controller.js).
    const disputeSpectatorUser = (targetUserId) => {
        Alert.alert(t.spectatorDisputeConfirmTitle, t.spectatorDisputeConfirmMsg, [
            { text: t.cancelBtn, style: 'cancel' },
            {
                text: t.spectatorDisputeConfirmBtn, style: 'destructive', onPress: () => {
                    setDisputingSpectatorId(targetUserId);
                    api.post(`/rivals/${item.id}/spectators/${targetUserId}/dispute`)
                        .then(({ data }) => {
                            if (data?.resolved) {
                                setSpectators(prev => prev.filter(sp => sp.user?.id !== targetUserId));
                                Alert.alert(t.spectatorDisputeResolvedTitle, t.spectatorDisputeResolvedMsg);
                            } else {
                                Alert.alert(t.spectatorDisputeRecordedTitle, t.spectatorDisputeRecordedMsg(data.voteCount, data.majorityNeeded));
                            }
                        })
                        .catch(e => Alert.alert(t.error, e?.response?.data?.message || t.actionFailed))
                        .finally(() => setDisputingSpectatorId(null));
                },
            },
        ]);
    };

    // Kullanıcı isteği: maç kadrosundan biri mevcut hakeme itiraz eder — kadronun yarısından
    // fazlası aynı hakeme itiraz edince hakem maçtan otomatik çıkarılır ve kendisine bilgi
    // gider (bkz. disputeReferee, backend/rival.controller.js).
    const disputeRefereeUser = () => {
        Alert.alert(t.refereeDisputeConfirmTitle, t.refereeDisputeConfirmMsg, [
            { text: t.cancelBtn, style: 'cancel' },
            {
                text: t.refereeDisputeConfirmBtn, style: 'destructive', onPress: () => {
                    setDisputingReferee(true);
                    api.post(`/rivals/${item.id}/referee/dispute`)
                        .then(({ data }) => {
                            if (data?.resolved) {
                                Alert.alert(t.refereeDisputeResolvedTitle, t.refereeDisputeResolvedMsg);
                                onRefresh();
                            } else {
                                Alert.alert(t.refereeDisputeRecordedTitle, t.refereeDisputeRecordedMsg(data.voteCount, data.majorityNeeded));
                            }
                        })
                        .catch(e => Alert.alert(t.error, e?.response?.data?.message || t.actionFailed))
                        .finally(() => setDisputingReferee(false));
                },
            },
        ]);
    };

    // Kullanıcı isteği: "hakemi çıkarmak istiyorum ama çıkar yok" — disputeRefereeUser kadro
    // çoğunluğunun oyuna ihtiyaç duyuyor, ilan sahibinin TEK BAŞINA hakemi çıkarabileceği bir
    // yol yoktu. removeReferee (backend) sadece sahibi yetkilendirir, oy toplamadan hemen uygular.
    const removeAssignedReferee = () => {
        Alert.alert(t.refereeRemoveConfirmTitle, t.refereeRemoveConfirmMsg, [
            { text: t.cancelBtn, style: 'cancel' },
            {
                text: t.refereeRemoveConfirmBtn, style: 'destructive', onPress: () => {
                    setDisputingReferee(true);
                    api.delete(`/rivals/${item.id}/referee`)
                        .then(() => onRefresh())
                        .catch(e => Alert.alert(t.error, e?.response?.data?.message || t.actionFailed))
                        .finally(() => setDisputingReferee(false));
                },
            },
        ]);
    };

    useEffect(() => {
        if (!visible || !item?.id) return;
        const off = onSocket('newComment', ({ rivalId, comment }) => {
            if (rivalId !== item.id) return;
            setComments(prev => prev.some(c => c.id === comment.id) ? prev : [...prev, comment]);
        });
        return off;
    }, [visible, item?.id]);

    useEffect(() => {
        if (!visible || !item?.id) return;
        const off = onSocket('rivalUpdate', (updated) => {
            if (updated.id !== item.id) return;
            const fillRatings = (arr) => (Array.isArray(arr) ? arr : []).map(p => (p?.id && p.skillRating == null && ratingsCacheRef.current[p.id] != null) ? { ...p, skillRating: ratingsCacheRef.current[p.id] } : p);
            if (Array.isArray(updated.joinRequests)) setLocalJoinRequests(updated.joinRequests);
            if (Array.isArray(updated.participants)) setLocalParticipants(fillRatings(updated.participants));
            // Kullanıcı isteği: davet ettiği kişi (Takım Arkadaşı/Partner ya da Atanmamış
            // havuzu daveti) kabul edince ilan sahibi/diğer görüntüleyenler çıkıp girmeden
            // anında görsün — önceden sadece participants/joinRequests senkronize ediliyordu,
            // senderTeam/unassignedPlayers'a düşen kabuller ekrana hiç yansımıyordu.
            if (Array.isArray(updated.senderTeam)) setLocalSenderTeam(fillRatings(updated.senderTeam));
            if (Array.isArray(updated.unassignedPlayers)) setLocalUnassigned(fillRatings(updated.unassignedPlayers));
            if (updated.genderReq !== undefined || updated.opp1GenderReq !== undefined) {
                setLocalGender({
                    genderReq: updated.genderReq ?? item.genderReq,
                    partnerGenderReq: updated.partnerGenderReq ?? item.partnerGenderReq,
                    opp1GenderReq: updated.opp1GenderReq ?? item.opp1GenderReq,
                    opp2GenderReq: updated.opp2GenderReq ?? item.opp2GenderReq,
                });
            }
        });
        return off;
    }, [visible, item?.id]);

    const isOwner = item.senderId === myId;
    // Hakem Arıyorum ilanları (matchType PLAYER_WANTED, positions:['REFEREE']) kendi
    // participants/senderTeam alanları hep boş (o alanlar hakemi tutar) — Oyuncular
    // bölümünde asıl maçın oyuncularını göstermek için linkedRival'a bakılır.
    const isRefereeAd = item.matchType === 'PLAYER_WANTED' && Array.isArray(item.positions) && item.positions.includes('REFEREE');
    // Hakem Arıyorum ilanları (linkedRival dolu) için: asıl maça oyuncu olarak
    // katılmış biri (kurucu/partner/rakip) kendi maçına hakemlik başvurusu yapamaz.
    const isLinkedMatchPlayer = !!item.linkedRival && (
        item.linkedRival.senderId === myId
        || (Array.isArray(item.linkedRival.participants) && item.linkedRival.participants.some(p => p?.id === myId))
        || (Array.isArray(item.linkedRival.senderTeam) && item.linkedRival.senderTeam.some(p => p?.id === myId))
    );
    const participants = localParticipants ?? (Array.isArray(item.participants) ? item.participants : []);
    const senderTeamArr = localSenderTeam ?? (Array.isArray(item.senderTeam) ? item.senderTeam : []);
    const unassignedArr = localUnassigned ?? (Array.isArray(item.unassignedPlayers) ? item.unassignedPlayers : []);
    // Seyirci itirazı: sadece bu maçın kadrosundaki (iki takım) oyuncular itiraz edebilir.
    const isMatchRosterMember = isOwner || senderTeamArr.some(p => p?.id === myId) || participants.some(p => p?.id === myId);
    const joinRequests = localJoinRequests ?? (Array.isArray(item.joinRequests) ? item.joinRequests : []);

    // Kullanıcı isteği: kadroya katılmış (owner olmayan) biri maçtan ayrılabilsin — cancelMatch'teki
    // AYNI geç iptal ceza penceresi (backend removeRivalParticipant'ta da aynı hesap tekrarlanır).
    const getItemMatchStart = () => {
        if (!item.matchDate || !item.matchTime) return null;
        const [h, min] = item.matchTime.split(':').map(Number);
        const d = new Date(item.matchDate);
        d.setHours(h, min, 0, 0);
        return d;
    };
    const itemMatchStart = getItemMatchStart();
    const itemHoursUntilMatch = itemMatchStart ? (itemMatchStart - new Date()) / (1000 * 60 * 60) : null;
    const isVolleyballItem = item.subCategory === 'volleyball';
    const leaveCancelPenaltyWindowHours = isVolleyballItem ? item.cancelPenaltyHours : 5;
    const leaveCancelPenaltyAmount = isVolleyballItem ? 0.10 : 0.20;
    const leaveWithinPenaltyWindow = leaveCancelPenaltyWindowHours != null && itemHoursUntilMatch !== null && itemHoursUntilMatch > 0 && itemHoursUntilMatch <= leaveCancelPenaltyWindowHours;
    const [leavingMatch, setLeavingMatch] = useState(false);
    const handleLeaveMatch = () => {
        const msg = leaveWithinPenaltyWindow
            ? t.cancelMatchPenaltyWarning(leaveCancelPenaltyWindowHours, leaveCancelPenaltyAmount)
            : t.cancelMatchConfirmMsg;
        Alert.alert(t.cancelMatchTitle, msg, [
            { text: 'Vazgeç', style: 'cancel' },
            {
                text: leaveWithinPenaltyWindow ? `${t.cancelMatchBtn} (-${leaveCancelPenaltyAmount.toFixed(2)})` : t.cancelMatchBtn,
                style: 'destructive',
                onPress: async () => {
                    setLeavingMatch(true);
                    try {
                        const { data } = await api.delete(`/rivals/${item.id}/participants/${myId}`);
                        if (Array.isArray(data?.request?.participants)) setLocalParticipants(data.request.participants);
                        if (Array.isArray(data?.request?.senderTeam)) setLocalSenderTeam(data.request.senderTeam);
                        if (Array.isArray(data?.request?.unassignedPlayers)) setLocalUnassigned(data.request.unassignedPlayers);
                        onClose();
                        onRefresh();
                    } catch (e) {
                        Alert.alert(t.error, e?.response?.data?.message || t.actionFailed);
                    } finally {
                        setLeavingMatch(false);
                    }
                },
            },
        ]);
    };
    useEffect(() => {
        [participants, senderTeamArr, unassignedArr].forEach(arr => {
            (Array.isArray(arr) ? arr : []).forEach(p => {
                if (p?.id && p.skillRating != null) ratingsCacheRef.current[p.id] = p.skillRating;
            });
        });
    }, [participants, senderTeamArr, unassignedArr]);
    const reqTimeAgo = (dateStr) => {
        if (!dateStr) return '';
        const diff = Date.now() - new Date(dateStr).getTime();
        const m = Math.floor(diff / 60000);
        if (m < 1) return t.timeNow;
        if (m < 60) return `${m}${t.timeMinSuffix}`;
        const h = Math.floor(m / 60);
        if (h < 24) return `${h}${t.timeHourSuffix}`;
        return `${Math.floor(h / 24)}${t.timeDaySuffix}`;
    };
    const genderReq = localGender?.genderReq ?? item.genderReq ?? 'MIX';
    const partnerGenderReq = localGender?.partnerGenderReq ?? item.partnerGenderReq ?? 'MIX';
    const opp1GenderReq = localGender?.opp1GenderReq ?? item.opp1GenderReq ?? 'MIX';
    const opp2GenderReq = localGender?.opp2GenderReq ?? item.opp2GenderReq ?? 'MIX';
    const genderLabel = (g) => g === 'MALE' ? '♂ Erkek' : g === 'FEMALE' ? '♀ Kadın' : null;
    const required = item.matchType === 'DOUBLE'
        ? ((Array.isArray(item.senderTeam) && item.senderTeam.length > 0) ? 2 : 3)
        : (item.teamSize || 1);
    const senderSideCount = 1 + (Array.isArray(item.senderTeam) ? item.senderTeam.length : 0);
    // Takım sporlarında (voleybol/airsoft) artık kayıtsız (manuel) rakip oyuncular da
    // participants içinde tutuluyor (bkz. addManualTeamPlayer) — sayaç onları da içermeli,
    // yoksa "(X/Y)" başlığı eksik gösteriyordu.
    const filled = participants.filter(p => p && (p.id || p.manualName)).length;
    // Rakip tarafta uygulamayı kullanmayan (serbest metin) oyuncular participants'a değil,
    // ayrı oppTeamManualNames alanına yazılıyor — sayaca dahil edilmezse "kadroda görünüyor
    // ama sayı hâlâ eksik gösteriyor" hissi oluyordu.
    const oppManualNames = Array.isArray(item.oppTeamManualNames) ? item.oppTeamManualNames.filter(n => typeof n === 'string' && n.trim()) : [];
    // Atanmamış havuz — kadro kartının ön yüzünde de sayılmalı, aksi halde başlıktaki
    // (X/Y) kartta gösterilenle uyuşmuyordu.
    const unassignedSlots = unassignedArr.filter(p => p?.id || p?.manualName);
    useEffect(() => {
        if (unassignedSlots.length === 0) return;
        const loop = Animated.loop(Animated.sequence([
            Animated.timing(unassignedBlink, { toValue: 0.25, duration: 500, useNativeDriver: true }),
            Animated.timing(unassignedBlink, { toValue: 1, duration: 500, useNativeDriver: true }),
        ]));
        loop.start();
        return () => loop.stop();
    }, [unassignedSlots.length]);
    // Arka yüzdeki "Atanmamış" listesinde bir isme dokununca hangi takıma (Kurucu/Rakip,
    // gerçek isimleriyle) atanacağı sorulur — kullanıcı isteği: "isme tıklayınca takımların
    // isimleri çıksın, birini seçip atayabilsin". Hem gerçek kullanıcılar (p.id) hem manuel
    // (kayıtsız, p.manualName) isimler için çalışır (bkz. assignManualToSide/backend). Dolu bir
    // takım seçeneklerde hiç ÇIKMAZ (kullanıcı isteği) — backend zaten reddediyordu ama seçilebilir
    // görünmesi kafa karıştırıyordu (bkz. assignPlayerToSide'daki kapasite kontrolü).
    const teamSizeNForAssign = item.teamSize || 1;
    const founderFullForAssign = 1 + senderTeamArr.filter(p => p && (p.id || p.manualName)).length >= teamSizeNForAssign;
    const oppFullForAssign = participants.filter(p => p && (p.id || p.manualName)).length + oppManualNames.length >= teamSizeNForAssign;
    const promptAssignTeam = (p) => {
        const name = p.id ? playerDisplayName(p) : p.manualName;
        const doAssign = (side) => p.id ? assignUnassignedToSide(p.id, side) : assignManualToSide(p.manualName, side);
        const buttons = [{ text: 'Vazgeç', style: 'cancel' }];
        if (!founderFullForAssign) buttons.push({ text: item.founderTeamName || t.myTeamLabel, onPress: () => doAssign('my') });
        if (!oppFullForAssign) buttons.push({ text: item.opponentTeamName || t.oppTeamLabel, onPress: () => doAssign('opp') });
        Alert.alert(name, buttons.length > 1 ? 'Hangi takıma atansın?' : 'İki takım da dolu — önce birinden yer açman gerekiyor.', buttons);
    };
    // Çiftlerde (DOUBLE) toplam kapasite sabit 4 (2 taraf x 2) ve "required" zaten
    // rakip tarafta kalan boş kontenjanı ifade eder. Takım sporlarında (voleybol 6v6 vb.)
    // "required" tek bir tarafın TAM boyutu (teamSize) — iki tarafı da saymadan
    // senderSideCount'a eklemek "1/7" gibi anlamsız bir toplam üretiyordu; gerçek
    // toplam kapasite her iki tarafın da dolu olduğu hâl, yani 2 x teamSize'dır.
    const totalCapacity = item.matchType === 'DOUBLE' ? (senderSideCount + required) : (2 * (item.teamSize || 1));
    // Hakem Arıyorum ilanının Oyuncular bölümü kendi (hep boş) alanları yerine
    // asıl maçın (linkedRival) oyuncularını gösterir.
    const linkedParticipants = (isRefereeAd && item.linkedRival && Array.isArray(item.linkedRival.participants)) ? item.linkedRival.participants : [];
    const linkedSenderTeam = (isRefereeAd && item.linkedRival && Array.isArray(item.linkedRival.senderTeam)) ? item.linkedRival.senderTeam : [];
    const linkedRequired = (isRefereeAd && item.linkedRival) ? (item.linkedRival.matchType === 'DOUBLE'
        ? (linkedSenderTeam.length > 0 ? 2 : 3)
        : (item.linkedRival.teamSize || 1)) : 0;
    const linkedSenderSideCount = (isRefereeAd && item.linkedRival) ? 1 + linkedSenderTeam.length : 0;
    const linkedFilled = linkedParticipants.filter(p => p?.id).length;
    const linkedTotalCapacity = (isRefereeAd && item.linkedRival)
        ? (item.linkedRival.matchType === 'DOUBLE' ? (linkedSenderSideCount + linkedRequired) : (2 * (item.linkedRival.teamSize || 1)))
        : 0;
    const mySentReq = item._myJoinStatus;
    const isFull = filled >= required;
    const isParticipant = participants.some(p => p?.id === myId);
    const myInvite = joinRequests.find(jr => jr.userId === myId && jr.initiatedBy === 'OWNER');
    const isInvolved = isOwner || isParticipant || (mySentReq !== null && mySentReq !== undefined);
    const participantIds = new Set([item.senderId, ...participants.filter(p => p?.id).map(p => p.id)]);
    const canDeleteComment = (c) => {
        const isAuthor = c.user?.id === myId;
        const iAmParticipant = participantIds.has(myId);
        const commenterIsParticipant = participantIds.has(c.user?.id);
        return isAuthor || (iAmParticipant && !commenterIsParticipant);
    };

    useEffect(() => {
        if (!inviteModalVisible) return;
        const q = inviteQuery.trim();
        // Kullanıcı isteği: hakem davetinde bir şey yazmayı beklemeden bu dalda kayıtlı TÜM
        // hakemlerin listesi ("hakem listesi") görünsün — /users/by-sport boş q ile de tüm
        // kayıtları döner. Normal oyuncu davetinde eskisi gibi en az 2 karakter gerekiyor.
        if (!inviteForReferee && (!q || q.length < 2)) { setInviteResults([]); return; }
        setInviteSearching(true);
        const task = setTimeout(() => {
            const url = inviteForReferee
                ? `/users/by-sport?subCategory=${sub}&category=${item.category}&refereeOnly=true${q ? `&q=${encodeURIComponent(q)}` : ''}`
                : `/users/search?q=${encodeURIComponent(q)}&subCategory=${sub}&category=${item.category}`;
            api.get(url)
                .then(res => setInviteResults(Array.isArray(res.data) ? res.data : []))
                .catch(() => setInviteResults([]))
                .finally(() => setInviteSearching(false));
        }, 400);
        return () => clearTimeout(task);
    }, [inviteQuery, inviteModalVisible, inviteForReferee]);

    const handleInvite = async (targetUser) => {
        setInvitingUserId(targetUser.id);
        try {
            const targetRivalId = inviteForReferee && refereeAdId ? refereeAdId : item.id;
            await api.post(`/rivals/${targetRivalId}/invite`, { userId: targetUser.id });
            setInvitedUserIds(prev => new Set(prev).add(targetUser.id));
            // Kullanıcı isteği: davet gönderilince küçük bir onay yazısı çıksın — aşağıdaki
            // "Gönderilen Davetler" listesine düştüğünü kullanıcı fark etmeyebilir.
            Alert.alert('', t.inviteSentToMsg(playerDisplayName(targetUser)));
        } catch (e) {
            Alert.alert(t.error, e?.response?.data?.message || t.actionFailed);
        } finally { setInvitingUserId(null); }
    };

    const acceptLocal = async (jrId) => {
        const prevLocalJoinRequests = joinRequests;
        setLocalJoinRequests(joinRequests.filter(r => r.id !== jrId));
        try {
            const res = await api.patch(`/rivals/join/${jrId}`, { action: 'accept' });
            // Üst listenin ne zaman/nasıl yenileneceğine bağlı kalmadan, açık modal
            // API'nin döndürdüğü güncel veriyle anında senkronize edilir — onRefresh()
            // sadece liste rozetleri/sayaçları için ayrıca çağrılmaya devam eder.
            if (res.data?.request) {
                setLocalJoinRequests(Array.isArray(res.data.request.joinRequests) ? res.data.request.joinRequests : []);
                if (Array.isArray(res.data.request.participants)) setLocalParticipants(res.data.request.participants);
                if (Array.isArray(res.data.request.unassignedPlayers)) setLocalUnassigned(res.data.request.unassignedPlayers);
                if (Array.isArray(res.data.request.senderTeam)) setLocalSenderTeam(res.data.request.senderTeam);
            }
            if (res.data?.lateAccept) {
                // İstek 1 saatten eskiyse hemen katılımcıya dönüşmez — karşı taraftan son
                // onay istenir ve bu isteği bekleyen listeden kaldırır. Bilgilendirmeden
                // sessizce kaybolursa kullanıcı "onayladım, istek kayboldu" sanır.
                Alert.alert(t.lateAcceptTitle, t.lateAcceptMsg);
                onRefresh();
            } else if (res.data?.matched) {
                setTimeout(onRefresh, 1200);
            } else {
                onRefresh();
            }
        } catch(e) {
            if (e?.response) Alert.alert(t.error, e.response.data?.message || t.actionFailed);
            setLocalJoinRequests(prevLocalJoinRequests);
            setLocalParticipants(null);
        }
    };

    const rejectLocal = (jrId) => {
        setLocalJoinRequests(joinRequests.filter(r => r.id !== jrId));
        handleRespondJoin(jrId, 'reject');
    };

    // İlan sahibinin "📨 Gönderilen Davetler"den kendi gönderdiği bir daveti ✕ ile geri
    // çekmesi — kullanıcı raporu: backend bunu her zaman "Forbidden" ile reddediyordu
    // (bkz. rival.controller.js respondToJoin, isOwnerWithdrawingOwnInvite düzeltmesi).
    // rejectLocal'dan ayrı: burada başarı sonrası açık bir onay mesajı gösteriliyor.
    const withdrawSentInvite = (jrId) => {
        setLocalJoinRequests(joinRequests.filter(r => r.id !== jrId));
        api.patch(`/rivals/join/${jrId}`, { action: 'reject' })
            .then(() => { Alert.alert('', t.inviteWithdrawnMsg); onRefresh(); })
            .catch(e => { Alert.alert(t.error, e?.response?.data?.message || t.actionFailed); onRefresh(); });
    };

    // Çiftler: kendi bireysel başvurumun partner durumunu değiştirir — davet et / kabul et / geri çek
    const setMyRivalJoinPartner = async (partnerId) => {
        setPartnerActionLoading(true);
        try {
            const { data } = await api.patch(`/rivals/${item.id}/join-partner`, { partnerId: partnerId || null });
            setLocalJoinRequests(prev => {
                const base = prev ?? joinRequests;
                return base.some(r => r.id === data.id) ? base.map(r => r.id === data.id ? { ...r, ...data } : r) : [...base, data];
            });
            setShowJoinInvitePicker(false);
        } catch (e) {
            Alert.alert('', e?.response?.data?.message || t.actionFailed);
        } finally {
            setPartnerActionLoading(false);
        }
    };

    // İlan sahibi yanlışlıkla kabul ettiği bir katılımcıyı (çiftlerde takımın tamamını) çıkarır
    const removeRivalParticipant = (participantUserId, participantName) => {
        Alert.alert(
            'Katılımcıyı Çıkar',
            `${participantName ? participantName : 'Bu kullanıcı'} maçtan çıkarılacak. Emin misiniz?`,
            [
                { text: 'Vazgeç', style: 'cancel' },
                { text: 'Çıkar', style: 'destructive', onPress: async () => {
                    try {
                        const { data } = await api.delete(`/rivals/${item.id}/participants/${participantUserId}`);
                        // Kullanıcı raporu: bu çıkarma artık atanmamış/yedek listesinden de
                        // tetiklenebiliyor (bkz. nameMenu) — önceden SADECE participants
                        // güncelleniyordu, senderTeam/unassignedPlayers'tan çıkarılan biri
                        // onRefresh() tüm listeyi yeniden çekene kadar kartta hayalet gibi
                        // görünmeye devam ediyordu.
                        if (Array.isArray(data?.request?.participants)) setLocalParticipants(data.request.participants);
                        if (Array.isArray(data?.request?.senderTeam)) setLocalSenderTeam(data.request.senderTeam);
                        if (Array.isArray(data?.request?.unassignedPlayers)) setLocalUnassigned(data.request.unassignedPlayers);
                        onRefresh();
                    } catch (e) {
                        Alert.alert('', e?.response?.data?.message || t.actionFailed);
                    }
                }},
            ]
        );
    };

    // "Atanmamış" havuzundaki (veya zaten bir tarafa atanmış) gerçek bir kullanıcıyı
    // Kurucu/Rakip'e atar/geri alır — Yaklaşan Maçlar'daki (assignPlayerToSide) ile aynı
    // uç nokta, ilan henüz MATCHED olmasa da çalışır.
    const assignUnassignedToSide = (userId, side) => {
        api.patch(`/rivals/${item.id}/assign-player`, { userId, side })
            .then(({ data }) => {
                if (Array.isArray(data?.participants)) setLocalParticipants(data.participants);
                if (Array.isArray(data?.senderTeam)) setLocalSenderTeam(data.senderTeam);
                if (Array.isArray(data?.unassignedPlayers)) setLocalUnassigned(data.unassignedPlayers);
                onRefresh();
            })
            .catch(e => Alert.alert(t.error, e?.response?.data?.message || t.actionFailed));
    };
    // Uygulamayı kullanmayan (kayıtsız, manuel isim) "Atanmamış" kişiler için — assignPlayerToSide
    // artık manualName ile de eşleştirebiliyor (bkz. backend). Önceden bu kişilere dokununca
    // hiçbir şey olmuyordu (kullanıcı raporu: "takım isimleri gelmiyor").
    const assignManualToSide = (manualName, side) => {
        api.patch(`/rivals/${item.id}/assign-player`, { manualName, side })
            .then(({ data }) => {
                if (Array.isArray(data?.participants)) setLocalParticipants(data.participants);
                if (Array.isArray(data?.senderTeam)) setLocalSenderTeam(data.senderTeam);
                if (Array.isArray(data?.unassignedPlayers)) setLocalUnassigned(data.unassignedPlayers);
                onRefresh();
            })
            .catch(e => Alert.alert(t.error, e?.response?.data?.message || t.actionFailed));
    };
    // Kullanıcı isteği: "karşıdaki oyunculardan biriyle değiştirmek isteniyorsa tüm slotlar
    // doluysa atanmamışa atıp sonra tekrar dağıtmakla uğraşmak yerine" — karşı taraf DOLUYKEN
    // doğrudan o taraftaki bir oyuncuyla yer değiştirir (ikisi de dolu kalır, kimse atanmamışa düşmez).
    const swapTeamPlayer = (mover, target) => {
        api.patch(`/rivals/${item.id}/swap-team-player`, {
            userId: mover.id || undefined, manualName: mover.id ? undefined : mover.manualName,
            swapUserId: target.id || undefined, swapManualName: target.id ? undefined : target.manualName,
        })
            .then(({ data }) => {
                if (Array.isArray(data?.participants)) setLocalParticipants(data.participants);
                if (Array.isArray(data?.senderTeam)) setLocalSenderTeam(data.senderTeam);
            })
            .catch(e => Alert.alert(t.error, e?.response?.data?.message || t.actionFailed));
    };
    // Voleybol: takım slotuna yerleşmiş bir oyuncuya ekstra pozisyon etiketi (Libero/Pasör/
    // Smaçör) atar — kullanıcı isteği: bu, ilan oluşturma formunda zaten vardı (bkz.
    // TeamSlotRow/setSlotPosition) ama sadece yerel state'ti, backend'e hiç gönderilmiyordu.
    const setParticipantPositionApi = (userId, position) => {
        api.patch(`/rivals/${item.id}/participant-position`, { userId, position })
            .then(({ data }) => {
                if (Array.isArray(data?.participants)) setLocalParticipants(data.participants);
                if (Array.isArray(data?.senderTeam)) setLocalSenderTeam(data.senderTeam);
                onRefresh();
            })
            .catch(e => Alert.alert(t.error, e?.response?.data?.message || t.actionFailed));
    };
    // Kullanıcı isteği: açık ilan detayında "Katılan Oyuncular"a girmiş (kadroda, atanmamışta
    // ya da yedekte fark etmez) bir katılımcı kendi ismine dokununca kendisi için pozisyon
    // önerebilsin — önceden bu SADECE Yaklaşan Maçlar'daki kadro kartında (TeamAssignCard) vardı.
    const suggestOwnPositionApi = (position) => {
        api.post(`/rivals/${item.id}/participant-position/suggest`, { position })
            .then(() => { Alert.alert('', t.positionSuggestionSentMsg); onRefresh(); })
            .catch(e => Alert.alert(t.error, e?.response?.data?.message || t.actionFailed));
    };
    const respondPositionSuggestionApi = (userId, action, rejectReason) => {
        api.patch(`/rivals/${item.id}/participant-position/suggest/respond`, { userId, action, rejectReason })
            .then(({ data }) => {
                if (Array.isArray(data?.participants)) setLocalParticipants(data.participants);
                if (Array.isArray(data?.senderTeam)) setLocalSenderTeam(data.senderTeam);
                if (Array.isArray(data?.unassignedPlayers)) setLocalUnassigned(data.unassignedPlayers);
                onRefresh();
            })
            .catch(e => Alert.alert(t.error, e?.response?.data?.message || t.actionFailed));
    };
    // Kadro kartının arka yüzünde dolu bir slota basınca (kullanıcı isteği: "sağında çıkar/
    // değiştir yazsın, tıklayınca küçük pencerede Çıkar / Atanmamışa Taşı çıksın"). Manuel
    // (kayıtsız) isimlerde "Çıkar" backend'de henüz desteklenmiyor (bkz. removeRivalParticipant
    // sadece gerçek userId alıyor) — onlar için sadece Atanmamışa Taşı sunulur.
    // side: bu kişinin ŞU AN hangi takımda olduğu ('my'|'opp') — kullanıcı isteği: "karşıya
    // taşımak istiyorsa karşı rakibin ismi neyse x takıma taşı seçeneği olsun, boşluk varsa".
    // Alert.alert DEĞİL SlotActionSheet kullanılıyor — Android'de Alert 3 buton sınırına
    // takılıp 4. butonu (genelde "Atanmamışa Taşı") sessizce düşürüyordu (kullanıcı raporu).
    const [slotActionTarget, setSlotActionTarget] = useState(null); // { p, side, mode } | null
    // mode: undefined/'manage' (Çıkar/Değiştir butonu), 'nameMenu' (isme dokununca: Pozisyona
    // Ata/Profiline Git), 'position' (nameMenu'den "Pozisyona Ata" seçilince açılan alt menü).
    const promptSlotAction = (p, side, mode) => setSlotActionTarget({ p, side, mode });
    // Kullanıcı raporu: "davet et" penceresini (👥 ikonu) açıp telefonun geri tuşuyla ilan
    // detayından çıkınca (Modal kapanır ama bileşen unmount OLMAZ, bkz. RivalCard'daki
    // koşullu render) tekrar aynı ilana girince pencere hâlâ açık görünüyordu — bu bileşenin
    // state'i visible=false/true arasında hep KORUNUYOR, sıfırlanmıyordu. Modal her
    // kapandığında (geri tuşu dahil, çünkü onRequestClose de aynı visible=false'a çıkıyor)
    // açık kalmış olabilecek TÜM ikincil pencere/aksiyon state'leri burada sıfırlanır.
    useEffect(() => {
        if (visible) return;
        setShowDoubleFriendsPicker(false);
        setDoubleInviteFromSlot(null);
        setSwapSlot(null);
        setTeamNameEdit(null);
        setSlotActionTarget(null);
    }, [visible]);
    // Kullanıcı raporu: "oyuncu davet et" panelini (👥 ikonu) açıp telefonun geri tuşuna
    // basınca panel kapanmak yerine doğrudan ilan detayının tamamı kapanıp açık ilanlar
    // listesine düşülüyordu. Sebep: bu panel ayrı bir <Modal> DEĞİL (yukarıdaki not — iç içe
    // Modal klavye açılınca çöküyordu), bu yüzden geri tuşu hiç yakalanmadan doğrudan dış
    // Modal'ın onRequestClose={onClose}'una gidiyordu. Panel açıkken geri tuşu önce SADECE
    // paneli kapatsın diye burada yakalanıyor (kapatma mantığı panelin ✕ butonuyla aynı).
    useEffect(() => {
        if (!visible || !inviteModalVisible) return;
        const onBackPress = () => {
            setInviteModalVisible(false);
            setInviteQuery('');
            setInviteResults([]);
            setInviteForReferee(false);
            return true;
        };
        const sub = BackHandler.addEventListener('hardwareBackPress', onBackPress);
        return () => sub.remove();
    }, [visible, inviteModalVisible]);
    const slotActionSheetProps = (() => {
        if (!slotActionTarget) return { visible: false, title: '', actions: [] };
        const { p, side, mode } = slotActionTarget;
        const name = p.id ? playerDisplayName(p) : p.manualName;
        if (mode === 'nameMenu') {
            const nameActions = [];
            // Kullanıcı isteği: "sadece isme tıklarlarsa pozisyona ata ve profiline git
            // seçenekleri çıksın" — pozisyon ataması sadece ilan sahibi + voleybolda.
            if (isOwner && sub === 'volleyball' && p.id) {
                nameActions.push({ label: `🏐 ${t.positionAssignBtn}`, onPress: () => setSlotActionTarget({ p, side, mode: 'position' }) });
            }
            if (p.id) nameActions.push({ label: `👤 ${t.goToProfileBtn}`, onPress: () => navigation.push('Profile', { userId: p.id }) });
            // Kullanıcı isteği: "katılan oyuncular listesinde ya da arka kadro kartında oyuncuya
            // tıklandığında maçtan çıkar da olsun — belki atama yapmadan, yedek listeden ya da
            // ana kadrodan çıkarmak isteyecek" — önceden bu menüde SADECE pozisyon/profil vardı,
            // çıkarma sadece arka yüzdeki ayrı "Çıkar/Değiştir" linkinde (sadece atanmış oyuncular
            // için) vardı. Kurucu (ilan sahibi) kendini buradan çıkaramaz.
            if (isOwner && sub === 'volleyball' && p.id && p.id !== item.senderId) {
                nameActions.push({ label: `🚫 ${t.removeFromMatchBtn}`, destructive: true, onPress: () => removeRivalParticipant(p.id, p.username) });
            }
            // Kullanıcı isteği: ilan sahibi olmayan bir katılımcı da "Katılan Oyuncular" listesinde
            // kendi ismine dokununca kendisi için bir pozisyon önerebilsin — ilan sahibi onaylarsa
            // gerçek pozisyona atanır, reddederse (bkz. 'suggestionReview') sebebiyle bildirim gelir.
            if (!isOwner && p.id === myId && sub === 'volleyball') {
                nameActions.push({ label: `🏐 ${t.positionSuggestBtn}`, onPress: () => setSlotActionTarget({ p, side, mode: 'suggestPosition' }) });
            }
            return { visible: true, title: name, actions: nameActions };
        }
        if (mode === 'position') {
            const posActions = [];
            if (p.position !== 'SPIKER') posActions.push({ label: `🏐 ${t.positionSpiker}`, onPress: () => setParticipantPositionApi(p.id, 'SPIKER') });
            if (p.position !== 'LIBERO') posActions.push({ label: `🙌 ${t.positionLibero}`, onPress: () => setParticipantPositionApi(p.id, 'LIBERO') });
            if (p.position !== 'SETTER') posActions.push({ label: `🎯 ${t.positionSetter}`, onPress: () => setParticipantPositionApi(p.id, 'SETTER') });
            if (p.position) posActions.push({ label: t.positionClearOption, onPress: () => setParticipantPositionApi(p.id, null) });
            return { visible: true, title: name, actions: posActions };
        }
        if (mode === 'suggestPosition') {
            const posActions = [];
            if (p.position !== 'SPIKER') posActions.push({ label: `🏐 ${t.positionSpiker}`, onPress: () => suggestOwnPositionApi('SPIKER') });
            if (p.position !== 'LIBERO') posActions.push({ label: `🙌 ${t.positionLibero}`, onPress: () => suggestOwnPositionApi('LIBERO') });
            if (p.position !== 'SETTER') posActions.push({ label: `🎯 ${t.positionSetter}`, onPress: () => suggestOwnPositionApi('SETTER') });
            return { visible: true, title: t.positionSuggestPickerTitle, actions: posActions };
        }
        // Kullanıcı isteği: ilan sahibi bekleyen bir öneriyi görünce Onayla ya da (iki hazır
        // sebepten birini seçerek) Reddet diyebilsin — reddedince seçilen sebep katılımcıya
        // bildirim olarak gider.
        if (mode === 'suggestionReview') {
            const suggestion = (Array.isArray(item.positionSuggestions) ? item.positionSuggestions : []).find(sg => sg?.userId === p.id);
            const posLabel = suggestion?.position === 'SPIKER' ? t.positionSpiker : suggestion?.position === 'LIBERO' ? t.positionLibero : t.positionSetter;
            const reviewActions = [
                { label: `✅ ${t.positionSuggestionApproveBtn} (${posLabel})`, onPress: () => respondPositionSuggestionApi(p.id, 'approve') },
                { label: `📅 ${t.positionSuggestionRejectArrangeBtn}`, onPress: () => respondPositionSuggestionApi(p.id, 'reject', 'CAN_ARRANGE_IN_MATCH') },
                { label: `🚫 ${t.positionSuggestionRejectFullBtn}`, onPress: () => respondPositionSuggestionApi(p.id, 'reject', 'POSITION_FULL') },
            ];
            return { visible: true, title: name, actions: reviewActions };
        }
        const oppositeSide = side === 'my' ? 'opp' : 'my';
        const oppositeFull = oppositeSide === 'my' ? founderFullForAssign : oppFullForAssign;
        const oppositeLabel = oppositeSide === 'my' ? (item.founderTeamName || t.myTeamLabel) : (item.opponentTeamName || t.oppTeamLabel);
        const actions = [];
        if (!oppositeFull) {
            actions.push({ label: `${oppositeLabel}'a Taşı`, onPress: () => (p.id ? assignUnassignedToSide(p.id, oppositeSide) : assignManualToSide(p.manualName, oppositeSide)) });
        } else {
            // Kullanıcı isteği: karşı taraf doluyken atanmamışa atıp sonra yeniden dağıtmakla
            // uğraşmak yerine, doğrudan karşı taraftaki bir oyuncuyla yer değiştirilebilsin.
            const oppositeRoster = oppositeSide === 'my'
                ? senderTeamArr.filter(x => x?.id || x?.manualName)
                : [...participants.filter(x => x?.id || x?.manualName), ...oppManualNames.map(n => ({ manualName: n }))];
            for (const target of oppositeRoster) {
                const targetName = target.id ? playerDisplayName(target) : target.manualName;
                actions.push({ label: `🔁 ${targetName} ile Değiş`, onPress: () => swapTeamPlayer(p, target) });
            }
        }
        actions.push({ label: 'Atanmamışa Taşı', onPress: () => (p.id ? assignUnassignedToSide(p.id, null) : assignManualToSide(p.manualName, null)) });
        if (p.id) actions.push({ label: 'Çıkar', destructive: true, onPress: () => removeRivalParticipant(p.id, p.username) });
        return { visible: true, title: name, actions };
    })();

    // Çiftler (DOUBLE): kabul edilen bireysel oyuncu atanmamış havuzuna düşer — ilan sahibi
    // herkesi, oyuncunun kendisi de (sadece kendini, atanmamışken) Takım Arkadaşı/Rakip1/
    // Rakip2'ye atayabilir.
    const assignDoubleSlot = (userId, slot) => {
        api.patch(`/rivals/${item.id}/assign-double-slot`, { userId, slot })
            .then(({ data }) => {
                if (Array.isArray(data?.participants)) setLocalParticipants(data.participants);
                if (Array.isArray(data?.senderTeam)) setLocalSenderTeam(data.senderTeam);
                if (Array.isArray(data?.unassignedPlayers)) setLocalUnassigned(data.unassignedPlayers);
                onRefresh();
            })
            .catch(e => Alert.alert(t.error, e?.response?.data?.message || t.actionFailed));
    };

    // Yedek Sayısı — ilan oluşturma formundaki subCount ile aynı alan, sadece açık
    // (henüz eşleşmemiş) ilanda kurucu değiştirebilir.
    const updateSubCount = (n) => {
        setShowSubCountPicker(false);
        api.patch(`/rivals/${item.id}`, { subCount: n })
            .then(onRefresh)
            .catch(e => Alert.alert(t.error, e?.response?.data?.message || t.actionFailed));
    };

    // Kurucu/Rakip Takım ismi kaydet — mevcut /team-name uç noktası, açık ilanda daha önce
    // hiç bağlı değildi (sadece Yaklaşan Maçlar'da vardı).
    const saveTeamNameEdit = () => {
        if (!teamNameEdit) return;
        setSavingTeamNameEdit(true);
        api.patch(`/rivals/${item.id}/team-name`, { side: teamNameEdit.side, name: teamNameEdit.value })
            .then(() => { setTeamNameEdit(null); onRefresh(); })
            .catch(e => Alert.alert('', e?.response?.data?.message || t.actionFailed))
            .finally(() => setSavingTeamNameEdit(false));
    };

    // Kadro kartının arka yüzünde boş bir slota isim yazıp doğrudan Kurucu/Rakip Takım'a
    // davet göndermek için (bkz. TeamSlotInviteField) — kabul edilince o kişi doğrudan o
    // takıma düşer, atanmamış havuzuna değil (backend: inviteToRival'daki side parametresi).
    const inviteToTeamSlot = (u, side, slotIndex) => {
        api.post(`/rivals/${item.id}/invite`, { userId: u.id, side, slotIndex })
            .then(({ data }) => {
                // Davet gönderilince "📨 Gönderilen Davetler" listesinde anında görünsün diye
                // (onRefresh() tüm listeyi yeniden çekene kadar beklemeden).
                if (Array.isArray(data?.request?.joinRequests)) setLocalJoinRequests(data.request.joinRequests);
                onRefresh();
                // Kullanıcı isteği: kadro kartındaki formadan davet gönderilince de (arama
                // penceresinden gönderilen davetle aynı şekilde) küçük bir onay yazısı çıksın.
                Alert.alert('', t.inviteSentToMsg(playerDisplayName(u)));
            })
            .catch(e => Alert.alert(t.error, e?.response?.data?.message || t.actionFailed));
    };

    // DOUBLE'da (2v2) kadro kartının arka yüzünde boş bir Partner/Rakip 1/Rakip 2 slotuna
    // isim yazıp doğrudan davet göndermek için — inviteToTeamSlot'un slot-özel karşılığı
    // (bkz. backend inviteToRival'daki isDoubleSlotInvite).
    const inviteToDoubleSlot = (u, slot) => {
        api.post(`/rivals/${item.id}/invite`, { userId: u.id, slot })
            .then(({ data }) => {
                if (Array.isArray(data?.request?.joinRequests)) setLocalJoinRequests(data.request.joinRequests);
                onRefresh();
                Alert.alert('', t.inviteSentToMsg(playerDisplayName(u)));
            })
            .catch(e => Alert.alert(t.error, e?.response?.data?.message || t.actionFailed));
    };

    // Uygulamayı kullanmayan (kayıtsız) oyuncu — sadece isim, davet/bildirim gitmez. Cinsiyet
    // de gönderiliyor ki cinsiyet dağılımı kotası (requiredMaleCount) tutarlı sayabilsin.
    const addManualPlayerToTeam = (name, side, slotIndex, gender) => {
        api.patch(`/rivals/${item.id}/add-manual-player`, { name, side, slotIndex, gender })
            .then(onRefresh)
            .catch(e => Alert.alert(t.error, e?.response?.data?.message || t.actionFailed));
    };

    const SLOT_LABELS = { partner: 'Kurucu Takımı (Partner)', opp1: 'Rakip 1', opp2: 'Rakip 2' };

    // Asıl taşıma isteğini backend'e gönderir ve İKİ dizinin de (participants +
    // senderTeam/partner) anında güncellenmesini sağlar — sadece participants
    // güncellenip senderTeam'in tam liste yenilenmesini (onRefresh) beklemesi,
    // oyuncu partner slotuna taşınınca "hiçbir şey olmadı" hissi veriyordu.
    const movePlayer = async (fromSlot, toSlot) => {
        try {
            const { data } = await api.patch(`/rivals/${item.id}/swap-positions`, { slot1: fromSlot, slot2: toSlot });
            if (Array.isArray(data.participants)) setLocalParticipants(data.participants);
            if (Array.isArray(data.senderTeam)) setLocalSenderTeam(data.senderTeam);
            onRefresh();
        } catch (e) { Alert.alert('', e?.response?.data?.message || t.actionFailed); }
    };

    // "⇄ Taşı" butonuna basılınca: hedefi belirsiz bir dokunuş beklemek yerine
    // (eskiden bu iki adımlı seç+dokun akışı güvenilir çalışmıyordu), doğrudan
    // "nereye taşınsın" diye net butonlu bir onay gösterip anında taşıyor.
    const promptMove = (fromSlot) => {
        if (!isOwner) return;
        if (item.teamFlexibility === 'STRICT') {
            Alert.alert('Takım Sabit', 'Bu ilan katı ayarlı: oyuncular başvururken seçtikleri slotta sabit kalır. Değiştirmek için o katılımcıyı çıkarıp slotu yeniden açabilirsin.');
            return;
        }
        const targets = ['partner', 'opp1', 'opp2'].filter(s => s !== fromSlot);
        Alert.alert(
            'Oyuncuyu Taşı',
            'Bu oyuncu nereye taşınsın?',
            [
                ...targets.map(s => ({ text: SLOT_LABELS[s], onPress: () => movePlayer(fromSlot, s) })),
                { text: 'Vazgeç', style: 'cancel' },
            ]
        );
    };

    // DOUBLE: iki slot arasında oyuncu taşı (seç + taşı) — eski tıkla-seç-sonra-
    // tıkla-tamamla akışı, uzun-basış kısayolu için hâlâ burada duruyor.
    const handleSlotTap = async (slot) => {
        if (!isOwner) return;
        if (item.teamFlexibility === 'STRICT') {
            Alert.alert('Takım Sabit', 'Bu ilan katı ayarlı: oyuncular başvururken seçtikleri slotta sabit kalır. Değiştirmek için o katılımcıyı çıkarıp slotu yeniden açabilirsin.');
            return;
        }
        if (!swapSlot) { setSwapSlot(slot); return; }
        if (swapSlot === slot) { setSwapSlot(null); return; }
        const s1 = swapSlot; const s2 = slot;
        setSwapSlot(null);
        movePlayer(s1, s2);
    };

    // Çiftler: eşleşmiş bir çifti ya da partner arayan bireyseli ikili kart olarak render eder
    const renderRivalDuoCard = (p1, p2, solos, byUserId) => {
        const nameOf = (jr) => jr?.user?.fullName || jr?.user?.username || '';
        const ratingOf = (jr) => jr?.user?.interests?.find(i => i.subCategory === sub)?.skillRating;
        const Half = ({ jr }) => (
            <View>
                <Text style={{ color:'#fff', fontSize:11, fontWeight:'700' }} numberOfLines={1} adjustsFontSizeToFit minimumFontScale={0.75}>{nameOf(jr)}</Text>
                <Text style={{ color: colors.textMuted, fontSize:9 }} numberOfLines={1} adjustsFontSizeToFit minimumFontScale={0.75}>{jr?.user?.username}{ratingOf(jr) != null ? `  ${starEmoji(Number(ratingOf(jr)))} ${Number(ratingOf(jr)).toFixed(2)}` : ''}{reqGenderParen(jr?.user?.gender, t.lang)}</Text>
                {jr?.createdAt && <Text style={{ color: colors.textMuted, fontSize:8 }} numberOfLines={1}>🕐 {reqTimeAgo(jr.createdAt)}</Text>}
            </View>
        );

        let slot2;
        if (p2) {
            slot2 = <Half jr={p2} />;
        } else {
            const isMine = p1.userId === myId;
            const invitedBy = solos.find(o => o.partnerId === p1.userId && o.userId !== p1.userId);
            if (p1.partnerId) {
                const target = byUserId.get(p1.partnerId);
                slot2 = (
                    <View>
                        <Text style={{ color:'#fbbf24', fontSize:9, fontWeight:'700' }} numberOfLines={1} adjustsFontSizeToFit minimumFontScale={0.75}>⏳ {nameOf(target) || '...'} (Bekliyor)</Text>
                        {isMine && (
                            <TouchableOpacity onPress={() => setMyRivalJoinPartner(null)} disabled={partnerActionLoading} style={{ marginTop:2 }}>
                                <Text style={{ color:'#f87171', fontSize:9, fontWeight:'700' }}>✕ Geri Çek</Text>
                            </TouchableOpacity>
                        )}
                    </View>
                );
            } else if (invitedBy) {
                slot2 = (
                    <View>
                        <Text style={{ color:'#4ade80', fontSize:9, fontWeight:'700' }} numberOfLines={1} adjustsFontSizeToFit minimumFontScale={0.75}>{nameOf(invitedBy)} davet etti</Text>
                        {isMine && (
                            <TouchableOpacity onPress={() => setMyRivalJoinPartner(invitedBy.userId)} disabled={partnerActionLoading} style={{ marginTop:2, backgroundColor:'#16a34a30', borderRadius:5, paddingHorizontal:3, paddingVertical:0, alignSelf:'flex-start', borderWidth:1, borderColor:'#16a34a50' }}>
                                <Text style={{ color:'#4ade80', fontSize:9, fontWeight:'700' }}>✓ Kabul Et</Text>
                            </TouchableOpacity>
                        )}
                    </View>
                );
            } else {
                slot2 = (
                    <View>
                        <Text style={{ color: colors.textMuted, fontSize:9 }} numberOfLines={1} adjustsFontSizeToFit minimumFontScale={0.75}>Partner aranıyor</Text>
                        {isMine && (
                            <TouchableOpacity
                                onPress={() => { setJoinInviteCandidates(solos.filter(s => s.userId !== myId)); setShowJoinInvitePicker(true); }}
                                disabled={partnerActionLoading}
                                style={{ marginTop:2, backgroundColor: cfg.color+'20', borderRadius:5, paddingHorizontal:3, paddingVertical:0, alignSelf:'flex-start', borderWidth:1, borderColor: cfg.color+'40' }}>
                                <Text style={{ color: cfg.color, fontSize:9, fontWeight:'700' }}>+ Davet Et</Text>
                            </TouchableOpacity>
                        )}
                    </View>
                );
            }
        }

        return (
            <View key={p1.id} style={{ width:'48%', backgroundColor:'#1e293b', borderRadius:8, borderWidth:1, borderColor: colors.border+'40', paddingVertical:3, paddingHorizontal:5, marginBottom:6 }}>
                <Half jr={p1} />
                <Text style={{ color: colors.textMuted, fontSize:10, fontWeight:'900', textAlign:'center', marginVertical:2 }}>+</Text>
                {slot2}
                {isOwner && (p1.status === 'AWAITING_JOINER_CONFIRM' || p2?.status === 'AWAITING_JOINER_CONFIRM' ? (
                    <Text style={{ color:'#fbbf24', fontSize:10, fontWeight:'700', textAlign:'center', marginTop:4 }}>⏳ Son Onay Bekleniyor</Text>
                ) : (
                    <View style={{ flexDirection:'row', gap:3, marginTop:4 }}>
                        <TouchableOpacity onPress={() => acceptLocal(p1.id)} style={{ flex:1, backgroundColor:'#16a34a30', borderRadius:5, paddingVertical:0, alignItems:'center', borderWidth:1, borderColor:'#16a34a50' }}>
                            <Text style={{ color:'#4ade80', fontSize:10, fontWeight:'700' }}>Kabul</Text>
                        </TouchableOpacity>
                        <TouchableOpacity onPress={() => rejectLocal(p1.id)} style={{ flex:1, backgroundColor:'#dc262630', borderRadius:5, paddingVertical:0, alignItems:'center', borderWidth:1, borderColor:'#dc262650' }}>
                            <Text style={{ color:'#f87171', fontSize:10, fontWeight:'700' }}>Red</Text>
                        </TouchableOpacity>
                    </View>
                ))}
            </View>
        );
    };

    const sendComment = async () => {
        // Kullanıcı isteği: "1 kez basıyorum ama yazdığımı iki defa gönderiyor" — tek dokunuş
        // bazı cihazlarda TouchableOpacity'yi iki kez tetikleyebiliyor (bkz. respondRefereeApplication'daki
        // aynı düzeltme); setSendingComment(true) React'te SENKRON işlemediği için disabled prop'u
        // ikinci tetiklemeyi önceden yakalayamıyordu. sendingComment burada da AYRICA en başta kontrol edilir.
        if (sendingComment) return;
        if (!commentText.trim()) return;
        setSendingComment(true);
        try {
            const res = await api.post(`/rivals/${item.id}/comments`, { content: commentText.trim() });
            setComments(p => [...p, res.data]);
            setCommentText('');
        } catch(e) { Alert.alert('Hata', e?.response?.data?.message || 'Yorum gönderilemedi'); }
        finally { setSendingComment(false); }
    };

    const deleteComment = async (commentId) => {
        try {
            await api.delete(`/rivals/comments/${commentId}`);
            setComments(p => p.filter(c => c.id !== commentId));
        } catch(e) { Alert.alert('Hata', e?.response?.data?.message || 'Yorum silinemedi'); }
    };

    return (
        <>
        {/* android_keyboardInputMode="adjustNothing" — Android'de bu Modal, uygulama genelindeki
            softwareKeyboardLayoutMode:"pan" ayarıyla birlikte kendi kendine de yeniden boyutlanıyordu
            (varsayılan adjustResize), bu da klavye açılınca kadro kartındaki arama önerisinin
            (TeamSlotInviteField) hemen kapanmasına/ilk dokunuşun boşa gitmesine ve altta Yorum
            yaz/Gönder çubuğunun gereksiz yukarı kayıp boş siyah alan bırakmasına sebep oluyordu
            (kullanıcı raporu) — bkz. references/ekran-guvenli-alan.md.
            (Not: "öneriye dokununca klavye açıkken davet gitmiyordu" sorunu bu ayarla değil,
            TeamSlotInviteField'ın öneri kutusunu artık focus/blur yerine text/results'a göre
            göstermesiyle çözüldü — bkz. o bileşendeki showDropdown yorumu.) */}
        <Modal visible={visible} animationType="slide" onRequestClose={onClose} android_keyboardInputMode="adjustNothing">
            <View style={{ flex:1, backgroundColor: colors.bg }}>
                {/* Header */}
                <View style={{ flexDirection:'row', alignItems:'center', paddingHorizontal:5, paddingTop: insets.top + (Platform.OS==='ios' ? 8 : 14), paddingBottom:moderateScale(14), borderBottomWidth:1, borderBottomColor: colors.border }}>
                    <TouchableOpacity onPress={onClose} style={{ marginRight:14, padding:1 }}>
                        <Text style={{ color:'#fff', fontSize:moderateScale(22), fontWeight:'300' }}>←</Text>
                    </TouchableOpacity>
                    <View style={{ flex:1 }}>
                        <Text style={{ color:'#fff', fontSize:moderateScale(16), fontWeight:'800' }}>{getSubCategoryLabel(item.subCategory, t.lang)}</Text>
                        <Text style={{ color: colors.textMuted, fontSize:moderateScale(12), marginTop:1 }}>{senderAlias(item.sender)}</Text>
                    </View>
                </View>

                {/* Scrollable content */}
                {/* maintainVisibleContentPosition: demo başvuru/yeni katılım gibi anlık güncellemeler
                    görünür alanın ÜSTÜNDEKİ içeriğin (İstekler listesi, kadro kartı vb.) boyutunu
                    değiştirince, kullanıcı hâlâ aynı yeri okurken ekran alakasız bir yere kayıyordu
                    (kullanıcı raporu: "yukarı kayıyor ne alaka") — bu prop kaydırma konumunu korur. */}
                <ScrollView style={{ flex:1 }} contentContainerStyle={{ paddingHorizontal:5, paddingTop:13, paddingBottom:5 }} showsVerticalScrollIndicator={false} keyboardShouldPersistTaps="always" maintainVisibleContentPosition={{ minIndexForVisible: 0 }}>

                    {/* Kurucu (sol) + Tarih/Saat/Kort/Fiyat (sağ, küçük) — tek satırda */}
                    <View style={{ flexDirection:'row', alignItems:'flex-start', gap:moderateScale(8), marginBottom:item.message ? 8 : 12, paddingBottom:9, borderBottomWidth:1, borderBottomColor: colors.border }}>
                        {/* Sol: kurucu */}
                        <View style={{ flex:1, flexDirection:'row', alignItems:'center', gap:moderateScale(8), minWidth:0 }}>
                            <Avatar name={item.sender?.username} avatar={item.sender?.avatar} size={moderateScale(34)} color={cfg.color} onPress={() => item.senderId && navigation.push('Profile', { userId: item.senderId })} />
                            <View style={{ flex:1, minWidth:0 }}>
                                <View style={{ flexDirection:'row', alignItems:'center', gap:3, flexWrap:'wrap' }}>
                                    <Text style={[s.cardName, { fontSize: moderateScale(13) }]} numberOfLines={1} adjustsFontSizeToFit minimumFontScale={0.75}>{senderAlias(item.sender)}</Text>
                                    {item.sender?.gender && item.sender.gender !== 'OTHER' && (
                                        <Text style={{ fontSize: moderateScale(11), fontWeight:'700', color: item.sender.gender === 'MALE' ? '#3b82f6' : '#ec4899' }}>
                                            {item.sender.gender === 'MALE' ? '♂' : '♀'}
                                        </Text>
                                    )}
                                </View>
                                {item.sender?.interests?.[0]?.assessmentCompleted && (
                                    <Text style={{ color:'#facc15', fontSize:moderateScale(11), fontWeight:'800' }}>{Number(item.sender.interests[0].skillRating).toFixed(2)} ★</Text>
                                )}
                                {/* Kullanıcı isteği: kart'ta (RivalCard) zaten gösterilen tüm bilgiler
                                    (cinsiyet kısıtlaması, derece aralığı, iptal cezası, kort/salon
                                    rezerve durumu) detay ekranında da alt alta görünsün — öncesinde
                                    bunların çoğu sadece kartta vardı, detayda eksikti. Takım büyüklüğü
                                    formatı (2v2/6v6) artık burada değil, sağdaki mod rozetinin yanında
                                    (bkz. aşağıdaki ModeBadge) — "Rekabetçi 2v2" gibi aynı satırda. */}
                                {item.genderReq && item.genderReq !== 'MIX' && (
                                    <View style={{ flexDirection:'row', marginTop:3 }}>
                                        <View style={{ backgroundColor: item.genderReq === 'MALE' ? '#3b82f620' : '#ec489920', borderColor: item.genderReq === 'MALE' ? '#3b82f6' : '#ec4899', borderWidth:1, borderRadius: moderateScale(8), paddingHorizontal: moderateScale(5), paddingVertical: moderateScale(2) }}>
                                            <Text style={{ color: item.genderReq === 'MALE' ? '#3b82f6' : '#ec4899', fontSize: moderateScale(9), fontWeight:'800' }}>
                                                {item.genderReq === 'MALE' ? '👨' : '👩'}
                                            </Text>
                                        </View>
                                    </View>
                                )}
                                {item.matchType === 'DOUBLE' && (item.partnerGenderReq !== 'MIX' || item.opp1GenderReq !== 'MIX' || item.opp2GenderReq !== 'MIX') && (() => {
                                    const gL = (g) => g === 'MALE' ? '♂' : g === 'FEMALE' ? '♀' : '⚥';
                                    // Kullanıcı isteği: ilanı açan kişinin (kurucu) GERÇEK cinsiyeti de
                                    // eklendi — 2v2'de 4 kişi olduğu için 4 emoji gösterilmesi lazım,
                                    // önceden sadece 3 slotun (partner/rakip1/rakip2) kısıtlaması
                                    // gösteriliyordu, kurucunun kendisi hiç yoktu. Bu yüzden "hepsi aynı"
                                    // durumunda tek sembole sıkıştırma da kaldırıldı — kurucu her zaman
                                    // ayrı bir sembol olarak sayılır. "+" ayırıcılar kaldırıldı (kullanıcı
                                    // ekran görüntüsü: 4 sembol + 3 "+" dar sol sütuna sığmayıp rozet 2
                                    // satıra bölünüyor, üstteki bilgiler kayıyormuş gibi görünüyordu) —
                                    // RivalCard'daki (liste kartı) aynı rozetle TUTARLI, o zaten "+" kullanmıyor.
                                    const label = `${gL(item.sender?.gender)}${gL(item.partnerGenderReq)}${gL(item.opp1GenderReq)}${gL(item.opp2GenderReq)}`;
                                    return (
                                        <View style={{ flexDirection:'row', marginTop:3 }}>
                                            <View style={{ backgroundColor:'#a855f715', borderColor:'#a855f740', borderWidth:1, borderRadius: moderateScale(8), paddingHorizontal: moderateScale(5), paddingVertical: moderateScale(2) }}>
                                                <Text style={{ color:'#a855f7', fontSize: moderateScale(9), fontWeight:'800' }} numberOfLines={1}>{label}</Text>
                                            </View>
                                        </View>
                                    );
                                })()}
                                {item.subCategory === 'volleyball' && item.teamSize > 1 && hasGenderCountInfo(item) && (
                                    <Text style={{ color:'#a855f7', fontSize:moderateScale(10), fontWeight:'700', marginTop:3 }}>
                                        {genderCountDisplayLabel(item)}
                                    </Text>
                                )}
                                {(() => {
                                    const hasRatingRange = item.ratingGenderSplit
                                        ? (item.minRatingMale != null || item.maxRatingMale != null || item.minRatingFemale != null || item.maxRatingFemale != null)
                                        : (item.minRating != null || item.maxRating != null);
                                    if (!hasRatingRange) return null;
                                    return (
                                        <Text style={{ color:'#facc15', fontSize:moderateScale(10), fontWeight:'700', marginTop:3 }}>
                                            {item.ratingGenderSplit
                                                ? `⭐ 👨${item.minRatingMale ?? 0}-${item.maxRatingMale ?? 5}  👩${item.minRatingFemale ?? 0}-${item.maxRatingFemale ?? 5}`
                                                : `⭐ ${item.minRating ?? '0'}–${item.maxRating ?? '5'}`}
                                        </Text>
                                    );
                                })()}
                                {item.subCategory === 'volleyball' && item.cancelPenaltyHours != null && (
                                    <Text style={{ color:'#f87171', fontSize:moderateScale(10), fontWeight:'700', marginTop:3 }} numberOfLines={1} adjustsFontSizeToFit minimumFontScale={0.75}>
                                        {t.cancelPenaltyBadge(item.cancelPenaltyHours)}
                                    </Text>
                                )}
                                <Text style={{ fontSize:moderateScale(10), fontWeight:'700', marginTop:3, color: item.isCourtReserved ? '#4ade80' : '#f87171' }} numberOfLines={1}>
                                    {item.isCourtReserved
                                        ? `${sub === 'volleyball' ? '' : '✅ '}${sub === 'volleyball' ? t.volleyballHallReservedLabel : t.courtReservedLabel}`
                                        : `${sub === 'volleyball' ? '' : '❌ '}${t.courtNotReserved}`}
                                </Text>
                            </View>
                        </View>

                        {/* Sağ: mod + tarih/saat/kort/fiyat — küçük, sola yaslı */}
                        <View style={{ flex:1.1, alignItems:'flex-start', gap:3, minWidth:0 }}>
                            {/* Kullanıcı isteği: takım büyüklüğü/format rozeti (2v2/6v6) artık ayrı bir
                                satırda değil, mod rozetinin (Rekabetçi/Antrenman) hemen sağında, aynı
                                satırda — "Rekabetçi 2v2" gibi. */}
                            <View style={{ flexDirection:'row', alignItems:'center', gap:4, flexWrap:'wrap' }}>
                                <ModeBadge mode={item.matchMode} />
                                <View style={[s.modeBadge, { backgroundColor:cfg.color+'20', borderColor:cfg.color+'40', borderRadius: moderateScale(8), paddingHorizontal: moderateScale(6), paddingVertical: moderateScale(2) }]}>
                                    <Text style={[s.modeBadgeText, { color:cfg.color, fontSize: moderateScale(9) }]}>
                                        {TEAM_SPORTS.has(sub) ? `${item.teamSize||1}v${item.teamSize||1}` : (item.matchType==='DOUBLE' ? '2v2' : '1v1')}
                                    </Text>
                                </View>
                            </View>
                            {item.matchDate && (
                                <Text style={{ color:'#fff', fontSize:moderateScale(11), fontWeight:'700' }} numberOfLines={2}>
                                    📅 {new Date(item.matchDate).toLocaleDateString(t.dateLocale, { day:'numeric', month:'long', weekday:'long' })}
                                </Text>
                            )}
                            {(item.matchTime || item.duration) && (
                                <Text style={{ color: cfg.color, fontSize:moderateScale(11), fontWeight:'700' }} numberOfLines={1}>
                                    {item.matchTime ? `🕐 ${item.matchTime}${item.duration ? (() => { const [h,m]=item.matchTime.split(':').map(Number); const tot=h*60+m+parseInt(item.duration); return `–${String(Math.floor(tot/60)%24).padStart(2,'0')}:${String(tot%60).padStart(2,'0')}`; })() : ''}` : `⏱ ${item.duration} ${t.timeMinSuffix}`}
                                </Text>
                            )}
                            {item.subCategory === 'volleyball' && !!VOLLEYBALL_SURFACES.find(v => v.id === item.surface) && (
                                <Text style={{ color: colors.textMuted, fontSize:moderateScale(10), fontWeight:'700' }} numberOfLines={1}>
                                    {(() => { const v = VOLLEYBALL_SURFACES.find(v => v.id === item.surface); return `${v.emoji} ${t.lang === 'tr' ? v.label : v.labelEn}`; })()}
                                </Text>
                            )}
                            {item.courtName && (
                                <TouchableOpacity onPress={() => openCourtMap(item.courtName, item.courtLat, item.courtLng, item.courtAddress)} style={{ maxWidth:'100%' }}>
                                    <Text style={{ color:'#60a5fa', fontSize:moderateScale(10), textDecorationLine:'underline' }} numberOfLines={2}>🏟️ {item.courtName}</Text>
                                </TouchableOpacity>
                            )}
                            {item.courtFeePerPerson > 0 && (
                                <Text style={{ color:'#4ade80', fontSize:moderateScale(10) }} numberOfLines={1} adjustsFontSizeToFit minimumFontScale={0.75}>
                                    💰 {item.courtFeePerPerson}{item.refereeFeePerPerson > 0 ? `+${item.refereeFeePerPerson}` : ''}₺{item.refereeRequested && !item.refereeFeePerPerson && !item.refereeFeeIncluded ? ` +${t.refereeFeeHint}` : ''}/{t.perPerson}
                                </Text>
                            )}
                            {/* Kullanıcı isteği: tek satırda " · " ile ayrılmış hali (EFT/Nakit/Online/Kredi
                                Kartı) dar kolona sığmıyordu — her yöntem kendi satırında, hepsi aynı sol
                                kenardan başlayarak alt alta listeleniyor. */}
                            {feeByMethodEntries(item.courtFeePerPersonByMethod).length > 0 && (
                                <View>
                                    {feeByMethodEntries(item.courtFeePerPersonByMethod).map(([k, v]) => (
                                        <Text key={k} style={{ color:'#86efac', fontSize:moderateScale(9) }} numberOfLines={1}>
                                            {FEE_METHOD_LABEL[k] || k}: {v}₺
                                        </Text>
                                    ))}
                                </View>
                            )}
                            {item.level && (
                                <Text style={[s.levelBadge, { borderRadius: moderateScale(8), paddingHorizontal: moderateScale(6), paddingVertical: moderateScale(2), fontSize: moderateScale(9) }]} numberOfLines={1}>{LEVEL_EMOJI[item.level]} {t.levelTr[item.level] || item.level}</Text>
                            )}
                        </View>
                    </View>
                    {/* Oyuncular — kullanıcı isteği: Kurucu/Rakip Takım kadro kartını saran bu
                        bölümün sağ/sol iç boşluğu daraltıldı (Kurucu Takım biraz sola, Rakip
                        Takım biraz sağa yaklaşsın diye) — üst/alt det.section'daki gibi kalıyor. */}
                    <View style={[det.section, { paddingHorizontal:1 }]}>
                        <View style={{ flexDirection:'row', alignItems:'center', justifyContent:'space-between' }}>
                            <Text style={det.sectionTitle}>
                                {/* Digimon kartlı (DOUBLE veya takım büyüklüğü >1 — voleybol vb.)
                                    ilanlarda diğer kadro kartlarıyla (CreateRivalModal/UpcomingCard)
                                    tutarlı olsun diye "Oyuncular" yerine "Katılan Oyuncular"
                                    (kullanıcı isteği: voleybolda da aynı etiket kullanılsın). */}
                                👥 {(item.matchType === 'DOUBLE' || item.matchType === 'SINGLE' || (item.teamSize || 1) > 1) ? t.rosterPoolLabel : (t.players || 'Oyuncular')} {isRefereeAd && item.linkedRival
                                    ? `(${linkedSenderSideCount + linkedFilled} / ${linkedTotalCapacity})`
                                    /* Kullanıcı isteği: DOUBLE'da kabul edilip henüz Takım Arkadaşı/Rakip1/
                                       Rakip2'ye atanmamış oyuncular ("atanmamış havuzu") artık ön yüzde
                                       sıradaki Katılımcı N olarak sayılıyor — önceden bu sayaç DOUBLE'da
                                       unassignedSlots'u hiç eklemiyordu (0 sabitti), bu yüzden atanmamış
                                       biri varken bile toplam "(1/4)" gibi eksik gösteriyordu. */
                                    : `(${senderSideCount + filled + unassignedSlots.length + (item.matchType === 'DOUBLE' ? 0 : oppManualNames.length)} / ${totalCapacity})`}
                            </Text>
                            {/* isOwner/isParticipant'a ek olarak highlightSlot.doubleSlot da butonu açık tutar —
                                bir DOUBLE forma davetiyle (bildirimden) gelen kişi henüz participants
                                listesinde değil (daveti kabul etmedi), önceden bu yüzden buton hiç
                                görünmüyordu ve "dıgımon kart olarak görmüyor" şikayetine yol açıyordu. */}
                            {item.matchType === 'DOUBLE' && (isOwner || isParticipant || !!highlightSlot?.doubleSlot) && showTeamCards && (
                                <TouchableOpacity onPress={() => { cancelHighlightSequence(); toggleTeamCards(false); }} style={{ backgroundColor:'#ffffff10', borderRadius:8, paddingHorizontal:10, paddingVertical:6, borderWidth:1, borderColor:'#ffffff20' }}>
                                    <Text style={{ color: cfg.color, fontSize:11, fontWeight:'700' }}>🔄 Çevir</Text>
                                </TouchableOpacity>
                            )}
                            {/* Voleyboldeki (teamSize>1) çevirme butonu kimse katılmasa da hep görünür —
                                DOUBLE'da eskiden en az bir katılımcı kabul edilmiş olması şart koşuluyordu,
                                bu da henüz kimsenin katılmadığı yeni bir ilanda butonun hiç çıkmamasına
                                (kullanıcı "digimon kart nerede" diye şaşırmasına) yol açıyordu. */}
                            {item.matchType === 'DOUBLE' && (isOwner || isParticipant || !!highlightSlot?.doubleSlot) && !showTeamCards && (isOwner ? item.teamFlexibility !== 'STRICT' : true) && (
                                <TouchableOpacity onPress={() => { cancelHighlightSequence(); toggleTeamCards(true); }} style={{ backgroundColor:'#ffffff10', borderRadius:8, paddingHorizontal:10, paddingVertical:6, borderWidth:1, borderColor:'#ffffff20', position:'relative' }}>
                                    <Text style={{ color: cfg.color, fontSize:11, fontWeight:'700' }}>🗂️ {isOwner ? 'Takımları Düzenle' : 'Takımları Gör'}</Text>
                                    {flipHintActive && (
                                        <Animated.View style={{ position:'absolute', top:-3, right:-3, width:9, height:9, borderRadius:5, backgroundColor:'#ef4444', opacity: highlightPulse }} />
                                    )}
                                </TouchableOpacity>
                            )}
                            {/* Takım sporlarında (voleybol) VE tekler (SINGLE, 1v1) kadro kartı — ilan
                                oluşturma ekranındaki aynı çevirmeli kart: takım sporunda ön yüz 3'lü grid
                                havuz + yedekler/arka yüz Kurucu/Rakip Takımı, teklerde ön yüz "Katılan
                                Oyuncular" (2 kişi)/arka yüz Kurucu/Rakip. Kullanıcı raporu: "1v1 açık
                                ilanlarda da yaklaşan maçlarda da dıgımon kart yok" — SINGLE bu koşuldan
                                (senderTeamArr/teamSize sadece takım sporlarında dolu olur) hariç
                                tutuluyordu, hiç flip butonu çıkmıyordu. Aynı showTeamCards/cardRotateY
                                state'i (DOUBLE'da kullanılanla aynı) burada da ön/arka geçişi için kullanılıyor. */}
                            {item.matchType !== 'DOUBLE' && !isRefereeAd && (item.matchType === 'SINGLE' || senderTeamArr.length > 0 || (item.teamSize || 1) > 1) && (
                                <TouchableOpacity onPress={() => { cancelHighlightSequence(); toggleTeamCards(!showTeamCards); }} style={{ backgroundColor:'#ffffff10', borderRadius:8, paddingHorizontal:10, paddingVertical:6, borderWidth:1, borderColor:'#ffffff20', position:'relative' }}>
                                    <Text style={{ color: cfg.color, fontSize:13, fontWeight:'700' }}>🔄</Text>
                                    {/* Otomatik çevirme dizisi bitip önde kalınca, arkada bir davet vurgusu
                                        olduğunu unutmasın diye butonda yanıp sönen küçük bir rozet bırakılır. */}
                                    {flipHintActive && (
                                        <Animated.View style={{ position:'absolute', top:-3, right:-3, width:9, height:9, borderRadius:5, backgroundColor: cfg.color, opacity: highlightPulse }} />
                                    )}
                                </TouchableOpacity>
                            )}
                        </View>
                        <Animated.View style={{ transform: [{ perspective: 800 }, { rotateY: cardRotateY }] }}>
                        {isRefereeAd && item.linkedRival ? (
                            <>
                                <View style={det.playerRow}>
                                    <Avatar name={item.linkedRival.sender?.username} avatar={item.linkedRival.sender?.avatar} size={moderateScale(32)} color={cfg.color} onPress={() => item.linkedRival.senderId && navigation.push('Profile', { userId: item.linkedRival.senderId })} />
                                    <View style={{ flex:1 }}>
                                        <Text style={det.playerName}>{playerDisplayName(item.linkedRival.sender)}</Text>
                                        <Text style={det.playerSub}>{item.linkedRival.sender?.username} · {t.founder || 'Kurucu'}</Text>
                                    </View>
                                </View>
                                {[...linkedSenderTeam, ...linkedParticipants].filter(p => p?.id).map((p, i) => (
                                    <View key={p.id || i} style={det.playerRow}>
                                        <Avatar name={p.username} avatar={p.avatar} size={moderateScale(32)} color={cfg.color} onPress={() => p.id && navigation.push('Profile', { userId: p.id })} />
                                        <View style={{ flex:1 }}>
                                            <Text style={det.playerName}>{playerDisplayName(p)}</Text>
                                            <Text style={det.playerSub}>{p.username}</Text>
                                        </View>
                                    </View>
                                ))}
                                {Array.from({ length: Math.max(0, linkedRequired - linkedFilled) }).map((_, i) => (
                                    <View key={`empty-${i}`} style={[det.playerRow, { opacity:0.55 }]}>
                                        <View style={{ width:moderateScale(32), height:moderateScale(32), borderRadius:moderateScale(16), borderWidth:1, borderStyle:'dashed', borderColor: colors.textMuted, alignItems:'center', justifyContent:'center' }}>
                                            <Text style={{ color: colors.textMuted, fontSize:14 }}>?</Text>
                                        </View>
                                        <View style={{ flex:1 }}>
                                            <Text style={[det.playerSub, { color: colors.textMuted }]}>Bekleniyor</Text>
                                        </View>
                                    </View>
                                ))}
                                <View style={[det.playerRow, { marginTop:4, borderTopWidth:1, borderTopColor: colors.border, paddingTop:8 }]}>
                                    {item.refereeUser ? (
                                        <>
                                            <Avatar name={item.refereeUser.username} avatar={item.refereeUser.avatar} size={moderateScale(32)} color={'#f59e0b'} onPress={() => navigation.push('Profile', { userId: item.refereeUser.id })} />
                                            <View style={{ flex:1 }}>
                                                <Text style={det.playerName}>{playerDisplayName(item.refereeUser)}</Text>
                                                <Text style={{ color:'#f59e0b', fontSize:moderateScale(11), fontWeight:'700' }}>🧑‍⚖️ Hakem</Text>
                                            </View>
                                        </>
                                    ) : item.manualRefereeName ? (
                                        <>
                                            <View style={{ width:moderateScale(32), height:moderateScale(32), borderRadius:moderateScale(16), backgroundColor:'#f59e0b20', alignItems:'center', justifyContent:'center' }}>
                                                <Text style={{ fontSize:14 }}>🧑‍⚖️</Text>
                                            </View>
                                            <View style={{ flex:1 }}>
                                                <Text style={det.playerName}>{item.manualRefereeName}</Text>
                                                <Text style={{ color:'#f59e0b', fontSize:moderateScale(11), fontWeight:'700' }}>🧑‍⚖️ Hakem</Text>
                                            </View>
                                        </>
                                    ) : (
                                        <>
                                            <View style={{ width:moderateScale(32), height:moderateScale(32), borderRadius:moderateScale(16), borderWidth:1, borderStyle:'dashed', borderColor:'#f59e0b', alignItems:'center', justifyContent:'center' }}>
                                                <Text style={{ fontSize:14 }}>🧑‍⚖️</Text>
                                            </View>
                                            <View style={{ flex:1 }}>
                                                {/* Kendi başvurusu bekleyen/karşı teklif almış görüntüleyici bunu genel
                                                    "Hakem — Bekleniyor" yerine kendi durumu olarak görsün. */}
                                                <Text style={[det.playerSub, { color:'#f59e0b' }]}>
                                                    {mySentReq === 'PENDING' ? 'İsteğiniz Bekleniyor'
                                                        : mySentReq === 'COUNTERED' ? 'Karşı Teklif Aldınız'
                                                        : 'Hakem — Bekleniyor'}
                                                </Text>
                                            </View>
                                        </>
                                    )}
                                </View>
                            </>
                        ) : item.matchType === 'DOUBLE' ? (() => {

                            // Slot kutusu: seçiliyse altın border, doluysa dokunulabilir
                            const SlotBox = ({ slot, gReqLabel, gReqValue, p, fallback, onRemove, locked, highlighted }) => {
                                // Kullanıcı isteği: bekleyen bir davet artık kartın İÇİNDE (ne ön ne arka
                                // yüzde) hiçbir şekilde gösterilmiyor — slot dolu görünmemeli, "davet
                                // edildiniz" kutusu da içermemeli. Davetin kime/hangi role gittiği ve
                                // kabul/red işlemi SADECE aşağıdaki "📨 Gönderilen Davetler" listesinden
                                // yapılır (bkz. o bölümdeki myInvite satırı). Kabul edilince kişi zaten
                                // backend'in doğru yerine (isPartnerInvite→senderTeam, requestedSlot
                                // varsa o participants index'i, yoksa unassignedPlayers) yerleşiyor ve
                                // ön yüzde onay sırasına göre, arka yüzde de o role göre görünüyor.
                                // Boş forma + sahip + aktif takas yoksa: voleybolün Digimon kartındaki gibi
                                // doğrudan formanın içinde arama/davet (kullanıcı isteği: "voleyboldeki
                                // mantığı yap"). Dıştaki TouchableOpacity'nin İÇİNE gömülmez — TextInput'un
                                // odaklanma/dokunma davranışıyla çakışır, bu yüzden erken ayrı render edilir.
                                if (!p && !locked && isOwner && !swapSlot) {
                                    return (
                                        <View>
                                            {gReqLabel && <Text style={{ color:'#a855f7', fontSize:8, fontWeight:'700', marginBottom:1 }}>{gReqLabel}</Text>}
                                            <TeamSlotInviteField sub={sub} category={item.category} cfg={cfg} t={t} placeholder={fallback}
                                                genderReq={gReqValue}
                                                onInvite={(u) => inviteToDoubleSlot(u, slot)}
                                                onOpenPicker={() => { setDoubleInviteFromSlot(slot); setShowDoubleFriendsPicker(true); }} />
                                        </View>
                                    );
                                }
                                // Boş forma + ben sahibi değilim + henüz başvurmadım/katılmadım + cinsiyetim
                                // bu slota uyuyor: kullanıcı isteği — "ilana başvurucak kişi direk slot
                                // seçerekde başvurabilir takım kısmından" — kadro kartındaki bu formaya
                                // dokunarak doğrudan O SLOTA başvurabilsin (bkz. backend sendJoinRequest'teki
                                // requestedSlot artık FLEXIBLE ilanlarda da opsiyonel olarak kabul ediliyor).
                                if (!p && !locked && !isOwner && !isParticipant && mySentReq == null && item.status === 'OPEN' && genderFitsSlot(myGender, gReqValue)) {
                                    return (
                                        <View>
                                            {gReqLabel && <Text style={{ color:'#a855f7', fontSize:8, fontWeight:'700', marginBottom:1 }}>{gReqLabel}</Text>}
                                            <TouchableOpacity onPress={() => handleJoin(slot)}
                                                style={{ borderWidth:1, borderStyle:'dashed', borderColor: cfg.color+'70', borderRadius:8, paddingVertical:6, alignItems:'center', backgroundColor: cfg.color+'10' }}>
                                                <Text style={{ color: cfg.color, fontSize:10, fontWeight:'700' }} numberOfLines={1}>{t.applyForSlotBtn}</Text>
                                            </TouchableOpacity>
                                        </View>
                                    );
                                }
                                const isSelected = swapSlot === slot;
                                // Hedef slot boş da olabilir — o zaman oyuncu oraya taşınır (swap değil, move).
                                const isTarget   = !!swapSlot && !locked && swapSlot !== slot;
                                const borderColor = isSelected ? '#f59e0b' : isTarget ? '#a855f7' : colors.border + '40';
                                const bg = isSelected ? '#f59e0b18' : isTarget ? '#a855f710' : undefined;
                                return (
                                    <TouchableOpacity
                                        onPress={() => { if (!locked && isOwner && swapSlot) handleSlotTap(slot); }}
                                        onLongPress={() => { if (!locked && p && isOwner && !swapSlot) handleSlotTap(slot); }}
                                        delayLongPress={300}
                                        hitSlop={{ top: 6, bottom: 6, left: 6, right: 6 }}
                                        activeOpacity={locked || !isOwner || (!p && !isTarget) ? 1 : 0.7}
                                        style={{ borderWidth: isSelected || isTarget ? 1.5 : 0, borderColor, borderRadius:6, padding:4, backgroundColor: bg }}
                                    >
                                        {gReqLabel && <Text style={{ color:'#a855f7', fontSize:8, fontWeight:'700', marginBottom:1 }}>{gReqLabel}</Text>}
                                        {p ? (
                                            <View>
                                                <View style={{ flexDirection:'row', alignItems:'center', justifyContent:'space-between' }}>
                                                    {/* Taşıma sırasında (swapSlot dolu) bu iç görünüm dokunulabilir DEĞİL —
                                                        aksi halde isim/kullanıcı adına dokunuş dıştaki "hedefe taşı"
                                                        onPress'ini hiç tetiklemeden yutuluyordu (iç içe TouchableOpacity). */}
                                                    {swapSlot ? (
                                                        <View style={{ flex:1 }}>
                                                            <Text style={{ color:'#fff', fontSize:11, fontWeight:'700' }} numberOfLines={1} adjustsFontSizeToFit minimumFontScale={0.75}>
                                                                {playerDisplayName(p)}
                                                                {(p.gender === 'MALE' || p.gender === 'FEMALE') && (
                                                                    <Text style={{ color: colors.textMuted, fontWeight:'400' }}> ({p.gender === 'MALE' ? t.genderMaleShort : t.genderFemaleShort})</Text>
                                                                )}
                                                            </Text>
                                                            <Text style={{ color: colors.textMuted, fontSize:9 }} numberOfLines={1} adjustsFontSizeToFit minimumFontScale={0.75}>
                                                                {p.username}
                                                                {p.skillRating != null && <Text style={{ color:'#facc15', fontWeight:'800' }}>  {Number(p.skillRating).toFixed(2)}★</Text>}
                                                            </Text>
                                                        </View>
                                                    ) : (
                                                        <TouchableOpacity onPress={() => p.id && navigation.push('Profile', { userId: p.id })} style={{ flex:1 }}>
                                                            <Text style={{ color:'#fff', fontSize:11, fontWeight:'700' }} numberOfLines={1} adjustsFontSizeToFit minimumFontScale={0.75}>
                                                                {playerDisplayName(p)}
                                                                {(p.gender === 'MALE' || p.gender === 'FEMALE') && (
                                                                    <Text style={{ color: colors.textMuted, fontWeight:'400' }}> ({p.gender === 'MALE' ? t.genderMaleShort : t.genderFemaleShort})</Text>
                                                                )}
                                                            </Text>
                                                            <Text style={{ color: colors.textMuted, fontSize:9 }} numberOfLines={1} adjustsFontSizeToFit minimumFontScale={0.75}>
                                                                {p.username}
                                                                {p.skillRating != null && <Text style={{ color:'#facc15', fontWeight:'800' }}>  {Number(p.skillRating).toFixed(2)}★</Text>}
                                                            </Text>
                                                        </TouchableOpacity>
                                                    )}
                                                    {isSelected && <Text style={{ color:'#f59e0b', fontSize:10, fontWeight:'900', marginLeft:4 }}>✓</Text>}
                                                    {isTarget  && <Text style={{ color:'#a855f7', fontSize:10, fontWeight:'900', marginLeft:4 }}>⇄</Text>}
                                                </View>
                                                {!locked && isOwner && !swapSlot && (onRemove || item.teamFlexibility !== 'STRICT') && (
                                                    <View style={{ flexDirection:'row', gap:8, marginTop:2 }}>
                                                        {item.teamFlexibility !== 'STRICT' && (
                                                            <TouchableOpacity onPress={() => promptMove(slot)}>
                                                                <Text style={{ color:'#f59e0b', fontSize:9, fontWeight:'700' }}>⇄ Taşı</Text>
                                                            </TouchableOpacity>
                                                        )}
                                                        {onRemove && (
                                                            <TouchableOpacity onPress={onRemove}>
                                                                <Text style={{ color:'#f87171', fontSize:9, fontWeight:'700' }}>Çıkar</Text>
                                                            </TouchableOpacity>
                                                        )}
                                                    </View>
                                                )}
                                            </View>
                                        ) : highlighted ? (
                                            // Kullanıcı raporu: bu boş forma için bekleyen bir davetim varsa
                                            // (bildirimden tıklayınca ya da ilana kendim girince) yanıp sönen
                                            // bir işaretle vurgulanması gerekiyordu — "highlighted" prop'u
                                            // taşınıyordu ama burada hiç kullanılmadığı için görsel etki
                                            // tamamen kayboluyordu. İsim/"Onay Bekleniyor" GÖSTERİLMİYOR
                                            // (yukarıdaki yorumdaki kural korunuyor, slot dolu görünmemeli) —
                                            // sadece hangi boş formanın kendisine ait olduğu yanıp söner.
                                            <Animated.View style={{ flexDirection:'row', alignItems:'center', gap:4, opacity: highlightPulse }}>
                                                <Text style={{ fontSize:12 }}>👉</Text>
                                                <Text style={{ color: cfg.color, fontSize:9, fontWeight:'800', flex:1 }}>{fallback}</Text>
                                            </Animated.View>
                                        ) : (
                                            <View style={{ flexDirection:'row', alignItems:'center', justifyContent:'space-between' }}>
                                                <Text style={{ color: isTarget ? '#a855f7' : colors.textMuted, fontSize:9, fontWeight: isTarget ? '700' : '400' }}>{fallback}</Text>
                                                {isTarget && <Text style={{ color:'#a855f7', fontSize:10, fontWeight:'900', marginLeft:4 }}>⇄</Text>}
                                            </View>
                                        )}
                                    </TouchableOpacity>
                                );
                            };

                            const PartnerContent = senderTeamArr[0] || null;

                            // Kabul edilmiş katılımcılar (kurucu hariç) — henüz Partner/Rakip 1/
                            // Rakip 2 kartlarına atanmış gibi değil, sırayla numaralı gösterilir.
                            // Her slotun kendi cinsiyet gereksinimi (varsa) etiketle birlikte taşınır.
                            const gParen = (g) => g === 'MALE' ? ' (Erkek)' : g === 'FEMALE' ? ' (Kadın)' : '';
                            const allTeamSlots = [
                                { key: 'partner', p: PartnerContent, gReq: partnerGenderReq },
                                { key: 'opp1', p: participants[0], gReq: opp1GenderReq },
                                { key: 'opp2', p: participants[1], gReq: opp2GenderReq },
                            ];
                            const teamSlots = allTeamSlots.filter(sl => sl.p?.id);
                            const acceptedOthers = teamSlots.map(sl => sl.p);
                            const unassignedDoubleSlots = unassignedArr.filter(p => p?.id);
                            // Kullanıcı isteği: ön yüzde artık sabit slot sırası (partner/opp1/opp2)
                            // yerine gerçekten katılmış (dolu) formalar önce, boş/bekleyen formalar
                            // sonra gösteriliyor — her slotun farklı cinsiyet kısıtlaması olduğunda
                            // sabit sıra "cinsiyete göre sıralanmış" gibi yanıltıcı görünüyordu.
                            // Kullanıcı raporu: kabul edilmiş ama henüz named slota (Takım Arkadaşı/
                            // Rakip1/Rakip2) atanmamış oyuncular önceden TÜM slotlardan (dolu VEYA boş)
                            // SONRA render ediliyordu — bu yüzden "Bekleniyor" yazan BOŞ kutular ekranda
                            // atanmış bir katılımcının ÜSTÜNDE görünüyordu, üstelik numaralandırma da
                            // çakışıyordu (hem boş slot hem atanmamış oyuncu aynı "Katılımcı N" numarasını
                            // alabiliyordu — ikisi de ayrı ayrı `i+1`den başlıyordu). Artık TEK bir sıralı
                            // numara dizisi var: önce dolu named slotlar, sonra atanmamış (kabul edilmiş)
                            // oyuncular — ARADA HİÇ BOŞLUK OLMADAN — en son da gerçekten boş kalan
                            // "Bekleniyor" slotları, numaralandırma kaldığı yerden devam ediyor.
                            // DİKKAT: allTeamSlots sadece 3 adlandırılmış slot (partner/rakip1/rakip2)
                            // içerir — kapasite kurucu hariç 3 kişidir. Atanmamış havuzdaki her oyuncu
                            // da bu 3 kapasiteden birini ZATEN dolduruyor (henüz hangi role gideceği
                            // belli değil, ama bir kişilik yer kaplıyor). Bunu düşmeden ham
                            // "adı boş olan slot" listesini göstermek fazladan hayalet kutu üretiyordu
                            // (ör. 1 atanmamış oyuncu + 3 boş adlandırılmış slot = 4 "Katılımcı" kutusu,
                            // halbuki 2v2'de kurucu hariç sadece 3 kişilik yer var).
                            const emptyNamedSlots = allTeamSlots.filter(sl => !sl.p?.id).slice(unassignedDoubleSlots.length);
                            const acceptedCount = teamSlots.length + unassignedDoubleSlots.length;

                            if (!showTeamCards) {
                                // Kullanıcı isteğiyle ön yüzde her satıra 2 oyuncu sığıyor (önceden tek
                                // sütun, alt alta tam genişlikti) — kart stiline geçildi (48% genişlik,
                                // sınırlı çerçeve), tek-sütun playerRow yerine.
                                const cardBox = { width:'48%', backgroundColor:'#1e293b', borderRadius:8, borderWidth:1, borderColor: colors.border+'40', paddingVertical:5, paddingHorizontal:6, marginBottom:6 };
                                return (
                                    <View style={{ flexDirection:'row', flexWrap:'wrap', justifyContent:'space-between' }}>
                                        <View key="founder" style={cardBox}>
                                            <TouchableOpacity style={{ flexDirection:'row', alignItems:'center', gap:6 }} onPress={() => item.senderId && navigation.push('Profile', { userId: item.senderId })}>
                                                <Avatar name={item.sender?.username} avatar={item.sender?.avatar} size={moderateScale(28)} color={cfg.color} />
                                                <View style={{ flex:1 }}>
                                                    <View style={{ flexDirection:'row', alignItems:'center' }}>
                                                        <Text style={[det.playerName, { flexShrink:1 }]} numberOfLines={1}>{playerDisplayName(item.sender)}</Text>
                                                        {item.senderId && localOrderedUserIds.includes(item.senderId) && (
                                                            <TouchableOpacity onPress={() => item.senderId === myId && setShowMyOrder(true)} hitSlop={{ top:6, bottom:6, left:4, right:6 }} disabled={item.senderId !== myId}>
                                                                <Animated.Text style={{ fontSize:12, marginLeft:4, opacity: orderBlink }}>📋</Animated.Text>
                                                            </TouchableOpacity>
                                                        )}
                                                        {/* Kullanıcı isteği: derece puanı (elo) kurucu dahil herkeste görünsün. */}
                                                        {item.sender?.interests?.[0]?.skillRating != null && (
                                                            <Text style={{ color:'#facc15', fontSize:9, fontWeight:'800', marginLeft:4 }} numberOfLines={1}>{Number(item.sender.interests[0].skillRating).toFixed(2)}★</Text>
                                                        )}
                                                    </View>
                                                    <Text style={det.playerSub} numberOfLines={1}>{item.sender?.username} · {t.founder || 'Kurucu'}</Text>
                                                </View>
                                            </TouchableOpacity>
                                        </View>
                                        {teamSlots.map((sl, i) => (
                                            <View key={sl.key} style={cardBox}>
                                                <TouchableOpacity style={{ flexDirection:'row', alignItems:'center', gap:6 }} onPress={() => sl.p.id && navigation.push('Profile', { userId: sl.p.id })}>
                                                    <Avatar name={sl.p.username} avatar={sl.p.avatar} size={moderateScale(28)} color={cfg.color} />
                                                    <View style={{ flex:1 }}>
                                                        <View style={{ flexDirection:'row', alignItems:'center' }}>
                                                            <Text style={[det.playerName, { flexShrink:1 }]} numberOfLines={1}>
                                                                {playerDisplayName(sl.p)}
                                                                {/* Kullanıcı isteği: isim yanında (voleyboldaki gibi) kısa cinsiyet
                                                                    parantezi — (E)/(K). */}
                                                                {(sl.p.gender === 'MALE' || sl.p.gender === 'FEMALE') && (
                                                                    <Text style={{ color: colors.textMuted, fontWeight:'400' }}> ({sl.p.gender === 'MALE' ? t.genderMaleShort : t.genderFemaleShort})</Text>
                                                                )}
                                                            </Text>
                                                            {sl.p.id && localOrderedUserIds.includes(sl.p.id) && (
                                                                <TouchableOpacity onPress={() => sl.p.id === myId && setShowMyOrder(true)} hitSlop={{ top:6, bottom:6, left:4, right:6 }} disabled={sl.p.id !== myId}>
                                                                    <Animated.Text style={{ fontSize:12, marginLeft:4, opacity: orderBlink }}>📋</Animated.Text>
                                                                </TouchableOpacity>
                                                            )}
                                                            {/* Kullanıcı isteği: derece puanı (elo) isimlerin sağında. */}
                                                            {sl.p.skillRating != null && (
                                                                <Text style={{ color:'#facc15', fontSize:9, fontWeight:'800', marginLeft:4 }} numberOfLines={1}>{Number(sl.p.skillRating).toFixed(2)}★</Text>
                                                            )}
                                                        </View>
                                                        {/* Kullanıcı raporu: ön yüzde slot bazlı cinsiyet etiketi ("Katılımcı 1
                                                            (kadın)") kafa karıştırıyordu — kabul sırasına göre yerleşen biri
                                                            o numarada göründüğü için, cinsiyeti farklı biri kabul edilince
                                                            sanki "yanlış cinsiyete atandı" gibi bir izlenim veriyordu. Cinsiyet
                                                            artık SADECE arka yüzdeki takım kartında (spesifik role bağlı
                                                            olduğu yerde) gösteriliyor, ön yüz salt sıra numarası. */}
                                                        <Text style={det.playerSub} numberOfLines={1}>{t.cardParticipantLabel(i + 1)}</Text>
                                                    </View>
                                                </TouchableOpacity>
                                                {isOwner && (
                                                    <TouchableOpacity onPress={() => removeRivalParticipant(sl.p.id, sl.p.username)} style={{ marginTop:3, alignSelf:'flex-end' }}>
                                                        <Text style={{ color:'#f87171', fontSize:moderateScale(10), fontWeight:'700' }}>Çıkar</Text>
                                                    </TouchableOpacity>
                                                )}
                                            </View>
                                        ))}
                                        {/* Kullanıcı isteği: kabul edilmiş ama henüz Takım Arkadaşı/Rakip1/
                                            Rakip2'ye ATANMAMIŞ oyuncular ön yüzde "Atanmamış" diye uyarı gibi
                                            DEĞİL, tıpkı named slotlardaki gibi (dolu slotların HEMEN ardından,
                                            boş "Bekleniyor" kutularından ÖNCE) sıradaki "Katılımcı N" olarak
                                            görünür — hangi spesifik role gideceği (arka yüzdeki "Atanmamış"
                                            listesinden, bkz. promptAssignTeam) SADECE ilan sahibini ilgilendiren
                                            bir arka yüz detayı, ön yüzde katılımcı sayılmaları için önemli değil. */}
                                        {unassignedDoubleSlots.map((p, i) => (
                                            <View key={p.id} style={cardBox}>
                                                <TouchableOpacity style={{ flexDirection:'row', alignItems:'center', gap:6 }} onPress={() => navigation.push('Profile', { userId: p.id })}>
                                                    <Avatar name={p.username} avatar={p.avatar} size={moderateScale(28)} color={cfg.color} />
                                                    <View style={{ flex:1 }}>
                                                        <View style={{ flexDirection:'row', alignItems:'center' }}>
                                                            <Text style={[det.playerName, { flexShrink:1 }]} numberOfLines={1}>
                                                                {playerDisplayName(p)}
                                                                {(p.gender === 'MALE' || p.gender === 'FEMALE') && (
                                                                    <Text style={{ color: colors.textMuted, fontWeight:'400' }}> ({p.gender === 'MALE' ? t.genderMaleShort : t.genderFemaleShort})</Text>
                                                                )}
                                                            </Text>
                                                            {p.id && localOrderedUserIds.includes(p.id) && (
                                                                <TouchableOpacity onPress={() => p.id === myId && setShowMyOrder(true)} hitSlop={{ top:6, bottom:6, left:4, right:6 }} disabled={p.id !== myId}>
                                                                    <Animated.Text style={{ fontSize:12, marginLeft:4, opacity: orderBlink }}>📋</Animated.Text>
                                                                </TouchableOpacity>
                                                            )}
                                                            {p.skillRating != null && (
                                                                <Text style={{ color:'#facc15', fontSize:9, fontWeight:'800', marginLeft:4 }} numberOfLines={1}>{Number(p.skillRating).toFixed(2)}★</Text>
                                                            )}
                                                        </View>
                                                        <Text style={det.playerSub} numberOfLines={1}>{t.cardParticipantLabel(teamSlots.length + i + 1)}</Text>
                                                    </View>
                                                </TouchableOpacity>
                                                {/* Kullanıcı raporu: named slottaki (Takım Arkadaşı/Rakip1/Rakip2)
                                                    dolu formalarda olduğu gibi, atanmamış havuzdaki oyuncular için
                                                    de Çıkar butonu eksikti. */}
                                                {isOwner && (
                                                    <TouchableOpacity onPress={() => removeRivalParticipant(p.id, p.username)} style={{ marginTop:3, alignSelf:'flex-end' }}>
                                                        <Text style={{ color:'#f87171', fontSize:moderateScale(10), fontWeight:'700' }}>Çıkar</Text>
                                                    </TouchableOpacity>
                                                )}
                                            </View>
                                        ))}
                                        {/* Kullanıcı isteği: bekleyen (henüz yanıtlanmamış) davet ön yüzde
                                            ayrıca isim+"Onay Bekleniyor" kutusu olarak GÖSTERİLMİYOR — bu
                                            zaten "📨 Gönderilen Davetler" bölümünde var, tekrar burada
                                            göstermek yanıltıcı ("kabul edilmiş gibi" görünüyordu). Partner
                                            slotu da (daveti bekleyen dahil) diğer boş slotlar gibi düz
                                            "Bekleniyor" kutusuna düşer, aşağıdaki emptyNamedSlots döngüsünde. */}
                                        {emptyNamedSlots.map((sl, i) => {
                                            // Kullanıcı raporu: ön yüzdeki ("Katılan Oyuncular") boş formalara
                                            // arka yüzdeki (SlotBox) gibi doğrudan davet arama alanı eklenmişti
                                            // — ön yüz sadece görüntüleme olmalı, davet/atama SADECE arka yüzdeki
                                            // "Takımları Düzenle" ekranından yapılır. Bu yüzden isOwner'a bakmadan
                                            // her zaman salt-okunur "Bekleniyor" kutusuna düşer.
                                            return (
                                                <View key={sl.key} style={[cardBox, { opacity:0.55, flexDirection:'row', alignItems:'center', gap:6 }]}>
                                                    <View style={{ width:moderateScale(28), height:moderateScale(28), borderRadius:moderateScale(14), borderWidth:1, borderStyle:'dashed', borderColor: colors.textMuted, alignItems:'center', justifyContent:'center' }}>
                                                        <Text style={{ color: colors.textMuted, fontSize:13 }}>?</Text>
                                                    </View>
                                                    <View style={{ flex:1 }}>
                                                        {/* Cinsiyet burada da (boş "Bekleniyor" kutusunda) gösterilmiyor —
                                                            bkz. yukarıdaki dolu slot yorumu, aynı gerekçe. */}
                                                        <Text style={[det.playerSub, { color: colors.textMuted }]} numberOfLines={1}>{t.cardParticipantLabel(acceptedCount + i + 1)}</Text>
                                                        <Text style={[det.playerSub, { color: colors.textMuted, fontSize:9 }]} numberOfLines={1}>Bekleniyor</Text>
                                                    </View>
                                                </View>
                                            );
                                        })}
                                        {acceptedOthers.length === 0 && unassignedDoubleSlots.length === 0 && <Text style={det.emptyTxt}>{t.noPlayersYet || 'Henüz katılan yok'}</Text>}
                                    </View>
                                );
                            }

                            return (
                                <View>
                                    {swapSlot && (
                                        <View style={{ backgroundColor:'#f59e0b18', borderRadius:6, padding:3, marginBottom:6, alignItems:'center' }}>
                                            <Text style={{ color:'#f59e0b', fontSize:11, fontWeight:'700' }}>Taşınacak oyuncu seçildi — hedef slota dokun</Text>
                                            <TouchableOpacity onPress={() => setSwapSlot(null)} style={{ marginTop:3 }}>
                                                <Text style={{ color: colors.textMuted, fontSize:10 }}>İptal</Text>
                                            </TouchableOpacity>
                                        </View>
                                    )}
                                    <View style={{ flexDirection:'row', flexWrap:'wrap', justifyContent:'space-between' }}>
                                        <View style={{ width:'48%', backgroundColor:'#1e293b', borderRadius:8, borderWidth:1, borderColor: colors.border+'40', paddingVertical:5, paddingHorizontal:5, marginBottom:6 }}>
                                            <Text style={{ color: cfg.color, fontSize:9, fontWeight:'800', marginBottom:4 }}>👑 Kurucu Takımı</Text>
                                            {/* Kurucu sabit — taşınamaz */}
                                            {/* Kullanıcı isteği: derece puanı (elo) kurucu dahil herkeste görünsün —
                                                item.sender'da düz skillRating yok, interests[0]'dan taşınıyor
                                                (SlotBox zaten p.skillRating'i gösteriyor, bkz. teamSlots). */}
                                            <SlotBox slot="__owner" locked p={{ ...item.sender, skillRating: item.sender?.interests?.[0]?.skillRating }} fallback="" />
                                            <View style={{ flexDirection:'row', alignItems:'center', marginVertical:2 }}>
                                                <Text style={{ color: colors.textMuted, fontSize:10, fontWeight:'900', flex:1, textAlign:'center' }}>+</Text>
                                                {genderLabel(partnerGenderReq) && <Text style={{ color:'#a855f7', fontSize:8, fontWeight:'700' }}>{genderLabel(partnerGenderReq)}</Text>}
                                            </View>
                                            {/* Kullanıcı isteği: bekleyen (henüz yanıtlanmamış) partner daveti
                                                burada da (arka yüz) ayrıca isim+"Onay Bekleniyor" olarak
                                                GÖSTERİLMİYOR — "📨 Gönderilen Davetler" bölümü zaten bunu
                                                gösteriyor, kart içinde tekrarı kafa karıştırıyordu (kullanıcı
                                                raporu, ön yüzdeki aynı kaldırma ile tutarlı). SlotBox boşken
                                                kendi içinde arama/davet alanını (ya da, sahip değilse/takas
                                                aktifse, eski statik metni) gösteriyor. */}
                                            <SlotBox slot="partner" p={PartnerContent} fallback="Partner yok" gReqLabel={null} gReqValue={partnerGenderReq}
                                                highlighted={highlightSlot?.doubleSlot === 'partner'} />
                                        </View>
                                        <View style={{ width:'48%', backgroundColor:'#1e293b', borderRadius:8, borderWidth:1, borderColor: colors.border+'40', paddingVertical:5, paddingHorizontal:5, marginBottom:6 }}>
                                            <Text style={{ color:'#f87171', fontSize:9, fontWeight:'800', marginBottom:4 }}>⚔️ Rakip Takımı</Text>
                                            <SlotBox slot="opp1" p={participants[0]} fallback="Henüz katılan yok"
                                                gReqLabel={genderLabel(opp1GenderReq)} gReqValue={opp1GenderReq}
                                                highlighted={highlightSlot?.doubleSlot === 'opp1'}
                                                onRemove={isOwner && participants[0] ? () => removeRivalParticipant(participants[0].id, participants[0].username) : null}
                                            />
                                            <View style={{ flexDirection:'row', alignItems:'center', marginVertical:2 }}>
                                                <Text style={{ color: colors.textMuted, fontSize:10, fontWeight:'900', flex:1, textAlign:'center' }}>+</Text>
                                                {genderLabel(opp2GenderReq) && <Text style={{ color:'#a855f7', fontSize:8, fontWeight:'700' }}>{genderLabel(opp2GenderReq)}</Text>}
                                            </View>
                                            {/* gReqLabel=null: cinsiyet etiketi zaten hemen üstündeki "+" satırında
                                                gösteriliyor (bkz. yukarıdaki genderLabel(opp2GenderReq)) — burada da
                                                geçilirse "♀ Kadın" iki kez üst üste yazılıyordu (kullanıcı raporu). */}
                                            <SlotBox slot="opp2" p={participants[1]} fallback="Henüz katılan yok"
                                                gReqLabel={null} gReqValue={opp2GenderReq}
                                                highlighted={highlightSlot?.doubleSlot === 'opp2'}
                                                onRemove={isOwner && participants[1] ? () => removeRivalParticipant(participants[1].id, participants[1].username) : null}
                                            />
                                        </View>
                                    </View>
                                    {/* Takım Değişikliği bilgisi — kullanıcı isteği: açık ilan detayının arka
                                        yüzünde de (ilan oluşturma/Yaklaşan Maçlar'daki gibi) bu bilgi sürekli
                                        görünsün, sadece bir slot davetinden gelindiğinde değil. Davetten
                                        gelindiyse (highlightSlot.doubleSlot) ve kilitliyse ayrıca kırmızı
                                        yanıp söner — davet edilen kişi pozisyonun değişmeyeceğini fark etsin. */}
                                    {highlightSlot?.doubleSlot && item.teamFlexibility === 'STRICT' ? (
                                        <Animated.View style={{ opacity: highlightPulse, backgroundColor:'#ef444418', borderRadius:6, padding:5, marginTop:6, alignItems:'center' }}>
                                            <Text style={{ color:'#ef4444', fontSize:10, fontWeight:'800' }}>🔒 Takım değişikliği kapalı — bu pozisyonda kalacaksınız</Text>
                                        </Animated.View>
                                    ) : (
                                        <Text style={{ color: colors.textMuted, fontSize:10, fontWeight:'700', textAlign:'center', marginTop:6 }}>
                                            {item.teamFlexibility === 'STRICT' ? '🔒' : '☑️'} {t.teamFlexLabel}: {item.teamFlexibility === 'STRICT' ? t.flexModeShortStrict : t.flexModeShortFlexible}
                                        </Text>
                                    )}
                                    {unassignedDoubleSlots.length > 0 && (
                                        <View style={{ marginTop:8 }}>
                                            <Text style={{ color:'#fbbf24', fontSize:9, fontWeight:'800', marginBottom:4 }}>Atanmamış</Text>
                                            {unassignedDoubleSlots.map(p => {
                                                const isMe = p.id === myId;
                                                // Kullanıcı raporu: partner slotu kendisi (PartnerContent) boş
                                                // olduğu sürece, BAŞKA birine gönderilmiş bekleyen bir davet
                                                // (pendingPartnerInvite) varsa bile "Kendi Takımıma Ata"
                                                // seçeneği hâlâ sunulmalı — o davet henüz kabul edilmedi,
                                                // slotu gerçekten dolduran bir şey yok. assignDoubleSlot zaten
                                                // gerçek dolulukta ("senderTeam[0]") kontrol yapıyor, davetlerle
                                                // ilgilenmiyor (bkz. backend), bu yüzden burada da engellenmemeli.
                                                const canTeam1 = !PartnerContent && genderFitsSlot(p.gender, partnerGenderReq);
                                                const team2Slot = [
                                                    !participants[0]?.id && genderFitsSlot(p.gender, opp1GenderReq) && 'opp1',
                                                    !participants[1]?.id && genderFitsSlot(p.gender, opp2GenderReq) && 'opp2',
                                                ].find(Boolean);
                                                const team1Label = item.founderTeamName || t.founderTeamShortLabel || 'Takım 1';
                                                const team2Label = item.opponentTeamName || t.opponentTeamShortLabel || 'Takım 2';
                                                return (
                                                    <View key={p.id} style={{ backgroundColor:'#1e293b', borderRadius:8, borderWidth:1, borderColor: colors.border+'40', paddingVertical:5, paddingHorizontal:6, marginBottom:4, flexDirection:'row', alignItems:'center', gap:4 }}>
                                                        <Text style={{ color:'#fff', fontSize:11, fontWeight:'700', flex:1, minWidth:0 }} numberOfLines={1}>
                                                            {playerDisplayName(p)}
                                                            {(p.gender === 'MALE' || p.gender === 'FEMALE') && (
                                                                <Text style={{ color: colors.textMuted, fontWeight:'400' }}> ({p.gender === 'MALE' ? t.genderMaleShort : t.genderFemaleShort})</Text>
                                                            )}
                                                            {p.skillRating != null && (
                                                                <Text style={{ color:'#facc15', fontWeight:'800' }}>  {Number(p.skillRating).toFixed(2)}★</Text>
                                                            )}
                                                        </Text>
                                                        {(isOwner || isMe) && canTeam1 && (
                                                            <TouchableOpacity onPress={() => assignDoubleSlot(p.id, 'partner')}
                                                                style={{ paddingHorizontal:6, paddingVertical:4, borderRadius:5, backgroundColor: cfg.color+'20', borderWidth:1, borderColor: cfg.color+'50' }}>
                                                                <Text style={{ color: cfg.color, fontSize:9, fontWeight:'700' }} numberOfLines={1} adjustsFontSizeToFit minimumFontScale={0.6}>{team1Label}'a Ata</Text>
                                                            </TouchableOpacity>
                                                        )}
                                                        {(isOwner || isMe) && team2Slot && (
                                                            <TouchableOpacity onPress={() => assignDoubleSlot(p.id, team2Slot)}
                                                                style={{ paddingHorizontal:6, paddingVertical:4, borderRadius:5, backgroundColor: cfg.color+'20', borderWidth:1, borderColor: cfg.color+'50' }}>
                                                                <Text style={{ color: cfg.color, fontSize:9, fontWeight:'700' }} numberOfLines={1} adjustsFontSizeToFit minimumFontScale={0.6}>{team2Label}'a Ata</Text>
                                                            </TouchableOpacity>
                                                        )}
                                                        {isOwner && (
                                                            <TouchableOpacity onPress={() => removeRivalParticipant(p.id, p.username)}
                                                                style={{ paddingHorizontal:6, paddingVertical:4, borderRadius:5, backgroundColor:'#dc262612', borderWidth:1, borderColor:'#dc262630' }}>
                                                                <Text style={{ color:'#f87171', fontSize:9, fontWeight:'700' }} numberOfLines={1}>Çıkar</Text>
                                                            </TouchableOpacity>
                                                        )}
                                                    </View>
                                                );
                                            })}
                                        </View>
                                    )}
                                    {(() => {
                                        // Kullanıcı hangi boş kutunun 👥 ikonuna dokunduysa (bkz. doubleInviteFromSlot),
                                        // o slot listenin BAŞINA alınır — picker'daki İLK seçim her zaman GERÇEKTEN
                                        // tıklanan slotun cinsiyet kuralına göre kontrol edilir. Önceden sıra her
                                        // zaman sabit partner→opp1→opp2 idi, tıklanan kutu ne olursa olsun ilk seçim
                                        // partner'ın (genelde farklı cinsiyet) kuralına göre kontrol ediliyordu —
                                        // "2./3./4. oyuncu formundan davet ediyorum, hep kadın kabul ediyor" hatası
                                        // buradan geliyordu (kullanıcı raporu).
                                        const rawEmptyKeys = ['partner', 'opp1', 'opp2'].filter(k => !({ partner: PartnerContent, opp1: participants[0], opp2: participants[1] }[k]));
                                        const emptyKeys = doubleInviteFromSlot && rawEmptyKeys.includes(doubleInviteFromSlot)
                                            ? [doubleInviteFromSlot, ...rawEmptyKeys.filter(k => k !== doubleInviteFromSlot)]
                                            : rawEmptyKeys;
                                        return (
                                            <FriendsMultiPickerModal
                                                visible={showDoubleFriendsPicker}
                                                onClose={() => { setShowDoubleFriendsPicker(false); setDoubleInviteFromSlot(null); }}
                                                sub={sub} category={item.category} cfg={cfg} t={t}
                                                maxSelect={emptyKeys.length}
                                                slotGenderReqs={emptyKeys.map(k => ({ partner: partnerGenderReq, opp1: opp1GenderReq, opp2: opp2GenderReq }[k]))}
                                                confirmLabel={(n) => t.friendsMultiPickerInviteBtn(n)}
                                                onConfirm={(users) => {
                                                    Promise.all(users.map((u, i) => api.post(`/rivals/${item.id}/invite`, { userId: u.id, slot: emptyKeys[i] })))
                                                        .then(() => onRefresh())
                                                        .catch(e => Alert.alert(t.error, e?.response?.data?.message || t.actionFailed));
                                                }}
                                            />
                                        );
                                    })()}
                                </View>
                            );
                        })() : (senderTeamArr.length > 0 || (item.teamSize || 1) > 1) ? (() => {
                            // Takım sporları (voleybol, futbol vb.) — ilan oluşturma ekranındaki kadro
                            // kartıyla BİREBİR AYNI yapı: ön yüzde 3'lü grid havuz (+ yedekler), arka
                            // yüzde Kurucu Takımı ↔ Rakip Takımı (teamSize'lık sabit iki sütun).
                            // showTeamCards/cardRotateY (DOUBLE'daki ile aynı state) ön/arka geçişi
                            // sağlıyor — kullanıcı isteğiyle oluşturma ekranındaki tasarım kopyalandı.
                            const teamSizeN = item.teamSize || 1;
                            // Kullanıcı isteği: voleybolda satır başına 4 forma sığdırınca sıkışık
                            // görünüyordu — ilan oluşturma ekranındaki (CreateRivalModal) 3'lü grid
                            // (32%) genişliğiyle aynı orana getirildi. Diğer takım sporları (futbol,
                            // airsoft) eski 4'lü (23.5%) düzende kalıyor.
                            const isVolleyball = sub === 'volleyball';
                            const poolCellWidth = isVolleyball ? '32%' : '23.5%';
                            const mySlots = senderTeamArr.filter(p => p?.id || p?.manualName);
                            const oppSlots = [...participants.filter(p => p?.id || p?.manualName), ...oppManualNames.map(n => ({ manualName: n }))];
                            const subSlots = (Array.isArray(item.substitutePlayers) ? item.substitutePlayers : []).filter(p => p?.id || p?.manualName);

                            // Kullanıcı isteği: ön yüzde ("Katılan Oyuncular") isimlerin altında artık
                            // takım adı/atama butonu YOK — atama sadece arka yüzdeki "Atanmamış"
                            // listesinden yapılıyor (bkz. promptAssignTeam), ön yüz sadece görüntüleme +
                            // atanmamışlar için kırmızı yanıp sönen uyarı (unassignedWarning).
                            const Cell = ({ p, side, allowRemove, unassignedWarning }) => {
                                const isFounder = p.id && p.id === item.senderId;
                                const isMe = p.id != null && p.id === myId;
                                // İlan sahibi (item.sender) SENDER_SELECT+interests ilişkisiyle geliyor
                                // (interests[0].skillRating), diğer oyuncular ise senderTeam/participants
                                // Json snapshot'ından (backend'in eklediği düz p.skillRating) — ikisini de kapsa.
                                const cellRating = p.skillRating ?? p.interests?.[0]?.skillRating;
                                // Cinsiyet — isim/soyisimden sonra kısa parantez (kullanıcı isteği: TR'de
                                // (E)/(K), EN'de (M)/(W)).
                                const genderParen = p.id && (p.gender === 'MALE' || p.gender === 'FEMALE')
                                    ? ` (${p.gender === 'MALE' ? t.genderMaleShort : t.genderFemaleShort})` : '';
                                const posLabel = sub === 'volleyball' && p.position
                                    ? (p.position === 'SPIKER' ? t.positionSpiker : p.position === 'LIBERO' ? t.positionLibero : t.positionSetter) : '';
                                // Kullanıcı isteği: ilan sahibi olmayan bir katılımcı da (atanmamış
                                // havuzunda, takıma atanmış ya da yedekte fark etmez) "Katılan Oyuncular"
                                // listesinde kendi ismine dokununca kendisi için pozisyon önerebilsin —
                                // önceden bu sadece Yaklaşan Maçlar'daki kadro kartında (TeamAssignCard)
                                // vardı, açık ilan detayında hiç yoktu.
                                const pendingSuggestion = sub === 'volleyball' && p.id
                                    ? (Array.isArray(item.positionSuggestions) ? item.positionSuggestions : []).find(sg => sg?.userId === p.id)
                                    : null;
                                const pendingSuggestionLabel = pendingSuggestion
                                    ? (pendingSuggestion.position === 'SPIKER' ? t.positionSpiker : pendingSuggestion.position === 'LIBERO' ? t.positionLibero : t.positionSetter) : '';
                                // Kullanıcı isteği: pozisyon + Çıkar/Değiştir aynı satırda isimle
                                // sıkışıyordu — takım sütununda (allowRemove'lu bağlamda) artık ismin
                                // biraz sağından başlayan ikinci bir satırda gösteriliyor. Ön yüz
                                // havuzunda (allowRemove yok) pozisyon eskisi gibi isimle aynı satırda.
                                return (
                                    <View>
                                        <View style={{ flexDirection:'row', alignItems:'center' }}>
                                            {/* Kullanıcı isteği: isme dokununca artık direkt profile gitmiyor —
                                                ilan sahibi + voleybolda "Pozisyona Ata"/"Profiline Git"/"Maçtan
                                                Çıkar" seçenekleri çıkıyor (kurucu dahil — "kendine pozisyon
                                                atayamıyor" şikayeti buradan çözülüyor). İlan sahibi olmayan
                                                katılımcı kendi satırına dokununca "Pozisyon Önerisi Sun"
                                                seçeneğini görür. Diğer herkes için direkt profile gider. */}
                                            <TouchableOpacity disabled={!p.id} onPress={() => {
                                                if (isOwner && sub === 'volleyball') promptSlotAction(p, side, 'nameMenu');
                                                else if (!isOwner && isMe && sub === 'volleyball') promptSlotAction(p, side, 'nameMenu');
                                                else if (p.id) navigation.push('Profile', { userId: p.id });
                                            }} style={{ flexDirection:'row', alignItems:'center', gap:2, flex:1, minWidth:0 }}>
                                                {p.id
                                                    ? <Avatar name={p.username} avatar={p.avatar} size={14} color={cfg.color} />
                                                    : <View style={{ width:14, height:14 }} />}
                                                <Animated.View style={[s.fieldInput, { flex:1, marginBottom:0, paddingVertical:2, paddingHorizontal:5, justifyContent:'center', opacity: unassignedWarning ? unassignedBlink : 0.8, minHeight:0 }]}>
                                                    <Text style={{ color: unassignedWarning ? '#ef4444' : '#fff', fontSize:10, fontWeight: unassignedWarning ? '800' : '400' }} numberOfLines={1}>
                                                        {p.id ? playerDisplayName(p) : p.manualName}
                                                        {!!genderParen && <Text style={{ color: colors.textMuted, fontWeight:'400' }}>{genderParen}</Text>}
                                                        {!allowRemove && !!posLabel && <Text style={{ color: colors.textMuted, fontWeight:'400' }}> ({posLabel})</Text>}
                                                    </Text>
                                                </Animated.View>
                                            </TouchableOpacity>
                                            {/* Kullanıcı isteği: "kadro kartta oyuncuların yanında derece puanları
                                                sağlarında yazsın" — rekabetçi maçlarda takım gücünü görebilmek için. */}
                                            {p.id && cellRating != null && (
                                                <Text style={{ color:'#facc15', fontSize:9, fontWeight:'800', marginLeft:3 }} numberOfLines={1}>{Number(cellRating).toFixed(2)}★</Text>
                                            )}
                                        </View>
                                        {allowRemove && (!!posLabel || (isOwner && !isFounder)) && (
                                            <View style={{ flexDirection:'row', alignItems:'center', paddingLeft:16, marginTop:1 }}>
                                                <Text style={{ color: colors.textMuted, fontSize:9, flex:1 }} numberOfLines={1}>{posLabel ? `🏐 ${posLabel}` : ''}</Text>
                                                {/* Kullanıcı isteği: "Çıkar" yazısı hangi oyuncuya ait olduğu belirsizdi
                                                    (isim altında, sıkışık) — artık ayrı bir satırda SAĞDA. Dokununca
                                                    küçük bir pencerede Çıkar / Atanmamışa Taşı sorulur (bkz. promptSlotAction). */}
                                                {isOwner && !isFounder && (
                                                    <TouchableOpacity onPress={() => promptSlotAction(p, side)} hitSlop={{ top:4, bottom:4, left:4, right:4 }}>
                                                        <Text style={{ color: colors.textMuted, fontSize:8, fontWeight:'700', textDecorationLine:'underline' }} numberOfLines={1}>Çıkar/Değiştir</Text>
                                                    </TouchableOpacity>
                                                )}
                                            </View>
                                        )}
                                        {/* Kullanıcı isteği: katılımcının kendisi için önerdiği, ilan sahibinin
                                            henüz yanıtlamadığı pozisyon — ilan sahibi dokununca Onayla/Reddet
                                            menüsü açılır (bkz. 'suggestionReview'), öneriyi yapan sadece bekler. */}
                                        {pendingSuggestion && (
                                            <TouchableOpacity disabled={!isOwner} activeOpacity={isOwner ? 0.6 : 1}
                                                onPress={() => isOwner && promptSlotAction(p, side, 'suggestionReview')}
                                                style={{ paddingLeft:16, marginTop:1 }}>
                                                <Text style={{ color:'#facc15', fontSize:9, fontWeight:'700' }} numberOfLines={1}>
                                                    {isOwner ? `🏐 ${t.positionSuggestionPendingOwnerLabel(pendingSuggestionLabel)}` : `⏳ ${t.positionSuggestionPendingMineLabel(pendingSuggestionLabel)}`}
                                                </Text>
                                            </TouchableOpacity>
                                        )}
                                    </View>
                                );
                            };
                            const EmptyCell = () => (
                                <View style={{ flexDirection:'row', alignItems:'center', gap:2, opacity:0.55 }}>
                                    <View style={{ width:14, height:14, borderRadius:7, borderWidth:1, borderStyle:'dashed', borderColor: colors.textMuted, alignItems:'center', justifyContent:'center' }}>
                                        <Text style={{ color: colors.textMuted, fontSize:8 }}>?</Text>
                                    </View>
                                    <View style={[s.fieldInput, { flex:1, marginBottom:0, paddingVertical:2, paddingHorizontal:5, justifyContent:'center', minHeight:0 }]}>
                                        <Text style={{ color: colors.textMuted, fontSize:10 }} numberOfLines={1}>Bekleniyor</Text>
                                    </View>
                                </View>
                            );
                            // Kullanıcı isteğiyle her slot SABİT bir pozisyon — "6. forma yazdım"
                            // gerçekten 6. sırada kalır, dizinin sonuna atlamaz. peoplePositional
                            // dolu olmayan index'lerde null/undefined içerebilir (bkz. backend
                            // setAtSlot); legacyManualExtra (eski oppTeamManualNames — pozisyonu
                            // bilinmeyen çok eski kayıtlar) sabit slotların ALTINDA, ekstra
                            // satırlar olarak ayrıca gösterilir, kaybolmasınlar diye.
                            const TeamColBack = ({ label, color, peoplePositional, legacyManualExtra = [], total, allowRemove, side, onEditName }) => {
                                const slots = Array.from({ length: total }, (_, i) => peoplePositional[i] || null);
                                // Kullanıcı isteği: "takımlar belli olduğuna göre takımların ortalama
                                // derecesi kaç, rekabetçi maç modu önemli" — dolu forma sayısı üzerinden
                                // (henüz derecesi olmayan/manuel oyuncular ortalamaya katılmıyor).
                                const teamRatings = [...slots, ...legacyManualExtra]
                                    .filter(Boolean)
                                    .map(p => p.skillRating ?? p.interests?.[0]?.skillRating)
                                    .filter(r => r != null);
                                const teamAvgRating = teamRatings.length > 0 ? teamRatings.reduce((s, r) => s + Number(r), 0) / teamRatings.length : null;
                                return (
                                    <View style={{ flex:1 }}>
                                        <View style={{ flexDirection:'row', alignItems:'center', gap:4, marginBottom:3 }}>
                                            <Text style={{ color, fontSize:10, fontWeight:'800' }} numberOfLines={1}>{label}</Text>
                                            {isOwner && onEditName && (
                                                <TouchableOpacity onPress={onEditName} hitSlop={{ top:6, bottom:6, left:6, right:6 }}>
                                                    <Text style={{ color: colors.textMuted, fontSize:9, fontWeight:'700' }} numberOfLines={1}>{t.teamNameChangeBtn}</Text>
                                                </TouchableOpacity>
                                            )}
                                            <View style={{ flex:1 }} />
                                            {teamAvgRating != null && (
                                                <Text style={{ color:'#facc15', fontSize:9, fontWeight:'800' }} numberOfLines={1}>Ort {teamAvgRating.toFixed(2)}★</Text>
                                            )}
                                        </View>
                                        {slots.map((p, i) => {
                                            // Bildirimden ("...Rakip Takım'a davet etti") gelindiyse, davet edilen
                                            // boş slot yanıp sönen bir çerçeveyle vurgulanır (kullanıcı isteği:
                                            // hangi forma davet edildiğini görsün).
                                            const isHighlighted = !p && highlightSlot?.side === side && highlightSlot?.slotIndex === i;
                                            return p ? (
                                                <View key={p.id || `m-${i}`} style={{ marginBottom:3 }}><Cell p={p} side={side} allowRemove={allowRemove} /></View>
                                            ) : (
                                                <View key={`e-${i}`} style={{ marginBottom:3 }}>
                                                    {isOwner && side ? (
                                                        <TeamSlotInviteField sub={sub} category={item.category} cfg={cfg} t={t}
                                                            placeholder={t.teamSlotPh(i + 1)}
                                                            onInvite={(u) => inviteToTeamSlot(u, side, i)} />
                                                    ) : isHighlighted ? (
                                                        <Animated.View style={{ flexDirection:'row', alignItems:'center', gap:3, borderWidth:2, borderColor: cfg.color, borderRadius:8, padding:2, opacity: highlightPulse }}>
                                                            <Text style={{ fontSize:12 }}>👉</Text>
                                                            <View style={{ flex:1 }}><EmptyCell /></View>
                                                        </Animated.View>
                                                    ) : <EmptyCell />}
                                                </View>
                                            );
                                        })}
                                        {legacyManualExtra.map((p, i) => (
                                            <View key={`legacy-${i}`} style={{ marginBottom:3 }}><Cell p={p} side={side} allowRemove={allowRemove} /></View>
                                        ))}
                                    </View>
                                );
                            };

                            const poolEmptyCount = Math.max(0, (2 * teamSizeN - 1) - mySlots.length - oppSlots.length - unassignedSlots.length);

                            return (
                                <View style={{ backgroundColor:'#1e293b', borderRadius:12, borderWidth:1, borderColor: cfg.color+'40', padding:1 }}>
                                    {!showTeamCards ? (
                                        <>
                                            <Text style={[s.fieldLabel, { marginBottom:6 }]}>{t.rosterPoolLabel}</Text>
                                            <View style={{ flexDirection:'row', flexWrap:'wrap', gap:1 }}>
                                                <View style={{ width: poolCellWidth }}>
                                                    <TouchableOpacity onPress={() => navigation.push('Profile', { userId: item.senderId })} style={{ flexDirection:'row', alignItems:'center', gap:2 }}>
                                                        <Avatar name={item.sender?.username} avatar={item.sender?.avatar} size={14} color={cfg.color} />
                                                        <View style={[s.fieldInput, { flex:1, marginBottom:0, paddingVertical:2, paddingHorizontal:5, justifyContent:'center', opacity:0.8, minHeight:0 }]}>
                                                            <Text style={{ color:'#fff', fontSize:10 }} numberOfLines={1}>{playerDisplayName(item.sender)}</Text>
                                                        </View>
                                                        {item.sender?.interests?.[0]?.skillRating != null && (
                                                            <Text style={{ color:'#facc15', fontSize:9, fontWeight:'800' }} numberOfLines={1}>{Number(item.sender.interests[0].skillRating).toFixed(2)}★</Text>
                                                        )}
                                                    </TouchableOpacity>
                                                </View>
                                                {mySlots.map((p, i) => <View key={p.id || `my-${i}`} style={{ width: poolCellWidth }}><Cell p={p} /></View>)}
                                                {oppSlots.map((p, i) => <View key={p.id || `opp-${i}`} style={{ width: poolCellWidth }}><Cell p={p} /></View>)}
                                                {/* Atama artık burada (ön yüzde) değil, kartı çevirip arka yüzdeki "Atanmamış"
                                                    listesinden yapılıyor (bkz. promptAssignTeam) — burada sadece kırmızı yanıp
                                                    sönen isimle "bunlara takım ataması yapılmadı" hatırlatması gösteriliyor. */}
                                                {unassignedSlots.map((p, i) => <View key={p.id || `u-${i}`} style={{ width: poolCellWidth }}><Cell p={p} unassignedWarning /></View>)}
                                                {Array.from({ length: poolEmptyCount }).map((_, i) => (
                                                    <View key={`empty-${i}`} style={{ width: poolCellWidth }}><EmptyCell /></View>
                                                ))}
                                            </View>
                                            {(item.substituteCount > 0 || subSlots.length > 0 || isOwner) && (
                                                <>
                                                    <View style={{ flexDirection:'row', alignItems:'center', marginTop:8, marginBottom:4, position:'relative', zIndex: showSubCountPicker ? 51 : 1 }}>
                                                        <Text style={[s.fieldLabel, { fontSize:11, marginBottom:0, flex:1 }]}>{t.subsLabel}</Text>
                                                        {isOwner && (
                                                            <>
                                                                <TouchableOpacity onPress={() => setShowSubCountPicker(v => !v)} style={{ backgroundColor: colors.surface2, borderRadius:8, borderWidth:1, borderColor: colors.border, paddingHorizontal:8, paddingVertical:3 }}>
                                                                    <Text style={{ color:'#fff', fontSize:11, fontWeight:'700' }}>{t.subCountLabel}: {item.substituteCount || 0}</Text>
                                                                </TouchableOpacity>
                                                                <MiniDropdown
                                                                    visible={showSubCountPicker}
                                                                    minWidth={60}
                                                                    options={[0, 1, 2, 3, 4, 5].map(n => ({ value: n, label: String(n) }))}
                                                                    value={item.substituteCount || 0}
                                                                    onSelect={(v) => updateSubCount(v)}
                                                                    onClose={() => setShowSubCountPicker(false)}
                                                                />
                                                            </>
                                                        )}
                                                    </View>
                                                    {(item.substituteCount > 0 || subSlots.length > 0) && (
                                                        <View style={{ flexDirection:'row', flexWrap:'wrap', gap:1 }}>
                                                            {subSlots.map((p, i) => <View key={p.id || `sub-${i}`} style={{ width: poolCellWidth }}><Cell p={p} /></View>)}
                                                            {Array.from({ length: Math.max(0, (item.substituteCount || 0) - subSlots.length) }).map((_, i) => (
                                                                <View key={`sub-empty-${i}`} style={{ width: poolCellWidth }}><EmptyCell /></View>
                                                            ))}
                                                        </View>
                                                    )}
                                                </>
                                            )}
                                        </>
                                    ) : (
                                        <View style={{ flexDirection:'row', gap:6 }}>
                                            <TeamColBack label={item.founderTeamName || t.myTeamLabel} color={cfg.color} peoplePositional={[{ ...item.sender, position: item.founderPosition }, ...senderTeamArr]} total={teamSizeN} allowRemove={isOwner}
                                                side="my" onEditName={() => setTeamNameEdit({ side:'founder', value: item.founderTeamName || '' })} />
                                            <TeamColBack label={item.opponentTeamName || t.oppTeamLabel} color="#f87171" peoplePositional={participants} legacyManualExtra={oppManualNames.map(n => ({ manualName: n }))} total={teamSizeN} allowRemove={isOwner}
                                                side="opp" onEditName={() => setTeamNameEdit({ side:'opponent', value: item.opponentTeamName || '' })} />
                                        </View>
                                    )}
                                    {/* Atanmamış — kullanıcı isteğiyle arka yüzde, iki takım sütununun ALTINDA tek
                                        liste: isme dokununca hangi takıma (gerçek isimleriyle) atanacağı sorulur,
                                        atanınca listeden otomatik kalkar (bkz. promptAssignTeam/assignUnassignedToSide). */}
                                    {showTeamCards && unassignedSlots.length > 0 && (
                                        <View style={{ marginTop:8, paddingTop:8, borderTopWidth:1, borderTopColor: colors.border }}>
                                            <Text style={[s.fieldLabel, { fontSize:10, marginBottom:4 }]}>{t.unassignedLabel} ({unassignedSlots.length})</Text>
                                            {/* Kullanıcı isteği: satır başına 3 isim (dar ekranda 2, bkz. unassignedGridCols) —
                                                tek sütun dikey liste yerine ızgara. */}
                                            <View style={{ flexDirection:'row', flexWrap:'wrap', gap:1 }}>
                                                {unassignedSlots.map((p, i) => (
                                                    <TouchableOpacity key={p.id || `unassigned-back-${i}`} disabled={!isOwner}
                                                        onPress={() => promptAssignTeam(p)}
                                                        style={{ width:`${Math.floor(100 / unassignedGridCols) - 1}%`, flexDirection:'row', alignItems:'center', gap:3, paddingVertical:4 }}>
                                                        {p.id ? <Avatar name={p.username} avatar={p.avatar} size={14} color={cfg.color} /> : <Text style={{ fontSize:11 }}>👤</Text>}
                                                        {/* Kullanıcı isteği: ilan sahibi kime hangi takımı vereceğine karar
                                                            verirken cinsiyet + derece puanını burada görsün. */}
                                                        <Text style={{ color:'#f87171', fontSize:10, fontWeight:'700', flex:1 }} numberOfLines={1}>
                                                            {p.id ? playerDisplayName(p) : p.manualName}{reqGenderParen(p.gender, t.lang)}{p.skillRating != null ? `  ⭐${Number(p.skillRating).toFixed(2)}` : ''}
                                                        </Text>
                                                    </TouchableOpacity>
                                                ))}
                                            </View>
                                        </View>
                                    )}
                                </View>
                            );
                        })() : item.matchType === 'SINGLE' ? (
                            // Tekler (1v1) — kullanıcı raporu: "açık ilanlarda da yaklaşan maçlarda da
                            // dıgımon kart yok, olması lazımdı". DOUBLE/takım sporlarıyla AYNI görsel dil:
                            // ön yüz "Katılan Oyuncular" (dolu olanlar, numaralı), arka yüz Kurucu/Rakip
                            // etiketli 2 kutu. Davet/başvuru mekanizması DEĞİŞMEDİ — SINGLE'da zaten alttaki
                            // genel "Katıl" butonu (handleJoin) çalışıyordu, burada sadece görünüm eklendi.
                            !showTeamCards ? (
                                <View style={{ flexDirection:'row', flexWrap:'wrap', gap:6 }}>
                                    {[item.sender, ...(participants[0]?.id ? [participants[0]] : [])].filter(p => p?.id).map((p, i) => (
                                        <TouchableOpacity key={p.id || i} style={{ width:'48%', flexDirection:'row', alignItems:'center', gap:6, backgroundColor:'#1e293b', borderRadius:8, borderWidth:1, borderColor: colors.border+'40', paddingVertical:6, paddingHorizontal:8 }}
                                            onPress={() => p.id && navigation.push('Profile', { userId: p.id })}>
                                            <Avatar name={p.username} avatar={p.avatar} size={moderateScale(28)} color={cfg.color} />
                                            <View style={{ flex:1, minWidth:0 }}>
                                                <View style={{ flexDirection:'row', alignItems:'center' }}>
                                                    <Text style={[det.playerName, { flexShrink:1 }]} numberOfLines={1}>{i + 1}. {playerDisplayName(p)}</Text>
                                                    {p.id && localOrderedUserIds.includes(p.id) && (
                                                        <TouchableOpacity onPress={() => p.id === myId && setShowMyOrder(true)} hitSlop={{ top:6, bottom:6, left:4, right:6 }} disabled={p.id !== myId}>
                                                            <Animated.Text style={{ fontSize:12, marginLeft:4, opacity: orderBlink }}>📋</Animated.Text>
                                                        </TouchableOpacity>
                                                    )}
                                                </View>
                                                <Text style={det.playerSub} numberOfLines={1}>{p.username}</Text>
                                            </View>
                                        </TouchableOpacity>
                                    ))}
                                </View>
                            ) : (
                                <View style={{ flexDirection:'row', flexWrap:'wrap', justifyContent:'space-between' }}>
                                    <View style={{ width:'48%', backgroundColor:'#1e293b', borderRadius:8, borderWidth:1, borderColor: colors.border+'40', paddingVertical:5, paddingHorizontal:6, marginBottom:6 }}>
                                        <TouchableOpacity style={{ flexDirection:'row', alignItems:'center', gap:6 }} onPress={() => item.senderId && navigation.push('Profile', { userId: item.senderId })}>
                                            <Avatar name={item.sender?.username} avatar={item.sender?.avatar} size={moderateScale(28)} color={cfg.color} />
                                            <View style={{ flex:1 }}>
                                                <View style={{ flexDirection:'row', alignItems:'center' }}>
                                                    <Text style={[det.playerName, { flexShrink:1 }]} numberOfLines={1}>{playerDisplayName(item.sender)}</Text>
                                                    {item.senderId && localOrderedUserIds.includes(item.senderId) && (
                                                        <TouchableOpacity onPress={() => item.senderId === myId && setShowMyOrder(true)} hitSlop={{ top:6, bottom:6, left:4, right:6 }} disabled={item.senderId !== myId}>
                                                            <Animated.Text style={{ fontSize:12, marginLeft:4, opacity: orderBlink }}>📋</Animated.Text>
                                                        </TouchableOpacity>
                                                    )}
                                                </View>
                                                <Text style={det.playerSub} numberOfLines={1}>{item.sender?.username} · {t.founder || 'Kurucu'}</Text>
                                            </View>
                                        </TouchableOpacity>
                                    </View>
                                    <View style={{ width:'48%', backgroundColor:'#1e293b', borderRadius:8, borderWidth:1, borderColor: colors.border+'40', paddingVertical:5, paddingHorizontal:6, marginBottom:6 }}>
                                        {participants[0]?.id ? (
                                            <>
                                                <TouchableOpacity style={{ flexDirection:'row', alignItems:'center', gap:6 }} onPress={() => navigation.push('Profile', { userId: participants[0].id })}>
                                                    <Avatar name={participants[0].username} avatar={participants[0].avatar} size={moderateScale(28)} color={cfg.color} />
                                                    <View style={{ flex:1 }}>
                                                        <View style={{ flexDirection:'row', alignItems:'center' }}>
                                                            <Text style={[det.playerName, { flexShrink:1 }]} numberOfLines={1}>{playerDisplayName(participants[0])}</Text>
                                                            {participants[0].id && localOrderedUserIds.includes(participants[0].id) && (
                                                                <TouchableOpacity onPress={() => participants[0].id === myId && setShowMyOrder(true)} hitSlop={{ top:6, bottom:6, left:4, right:6 }} disabled={participants[0].id !== myId}>
                                                                    <Animated.Text style={{ fontSize:12, marginLeft:4, opacity: orderBlink }}>📋</Animated.Text>
                                                                </TouchableOpacity>
                                                            )}
                                                        </View>
                                                        <Text style={det.playerSub} numberOfLines={1}>
                                                            {genderReq !== 'MIX' && <Text style={{ color:'#a855f7', fontWeight:'700' }}>{genderReq === 'MALE' ? '(Erkek) ' : '(Kadın) '}</Text>}
                                                            {participants[0].username}
                                                        </Text>
                                                    </View>
                                                </TouchableOpacity>
                                                {isOwner && (
                                                    <TouchableOpacity onPress={() => removeRivalParticipant(participants[0].id, participants[0].username)} style={{ marginTop:3, alignSelf:'flex-end' }}>
                                                        <Text style={{ color:'#f87171', fontSize:moderateScale(10), fontWeight:'700' }}>Çıkar</Text>
                                                    </TouchableOpacity>
                                                )}
                                            </>
                                        ) : (
                                            <View style={{ flexDirection:'row', alignItems:'center', gap:6, opacity:0.55 }}>
                                                <View style={{ width:moderateScale(28), height:moderateScale(28), borderRadius:moderateScale(14), borderWidth:1, borderStyle:'dashed', borderColor: colors.textMuted, alignItems:'center', justifyContent:'center' }}>
                                                    <Text style={{ color: colors.textMuted, fontSize:13 }}>?</Text>
                                                </View>
                                                <View style={{ flex:1 }}>
                                                    <Text style={[det.playerSub, { color: colors.textMuted }]} numberOfLines={1}>
                                                        {genderReq !== 'MIX' && <Text style={{ color:'#a855f7', fontWeight:'700' }}>{genderReq === 'MALE' ? '(Erkek) ' : '(Kadın) '}</Text>}
                                                        {t.opponentTeamShortLabel || 'Rakip'}
                                                    </Text>
                                                    <Text style={[det.playerSub, { color: colors.textMuted, fontSize:9 }]} numberOfLines={1}>Bekleniyor</Text>
                                                </View>
                                            </View>
                                        )}
                                    </View>
                                </View>
                            )
                        ) : (
                            <>
                                <View style={det.playerRow}>
                                    <Avatar name={item.sender?.username} avatar={item.sender?.avatar} size={moderateScale(32)} color={cfg.color} onPress={() => item.senderId && navigation.push('Profile', { userId: item.senderId })} />
                                    <View style={{ flex:1 }}>
                                        <View style={{ flexDirection:'row', alignItems:'center' }}>
                                            <Text style={[det.playerName, { flexShrink:1 }]}>{playerDisplayName(item.sender)}</Text>
                                            {item.senderId && localOrderedUserIds.includes(item.senderId) && (
                                                <TouchableOpacity onPress={() => item.senderId === myId && setShowMyOrder(true)} hitSlop={{ top:6, bottom:6, left:4, right:6 }} disabled={item.senderId !== myId}>
                                                    <Animated.Text style={{ fontSize:12, marginLeft:4, opacity: orderBlink }}>📋</Animated.Text>
                                                </TouchableOpacity>
                                            )}
                                            {/* Kullanıcı isteği: digimon kartlarda oyuncuların yanında elo puanı
                                                HER dalda gösterilsin, ilan detayına bakan HERKES (ilan sahibi
                                                dahil) görebilsin — burada (SINGLE/1v1 ilanlar) hiç yoktu. */}
                                            {item.sender?.interests?.[0]?.skillRating != null && (
                                                <Text style={{ color:'#facc15', fontSize:moderateScale(10), fontWeight:'800', marginLeft:4 }} numberOfLines={1}>{Number(item.sender.interests[0].skillRating).toFixed(2)}★</Text>
                                            )}
                                        </View>
                                        <Text style={det.playerSub}>{item.sender?.username} · {t.founder || 'Kurucu'}</Text>
                                    </View>
                                </View>
                                {participants.filter(p => p?.id).map((p, i) => (
                                    <View key={p.id || i} style={det.playerRow}>
                                        <Avatar name={p.username} avatar={p.avatar} size={moderateScale(32)} color={cfg.color} onPress={() => p.id && navigation.push('Profile', { userId: p.id })} />
                                        <View style={{ flex:1 }}>
                                            <View style={{ flexDirection:'row', alignItems:'center' }}>
                                                <Text style={[det.playerName, { flexShrink:1 }]}>{playerDisplayName(p)}</Text>
                                                {p.id && localOrderedUserIds.includes(p.id) && (
                                                    <TouchableOpacity onPress={() => p.id === myId && setShowMyOrder(true)} hitSlop={{ top:6, bottom:6, left:4, right:6 }} disabled={p.id !== myId}>
                                                        <Animated.Text style={{ fontSize:12, marginLeft:4, opacity: orderBlink }}>📋</Animated.Text>
                                                    </TouchableOpacity>
                                                )}
                                                {p.skillRating != null && (
                                                    <Text style={{ color:'#facc15', fontSize:moderateScale(10), fontWeight:'800', marginLeft:4 }} numberOfLines={1}>{Number(p.skillRating).toFixed(2)}★</Text>
                                                )}
                                            </View>
                                            <Text style={det.playerSub}>
                                                {genderReq !== 'MIX' && <Text style={{ color:'#a855f7', fontWeight:'700' }}>{genderReq === 'MALE' ? '(Erkek) ' : '(Kadın) '}</Text>}
                                                {p.username}
                                            </Text>
                                        </View>
                                        {isOwner && (
                                            <TouchableOpacity onPress={() => removeRivalParticipant(p.id, p.username)} style={{ padding:3 }}>
                                                <Text style={{ color:'#f87171', fontSize:moderateScale(11), fontWeight:'700' }}>Çıkar</Text>
                                            </TouchableOpacity>
                                        )}
                                    </View>
                                ))}
                                {Array.from({ length: Math.max(0, required - filled) }).map((_, i) => (
                                    <View key={`empty-${i}`} style={[det.playerRow, { opacity:0.55 }]}>
                                        <View style={{ width:moderateScale(32), height:moderateScale(32), borderRadius:moderateScale(16), borderWidth:1, borderStyle:'dashed', borderColor: colors.textMuted, alignItems:'center', justifyContent:'center' }}>
                                            <Text style={{ color: colors.textMuted, fontSize:14 }}>?</Text>
                                        </View>
                                        <View style={{ flex:1 }}>
                                            <Text style={[det.playerSub, { color: colors.textMuted }]}>
                                                {genderReq !== 'MIX' && <Text style={{ color:'#a855f7', fontWeight:'700' }}>{genderReq === 'MALE' ? '(Erkek) ' : '(Kadın) '}</Text>}
                                                Bekleniyor
                                            </Text>
                                        </View>
                                    </View>
                                ))}
                            </>
                        )}
                        </Animated.View>
                    </View>

                    {/* İstekler — kullanıcı isteği: kadroya katılmamış olsalar bile maç detayına
                        giren HERKES kimlerin başvurduğunu görebilsin (ör. sevmediği biri zaten
                        başvurmuşsa kendisi başvurmayabilsin); kabul/red butonları yine sadece ilan
                        sahibinde kalır (bkz. aşağıdaki isOwner kontrolü). */}
                    {joinRequests.filter(jr => jr.initiatedBy !== 'OWNER').length > 0 && (
                        <View style={det.section}>
                            {/* Kullanıcı isteği: yer tasarrufu için en sağdaki oka dokununca açılıp
                                kapanıyor — varsayılan kapalı. */}
                            <TouchableOpacity onPress={() => setRequestsExpanded(v => !v)} style={{ flexDirection:'row', alignItems:'center' }}>
                                <Text style={[det.sectionTitle, { flex:1 }]}>📬 {t.requests || 'İstekler'} ({joinRequests.filter(jr => jr.initiatedBy !== 'OWNER').length})</Text>
                                <Text style={{ color:'#fff', fontSize:14 }}>{requestsExpanded ? '▼' : '◀'}</Text>
                            </TouchableOpacity>
                            {/* Kullanıcı raporu: ilan sahibi olmayan biri kabul/red'e dokununca backend'den
                                çıplak "Forbidden" hatası dönüyordu — bu istekleri SADECE ilan sahibi
                                yanıtlayabilir (bkz. respondToJoin). Sahibi değilse butonlar yerine ne
                                yapabileceğini (davet gönderebilir mi, "kilit" açık mı) anlatan tek satırlık
                                bir not gösterilir. */}
                            {requestsExpanded && !isOwner && (
                                <Text style={{ color: colors.textMuted, fontSize: moderateScale(10), marginBottom:6 }}>
                                    {item.participantsCanInvite ? t.requestsOwnerOnlyCanInviteHint : t.requestsOwnerOnlyHint}
                                </Text>
                            )}
                            {requestsExpanded && (item.matchType === 'DOUBLE' && item.teamFlexibility === 'STRICT' ? (() => {
                                // STRICT çiftler maçında başvuran, hangi slota (Kurucu Takımı /
                                // Rakip 1 / Rakip 2) başvurduğunu request sırasında zaten seçmişti
                                // (requestedSlot) — burada eşleştirme/partner mantığına gerek yok,
                                // sadece hangi slotu istediği açıkça gösterilir.
                                const slotLabel = (slot) => slot === 'partner' ? t.founderTeamLabel : slot === 'opp1' ? t.opp1Label : slot === 'opp2' ? t.opp2Label : t.opp1Label;
                                return joinRequests.filter(jr => jr.initiatedBy !== 'OWNER').map(jr => (
                                    <View key={jr.id} style={det.playerRow}>
                                        <Avatar name={jr.user?.username} avatar={jr.user?.avatar} size={moderateScale(32)} color={cfg.color} onPress={() => jr.user?.id && navigation.push('Profile', { userId: jr.user.id })} />
                                        <View style={{ flex:1 }}>
                                            <Text style={det.playerName}>{playerDisplayName(jr.user)}</Text>
                                            <Text style={det.playerSub}>
                                                {jr.user?.username} · 🕐 {reqTimeAgo(jr.createdAt)}{jr.user?.interests?.find(i => i.subCategory === sub)?.skillRating != null ? `  ${Number(jr.user.interests.find(i => i.subCategory === sub).skillRating).toFixed(2)} ★` : ''}{reqGenderParen(jr.user?.gender, t.lang)}
                                            </Text>
                                            <Text style={{ color: cfg.color, fontSize:moderateScale(10), fontWeight:'700', marginTop:1 }} numberOfLines={1}>
                                                → {slotLabel(jr.requestedSlot)}
                                            </Text>
                                        </View>
                                        {isOwner && (jr.status === 'AWAITING_JOINER_CONFIRM' ? (
                                            <Text style={{ color:'#fbbf24', fontSize: moderateScale(10), fontWeight:'700' }}>⏳ Son Onay Bekleniyor</Text>
                                        ) : (
                                            <View style={{ flexDirection:'row', gap:3 }}>
                                                <TouchableOpacity style={[s.acceptBtn, { borderRadius: moderateScale(8), width: moderateScale(28), height: moderateScale(28) }]} onPress={() => acceptLocal(jr.id)}>
                                                    <Text style={{ color:'#fff', fontSize:moderateScale(12), fontWeight:'700' }}>✓</Text>
                                                </TouchableOpacity>
                                                <TouchableOpacity style={[s.declineBtn, { borderRadius: moderateScale(8), width: moderateScale(28), height: moderateScale(28) }]} onPress={() => rejectLocal(jr.id)}>
                                                    <Text style={{ color:'#fff', fontSize:moderateScale(12), fontWeight:'700' }}>✕</Text>
                                                </TouchableOpacity>
                                            </View>
                                        ))}
                                    </View>
                                ));
                            })() : item.matchType === 'DOUBLE' ? (() => {
                                // Hâlâ boş olan koltukların cinsiyet gereksinimine uyan istekler
                                // öne alınır — sahibi kotayı dolduracak adayları hemen görsün.
                                const senderTeamNow = Array.isArray(item.senderTeam) ? item.senderTeam : [];
                                const openGenderReqs = [
                                    !senderTeamNow[0]?.id && partnerGenderReq,
                                    !participants[0]?.id && opp1GenderReq,
                                    !participants[1]?.id && opp2GenderReq,
                                ].filter(g => g && g !== 'MIX');
                                const fitsOpenSlot = (jr) => {
                                    if (openGenderReqs.length === 0) return true;
                                    const g = jr.user?.gender;
                                    if (!g || g === 'OTHER') return true;
                                    return openGenderReqs.includes(g);
                                };
                                const incoming = joinRequests.filter(jr => jr.initiatedBy !== 'OWNER')
                                    .slice()
                                    .sort((a, b) => (fitsOpenSlot(a) === fitsOpenSlot(b) ? 0 : fitsOpenSlot(a) ? -1 : 1));
                                const { pairs, solos, byUserId } = groupDoublesPairs(incoming);
                                const solosWithPartnerLink = solos.filter(s => s.partnerId || solos.some(o => o.partnerId === s.userId && o.userId !== s.userId));
                                const solosIndividual = solos.filter(s => !s.partnerId && !solos.some(o => o.partnerId === s.userId && o.userId !== s.userId));
                                return (
                                    <View>
                                        <View style={{ flexDirection:'row', flexWrap:'wrap', justifyContent:'space-between' }}>
                                            {pairs.map(([a, b]) => renderRivalDuoCard(a, b, solos, byUserId))}
                                            {solosWithPartnerLink.map(s => renderRivalDuoCard(s, null, solos, byUserId))}
                                        </View>
                                        {solosIndividual.map(jr => (
                                            <View key={jr.id} style={det.playerRow}>
                                                <Avatar name={jr.user?.username} avatar={jr.user?.avatar} size={moderateScale(32)} color={cfg.color} onPress={() => jr.user?.id && navigation.push('Profile', { userId: jr.user.id })} />
                                                <View style={{ flex:1 }}>
                                                    <Text style={det.playerName}>{playerDisplayName(jr.user)}</Text>
                                                    <Text style={det.playerSub}>{jr.user?.username} · 🕐 {reqTimeAgo(jr.createdAt)}{jr.user?.interests?.find(i => i.subCategory === sub)?.skillRating != null ? `  ${Number(jr.user.interests.find(i => i.subCategory === sub).skillRating).toFixed(2)} ★` : ''}{reqGenderParen(jr.user?.gender, t.lang)}</Text>
                                                </View>
                                                {isOwner && (jr.status === 'AWAITING_JOINER_CONFIRM' ? (
                                                    <Text style={{ color:'#fbbf24', fontSize: moderateScale(10), fontWeight:'700' }}>⏳ Son Onay Bekleniyor</Text>
                                                ) : (
                                                    <View style={{ flexDirection:'row', gap:3 }}>
                                                        <TouchableOpacity style={[s.acceptBtn, { borderRadius: moderateScale(8), width: moderateScale(28), height: moderateScale(28) }]} onPress={() => acceptLocal(jr.id)}>
                                                            <Text style={{ color:'#fff', fontSize:moderateScale(12), fontWeight:'700' }}>✓</Text>
                                                        </TouchableOpacity>
                                                        <TouchableOpacity style={[s.declineBtn, { borderRadius: moderateScale(8), width: moderateScale(28), height: moderateScale(28) }]} onPress={() => rejectLocal(jr.id)}>
                                                            <Text style={{ color:'#fff', fontSize:moderateScale(12), fontWeight:'700' }}>✕</Text>
                                                        </TouchableOpacity>
                                                    </View>
                                                ))}
                                            </View>
                                        ))}
                                    </View>
                                );
                            })() : joinRequests.filter(jr => jr.initiatedBy !== 'OWNER')
                                .slice()
                                .sort((a, b) => {
                                    const fits = (jr) => {
                                        if (!genderReq || genderReq === 'MIX') return true;
                                        const g = jr.user?.gender;
                                        if (!g || g === 'OTHER') return true;
                                        return g === genderReq;
                                    };
                                    return fits(a) === fits(b) ? 0 : fits(a) ? -1 : 1;
                                })
                                .map(jr => (
                                <View key={jr.id} style={det.playerRow}>
                                    <Avatar name={jr.user?.username} avatar={jr.user?.avatar} size={moderateScale(32)} color={cfg.color} onPress={() => jr.user?.id && navigation.push('Profile', { userId: jr.user.id })} />
                                    {/* Voleybol "Rakip Aranıyor": tek isim yerine tam takım kadrosu + ortalama
                                        puan gösterilir — bkz. TeamJoinRequestModal (bu isteği gönderen kişi
                                        kendi tam takımını doldurup göndermişti). */}
                                    {Array.isArray(jr.joiningTeam) && jr.joiningTeam.length > 0 ? (
                                        <View style={{ flex:1 }}>
                                            <Text style={det.playerName}>
                                                {t.teamJoinRequestLabel}
                                                {(() => {
                                                    const ratings = jr.joiningTeam.filter(m => !m.isSubstitute && m.skillRating != null).map(m => m.skillRating);
                                                    const avg = ratings.length > 0 ? ratings.reduce((a, b) => a + b, 0) / ratings.length : null;
                                                    return avg != null ? `  Ort ${avg.toFixed(2)}★` : '';
                                                })()}
                                            </Text>
                                            <Text style={det.playerSub} numberOfLines={2}>
                                                {jr.joiningTeam.filter(m => !m.isSubstitute).map(m => m.username || m.fullName || m.manualName).join(', ')}
                                            </Text>
                                            {jr.joiningTeam.some(m => m.isSubstitute) && (
                                                <Text style={{ color: colors.textMuted, fontSize: moderateScale(9) }} numberOfLines={1}>
                                                    {t.subsLabel}: {jr.joiningTeam.filter(m => m.isSubstitute).map(m => m.username || m.fullName || m.manualName).join(', ')}
                                                </Text>
                                            )}
                                            <Text style={{ color: colors.textMuted, fontSize: moderateScale(9) }}>🕐 {reqTimeAgo(jr.createdAt)}</Text>
                                        </View>
                                    ) : (
                                        <View style={{ flex:1 }}>
                                            <Text style={det.playerName}>{playerDisplayName(jr.user)}</Text>
                                            <Text style={det.playerSub}>{jr.user?.username} · 🕐 {reqTimeAgo(jr.createdAt)}{jr.user?.interests?.find(i => i.subCategory === sub)?.skillRating != null ? `  ${Number(jr.user.interests.find(i => i.subCategory === sub).skillRating).toFixed(2)} ★` : ''}{reqGenderParen(jr.user?.gender, t.lang)}</Text>
                                            {jr.requestedSlot && (
                                                <Text style={{ color:'#a855f7', fontSize: moderateScale(9), fontWeight:'700', marginTop:1 }}>
                                                    🎯 {jr.requestedSlot === 'partner' ? t.founderTeamLabel : jr.requestedSlot === 'opp1' ? t.opp1Label : jr.requestedSlot === 'opp2' ? t.opp2Label : t.joinAsOpponentBtn}
                                                </Text>
                                            )}
                                            {/* Kullanıcı isteği: voleybolde başvuran hangi pozisyon(lar)ı istediğini
                                                (öncelik sırasıyla) belirtmişse, ilan sahibi kabul/red kararını buna
                                                göre versin diye burada gösterilir. */}
                                            {Array.isArray(jr.positionPreferences) && jr.positionPreferences.length > 0 && (
                                                <Text style={{ color:'#38bdf8', fontSize: moderateScale(9), fontWeight:'700', marginTop:1 }} numberOfLines={1}>
                                                    🏐 {jr.positionPreferences.map((p, i) => `${i + 1}. ${p === 'SETTER' ? t.positionSetter : p === 'SPIKER' ? t.positionSpiker : t.positionLibero}`).join('  ')}
                                                </Text>
                                            )}
                                        </View>
                                    )}
                                    {isOwner && (jr.status === 'AWAITING_JOINER_CONFIRM' ? (
                                        <Text style={{ color:'#fbbf24', fontSize: moderateScale(10), fontWeight:'700' }}>⏳ Son Onay Bekleniyor</Text>
                                    ) : (
                                        <View style={{ flexDirection:'row', gap:3 }}>
                                            <TouchableOpacity style={[s.acceptBtn, { borderRadius: moderateScale(8), width: moderateScale(28), height: moderateScale(28) }]} onPress={() => acceptLocal(jr.id)}>
                                                <Text style={{ color:'#fff', fontSize:moderateScale(12), fontWeight:'700' }}>✓</Text>
                                            </TouchableOpacity>
                                            <TouchableOpacity style={[s.declineBtn, { borderRadius: moderateScale(8), width: moderateScale(28), height: moderateScale(28) }]} onPress={() => rejectLocal(jr.id)}>
                                                <Text style={{ color:'#fff', fontSize:moderateScale(12), fontWeight:'700' }}>✕</Text>
                                            </TouchableOpacity>
                                        </View>
                                    ))}
                                </View>
                            )))}
                        </View>
                    )}
                    {/* Ilan sahibinin gönderdiği (OWNER) davetler — kullanıcı isteği: DOUBLE'da davet
                        durumu artık kadro kartının İÇİNDE (ne ön ne arka yüzde) hiç gösterilmiyor,
                        SADECE burada — bu yüzden partner davetleri de (önceden Kurucu Takımı
                        panelinde ayrıca gösterildiği için burada hariç tutuluyordu) artık listede.
                        Hangi role davet edildiği (Takım Arkadaşı/Rakip 1/Rakip 2) satırda yazıyor.
                        Liste herkese görünür; iptal (✕) sahipte, kabul/red (✓/✕) SADECE daveti alan
                        kişide — kabul edince backend zaten doğru yere yerleştiriyor (isPartnerInvite→
                        senderTeam, requestedSlot varsa o participants index'i, yoksa unassignedPlayers)
                        ve kişi ön yüzde onay sırasına göre, arka yüzde de rolüne göre görünür. */}
                    {joinRequests.filter(jr => jr.initiatedBy === 'OWNER').length > 0 && (
                        <View style={det.section}>
                            <Text style={det.sectionTitle}>📨 Gönderilen Davetler</Text>
                            {joinRequests.filter(jr => jr.initiatedBy === 'OWNER').map(jr => {
                                const slotLabel = isRefereeAd ? '🟨 Hakemlik Daveti'
                                    : item.matchType !== 'DOUBLE' ? null
                                    : jr.isPartnerInvite ? 'Takım Arkadaşı'
                                    : jr.requestedSlot === 'opp1' ? 'Rakip 1'
                                    : jr.requestedSlot === 'opp2' ? 'Rakip 2'
                                    : null;
                                const isMyInvite = jr.userId === myId;
                                return (
                                    <View key={jr.id} style={det.playerRow}>
                                        <Avatar name={jr.user?.username} avatar={jr.user?.avatar} size={moderateScale(32)} color={cfg.color} onPress={() => jr.user?.id && navigation.push('Profile', { userId: jr.user.id })} />
                                        <View style={{ flex:1 }}>
                                            <Text style={det.playerName}>{playerDisplayName(jr.user)}{!isRefereeAd && jr.user?.interests?.find(i => i.subCategory === sub)?.skillRating != null ? `  ${Number(jr.user.interests.find(i => i.subCategory === sub).skillRating).toFixed(2)} ★` : ''}</Text>
                                            <Text style={{ color:'#fbbf24', fontSize: moderateScale(10), fontWeight:'700' }}>{slotLabel ? `${slotLabel} — ` : ''}⏳ Onay Bekleniyor</Text>
                                            {/* Kullanıcı isteği: hakem daveti bildiriminden gelen kişi, kabul/red
                                                etmeden önce kendisine teklif edilen ücret/mesajı görebilmeli —
                                                önceden bu satırda hiç gösterilmiyordu, ne teklif edildiği belirsizdi. */}
                                            {isRefereeAd && jr.offerPrice && (
                                                <Text style={{ color:'#4ade80', fontSize: moderateScale(10), fontWeight:'700', marginTop:2 }}>💰 {jr.offerPrice}</Text>
                                            )}
                                            {isRefereeAd && jr.offerMessage && (
                                                <Text style={{ color: colors.textSecondary, fontSize: moderateScale(10), marginTop:2 }} numberOfLines={2}>{jr.offerMessage}</Text>
                                            )}
                                        </View>
                                        {isMyInvite && (
                                            <TouchableOpacity onPress={() => acceptLocal(jr.id)} style={{ backgroundColor:'#16a34a', borderRadius: moderateScale(8), width: moderateScale(28), height: moderateScale(28), justifyContent:'center', alignItems:'center', marginRight:4 }}>
                                                <Text style={{ color:'#fff', fontSize: moderateScale(12), fontWeight:'700' }}>✓</Text>
                                            </TouchableOpacity>
                                        )}
                                        {(isOwner || isMyInvite) && (
                                            <TouchableOpacity onPress={() => (isOwner ? withdrawSentInvite(jr.id) : rejectLocal(jr.id))} style={{ backgroundColor:'#dc262620', borderRadius: moderateScale(8), width: moderateScale(28), height: moderateScale(28), justifyContent:'center', alignItems:'center', borderWidth:1, borderColor:'#dc262650' }}>
                                                <Text style={{ color:'#f87171', fontSize: moderateScale(12), fontWeight:'700' }}>✕</Text>
                                            </TouchableOpacity>
                                        )}
                                    </View>
                                );
                            })}
                        </View>
                    )}

                    {/* Hakem Slotu — ilan sahibi + katılımcılar için özet, kimin hakem olduğunu gösterir.
                        Hakemler sekmesinden ilanın kendi detayı açıldığında da (isRefereeAd) görünür. */}
                    {(() => {
                        // Kullanıcı isteği: hakem slotunu SADECE ilan sahibi/oyuncular değil, o maçın
                        // hakemi (atanmış ya da sırada bekleyen) da görebilsin — önceden hakemler
                        // (kadroda hiç yer almadıkları için isParticipant/isOwner asla true olmuyordu)
                        // kendi atandıkları/sıraya girdikleri maçta bu kutuyu hiç göremiyordu.
                        const iAmQueuedReferee = Array.isArray(item.refereeQueue) && item.refereeQueue.some(q => q.userId === myId);
                        const canSeeRefereeSlot = (item.refereeRequested || isRefereeAd)
                            && (isMatchRosterMember || isLinkedMatchPlayer || item.refereeId === myId || iAmQueuedReferee);
                        if (!canSeeRefereeSlot) return null;
                        return (
                            <View style={{ marginBottom:8, backgroundColor:'#f59e0b0d', borderRadius: moderateScale(8), borderWidth:1, borderColor:'#f59e0b30', paddingHorizontal:9, paddingVertical:6 }}>
                            <View style={{ flexDirection:'row', alignItems:'center', gap:6 }}>
                                {item.refereeUser ? (
                                    <>
                                        <Avatar name={item.refereeUser.username} avatar={item.refereeUser.avatar} size={moderateScale(24)} color="#f59e0b" />
                                        <Text style={{ color:'#f59e0b', fontSize:moderateScale(12), fontWeight:'700', flex:1 }} numberOfLines={1} adjustsFontSizeToFit minimumFontScale={0.75}>{t.refereeSlotLabel}: {item.refereeUser.fullName || item.refereeUser.username} ✓</Text>
                                        {/* Kullanıcı isteği: hakem zaten atanmışken bile yedek/değişiklik için
                                            başka bir hakem davet edilebilsin — İtiraz Et'in SOLUNA eklendi.
                                            Kabul edilirse respondToJoin (rival.controller.js) mevcut hakemin
                                            yerine yenisini yazıyor ve itiraz oylarını sıfırlıyor, bu yüzden
                                            burada ayrı bir "çıkar" adımına gerek yok — davet kabul edilince
                                            otomatik değişiyor. */}
                                        {!!refereeAdId && (isOwner || ((isParticipant || isLinkedMatchPlayer) && (item.participantsCanInvite || item.linkedRival?.participantsCanInvite))) && (
                                            <TouchableOpacity onPress={() => { setInviteForReferee(true); setInviteModalVisible(true); }} style={{ marginRight:2 }}>
                                                <Text style={{ color:'#f59e0b', fontSize:moderateScale(11), fontWeight:'700' }} numberOfLines={1}>{noEmojiStr(t.inviteRefereeBtn)}</Text>
                                            </TouchableOpacity>
                                        )}
                                        {/* Kullanıcı isteği: "hakemi çıkarmak istiyorum ama çıkar yok" —
                                            ilan sahibi kadro oyu toplamadan TEK BAŞINA hakemi çıkarabilsin
                                            (removeAssignedReferee). Diğer kadro üyeleri için oylamalı
                                            İtiraz Et (disputeRefereeUser) aynen kalıyor. */}
                                        {isOwner ? (
                                            <TouchableOpacity disabled={disputingReferee} onPress={removeAssignedReferee} style={{ opacity: disputingReferee ? 0.5 : 1 }}>
                                                <Text style={{ color:'#f87171', fontSize:moderateScale(11), fontWeight:'700' }}>✕ {t.refereeRemoveBtn}</Text>
                                            </TouchableOpacity>
                                        ) : isMatchRosterMember && (
                                            <TouchableOpacity disabled={disputingReferee} onPress={disputeRefereeUser} style={{ opacity: disputingReferee ? 0.5 : 1 }}>
                                                <Text style={{ color:'#f87171', fontSize:moderateScale(11), fontWeight:'700' }}>🚩 {t.refereeDisputeBtn}</Text>
                                            </TouchableOpacity>
                                        )}
                                    </>
                                ) : item.manualRefereeName ? (
                                    <>
                                        <View style={{ width:moderateScale(24), height:moderateScale(24), borderRadius:moderateScale(12), backgroundColor:'#f59e0b20', alignItems:'center', justifyContent:'center' }}>
                                            <Text style={{ fontSize:12 }}>🧑‍⚖️</Text>
                                        </View>
                                        <Text style={{ color:'#f59e0b', fontSize:moderateScale(12), fontWeight:'700', flex:1 }} numberOfLines={1} adjustsFontSizeToFit minimumFontScale={0.75}>{t.refereeSlotLabel}: {item.manualRefereeName}{item.refereePayment ? `  ·  ${item.refereePayment}` : ''}</Text>
                                    </>
                                ) : (
                                    // Kullanıcı isteği: "Hakem Davet Et" butonu artık burada değil,
                                    // aşağıdaki "Oyuncu Davet Et" ile aynı satırda (sağında) gösteriliyor.
                                    <Text style={{ color:'#f59e0b', fontSize:moderateScale(12), fontWeight:'700', flex:1 }} numberOfLines={1} adjustsFontSizeToFit minimumFontScale={0.75}>
                                        {t.refereeSlotLabel}: {t.refereeSlotSearching}{item.refereePayment ? `  ·  ${item.refereePayment}` : ''}
                                    </Text>
                                )}
                            </View>
                            {/* Kullanıcı isteği: kabul edilip sıraya giren yedek hakemler burada
                                listelensin — kendisi sıradaysa "(Sen)" ile ayrıca belirtiliyor,
                                yoksa hiç göremeyip "hiçbir şey olmadı" sanıyordu. */}
                            {Array.isArray(item.refereeQueue) && item.refereeQueue.length > 0 && (
                                <Text style={{ color:'#f59e0b', fontSize:moderateScale(10), fontWeight:'600', marginTop:6, paddingTop:6, borderTopWidth:1, borderTopColor:'#f59e0b30' }}>
                                    🕓 Yedek Sırası: {item.refereeQueue.map((q, i) => `${i + 1}. ${q.fullName || q.username}${q.userId === myId ? ' (Sen)' : ''}`).join('  ·  ')}
                                </Text>
                            )}
                            </View>
                        );
                    })()}

                    {/* Hakem Başvuruları — ilan sahibi + katılımcılar ortak görür; sahibi kabul/red/karşı teklif verebilir.
                        Hakemler sekmesinden ilanın kendi detayı açıldığında da (isRefereeAd) görünür.
                        Kullanıcı isteği: onaylanan başvuru burada TEKRAR gösterilmiyor — o bilgi zaten
                        yukarıdaki "Hakem Slotu" özet kutusunda (Hakem: X ✓) var, burada sadece diğer
                        (bekleyen/karşı teklifli) başvurular kalır. */}
                    {(() => {
                        const pendingRefereeApplications = refereeApplications.filter(app => app.status !== 'ACCEPTED');
                        // Kullanıcı isteği: kadroda olmasa bile, kendisine bu maç için hakemlik
                        // daveti gelmiş/başvurmuş biri de bu bölümü görüp kendi davetine kabul/red
                        // verebilsin — bildirime tıklayınca doğrudan burada işlem yapabilmeli.
                        const iAmInvitedOrApplied = refereeApplications.some(app => app.userId === myId);
                        return (item.refereeRequested || isRefereeAd) && (isOwner || isParticipant || isLinkedMatchPlayer || iAmInvitedOrApplied) && pendingRefereeApplications.length > 0 && (
                        <View style={{ marginBottom:10, backgroundColor:'#f59e0b0d', borderRadius: moderateScale(8), borderWidth:1, borderColor:'#f59e0b30', padding:6 }}>
                            <Text style={{ color:'#f59e0b', fontSize:moderateScale(10), fontWeight:'800', marginBottom:4 }}>{t.refereeApplicationsTitle}</Text>
                            {pendingRefereeApplications.map(app => (
                                <View key={app.id} style={{ marginBottom:4, paddingBottom:4, borderBottomWidth:1, borderBottomColor:'#f59e0b20' }}>
                                    <View style={{ flexDirection:'row', alignItems:'center', gap:4 }}>
                                        <Avatar name={app.user?.username} avatar={app.user?.avatar} size={moderateScale(20)} color="#f59e0b" />
                                        <View style={{ flex:1 }}>
                                            <Text style={{ color:'#fff', fontSize:moderateScale(10), fontWeight:'700' }}>{app.user?.fullName || app.user?.username}</Text>
                                            {app.offerPrice && <Text style={{ color:'#f59e0b', fontSize:moderateScale(9), fontWeight:'700' }}>{app.offerPrice}</Text>}
                                        </View>
                                        {app.status === 'ACCEPTED' && (
                                            <View style={{ backgroundColor:'#16a34a20', borderRadius:5, paddingHorizontal:5, paddingVertical:1, borderWidth:1, borderColor:'#16a34a50' }}>
                                                <Text style={{ color:'#4ade80', fontSize:moderateScale(9), fontWeight:'700' }}>✓ {t.refereeAcceptedLabel}</Text>
                                            </View>
                                        )}
                                        {app.status === 'COUNTERED' && (
                                            <View style={{ backgroundColor:'#f59e0b20', borderRadius:5, paddingHorizontal:5, paddingVertical:1, borderWidth:1, borderColor:'#f59e0b50' }}>
                                                <Text style={{ color:'#f59e0b', fontSize:moderateScale(9), fontWeight:'700' }}>↔ {app.counterPrice}</Text>
                                            </View>
                                        )}
                                    </View>
                                    {app.offerMessage && <Text style={{ color: colors.textSecondary, fontSize:moderateScale(9), marginTop:2 }}>{app.offerMessage}</Text>}
                                    {app.status === 'COUNTERED' && app.counterMessage && (
                                        <Text style={{ color:'#f59e0b', fontSize:moderateScale(9), marginTop:2, fontStyle:'italic' }}>{app.counterMessage}</Text>
                                    )}
                                    {app.offerCvUrl && (
                                        <TouchableOpacity onPress={() => Linking.openURL(app.offerCvUrl)} style={{ marginTop:2, alignSelf:'flex-start', backgroundColor:'#16a34a20', borderRadius:5, paddingHorizontal:6, paddingVertical:1, borderWidth:1, borderColor:'#16a34a50' }}>
                                            <Text style={{ color:'#4ade80', fontSize:moderateScale(9), fontWeight:'700' }}>CV</Text>
                                        </TouchableOpacity>
                                    )}
                                    {isOwner && app.status === 'COUNTERED' && (
                                        <Text style={{ color: colors.textMuted, fontSize:moderateScale(9), marginTop:2, fontStyle:'italic' }}>{t.refereeCounterPendingMsg}</Text>
                                    )}
                                    {/* Kullanıcı isteği: davet edilen kişi bildirimden buraya gelince kendi
                                        davetine burada doğrudan kabul/red verebilsin — sadece sahibe/kadroya
                                        pasif "onay bekleniyor" metni gösterilir, davet edilen kişiye butonlar. */}
                                    {app.initiatedBy === 'OWNER' && app.status === 'PENDING' && app.userId === myId && (
                                        <View style={{ flexDirection:'row', gap:4, marginTop:4 }}>
                                            <TouchableOpacity disabled={respondingAppId === app.id} style={{ flex:1, backgroundColor:'#16a34a', borderRadius:6, paddingVertical:3, alignItems:'center', opacity: respondingAppId === app.id ? 0.6 : 1 }} onPress={() => respondRefereeApplication(app.id, 'accept')}>
                                                <Text style={{ color:'#fff', fontSize:moderateScale(9), fontWeight:'700' }}>{t.inviteAcceptBtn}</Text>
                                            </TouchableOpacity>
                                            <TouchableOpacity disabled={respondingAppId === app.id} style={[s.cancelBtn, { flex:1, borderRadius:6, paddingVertical:3, opacity: respondingAppId === app.id ? 0.6 : 1 }]} onPress={() => respondRefereeApplication(app.id, 'reject')}>
                                                <Text style={[s.cancelBtnText, { fontSize:moderateScale(9) }]}>{t.inviteRejectBtn}</Text>
                                            </TouchableOpacity>
                                        </View>
                                    )}
                                    {app.initiatedBy === 'OWNER' && app.status === 'PENDING' && app.userId !== myId && (
                                        <Text style={{ color: colors.textMuted, fontSize:moderateScale(9), marginTop:2, fontStyle:'italic' }}>Davet gönderildi — onay bekleniyor</Text>
                                    )}
                                    {isOwner && app.initiatedBy !== 'OWNER' && app.status === 'PENDING' && counterInputFor !== app.id && (
                                        <View style={{ flexDirection:'row', gap:4, marginTop:4 }}>
                                            <TouchableOpacity disabled={respondingAppId === app.id} style={{ flex:1, backgroundColor:'#16a34a', borderRadius:6, paddingVertical:3, alignItems:'center', opacity: respondingAppId === app.id ? 0.6 : 1 }} onPress={() => respondRefereeApplication(app.id, 'accept')}>
                                                <Text style={{ color:'#fff', fontSize:moderateScale(9), fontWeight:'700' }}>{t.inviteAcceptBtn}</Text>
                                            </TouchableOpacity>
                                            <TouchableOpacity disabled={respondingAppId === app.id} style={{ flex:1, backgroundColor:'#f59e0b20', borderRadius:6, paddingVertical:3, alignItems:'center', borderWidth:1, borderColor:'#f59e0b60', opacity: respondingAppId === app.id ? 0.6 : 1 }} onPress={() => { setCounterInputFor(app.id); setCounterPriceInput(''); }}>
                                                <Text style={{ color:'#f59e0b', fontSize:moderateScale(9), fontWeight:'700' }}>{t.refereeCounterBtn}</Text>
                                            </TouchableOpacity>
                                            <TouchableOpacity disabled={respondingAppId === app.id} style={[s.cancelBtn, { flex:1, borderRadius:6, paddingVertical:3, opacity: respondingAppId === app.id ? 0.6 : 1 }]} onPress={() => respondRefereeApplication(app.id, 'reject')}>
                                                <Text style={[s.cancelBtnText, { fontSize:moderateScale(9) }]}>{t.inviteRejectBtn}</Text>
                                            </TouchableOpacity>
                                        </View>
                                    )}
                                    {isOwner && app.initiatedBy !== 'OWNER' && counterInputFor === app.id && (
                                        <View style={{ marginTop:4, gap:4 }}>
                                            <View style={{ flexDirection:'row', gap:4, alignItems:'center' }}>
                                                <TextInput
                                                    style={[s.fieldInput, { flex:1, marginBottom:0, fontSize:moderateScale(11), paddingVertical:4 }]}
                                                    value={counterPriceInput} onChangeText={setCounterPriceInput}
                                                    placeholder="450" placeholderTextColor={colors.textMuted} keyboardType="numeric" autoFocus
                                                />
                                                <TouchableOpacity style={{ backgroundColor:'#f59e0b', borderRadius:6, paddingVertical:6, paddingHorizontal:9 }} onPress={() => respondRefereeApplication(app.id, 'counter', counterPriceInput, counterMessageInput)}>
                                                    <Text style={{ color:'#fff', fontSize:moderateScale(9), fontWeight:'700' }}>{t.refereeCounterSendBtn}</Text>
                                                </TouchableOpacity>
                                                <TouchableOpacity onPress={() => { setCounterInputFor(null); setCounterPriceInput(''); setCounterMessageInput(''); }}>
                                                    <Text style={{ color: colors.textMuted, fontSize:moderateScale(14) }}>✕</Text>
                                                </TouchableOpacity>
                                            </View>
                                            <TextInput
                                                style={[s.fieldInput, { marginBottom:0, fontSize:moderateScale(11), paddingVertical:4 }]}
                                                value={counterMessageInput} onChangeText={setCounterMessageInput}
                                                placeholder={t.messageFieldLabel} placeholderTextColor={colors.textMuted}
                                            />
                                        </View>
                                    )}
                                </View>
                            ))}
                        </View>
                        );
                    })()}

                    {/* Katıl / İptal aksiyonu */}
                    <View style={{ marginBottom:14 }}>
                        {/* İlan sahibi her zaman oyuncu davet edip paylaşabilir; kabul edilmiş
                            katılımcılar bunu SADECE sahibi ilanı oluştururken/düzenlerken
                            "🔓 Davete İzin Ver"i açtıysa yapabilir (item.participantsCanInvite). */}
                        {(() => {
                            // Hakemler sekmesinden hakem ilanının kendi detayı açıldıysa (isRefereeAd),
                            // ilan sahibi olsa bile burası sadece hakemlikle ilgili olmalı — oyuncu
                            // davet et / paylaş gibi asıl maça ait aksiyonlar burada gösterilmez.
                            const otherCanAct = !isRefereeAd && (isParticipant || mySentReq === 'ACCEPTED') && item.participantsCanInvite;
                            const canInvite = !isRefereeAd && (isOwner || otherCanAct) && !isFull;
                            const canShare = !isRefereeAd && (isOwner || otherCanAct);
                            // Kullanıcı isteği: "Oyuncu Davet Et" solda, "Hakem Davet Et" sağda,
                            // aynı satırda — eskiden Hakem Davet Et yukarıdaki Hakem Slotu kutusunun
                            // içindeydi. Hakem sahibi/manuel isim zaten belirlenmişse hiç gösterilmez.
                            const canInviteRefereeBtn = (item.refereeRequested || isRefereeAd) && !item.refereeUser && !item.manualRefereeName
                                && (isOwner || ((isParticipant || isLinkedMatchPlayer) && (item.participantsCanInvite || item.linkedRival?.participantsCanInvite)))
                                && !!refereeAdId;
                            // Paylaş, ilan sahibiyken aşağıda Düzenle/İptal ile aynı satıra taşındı
                            // (kullanıcı isteği) — sadece izinli katılımcı (otherCanAct) burada kalıyor,
                            // onlar için Düzenle/İptal zaten hiç gösterilmiyor.
                            const canShareHere = canShare && !isOwner;
                            // Kullanıcı isteği: ilan sahibi için "Oyuncu Davet Et" artık burada değil,
                            // aşağıda Paylaş/Düzenle ile AYNI satırda (solda) gösteriliyor — izinli
                            // katılımcılar (otherCanAct) için ise değişmedi, hâlâ burada.
                            const canInviteHere = canInvite && !isOwner;
                            // Kullanıcı isteği: sadece ilan sahibi değil, bu maça katılan (kabul
                            // edilmiş) HERKES ilan detayından sipariş verebilsin — "Oyuncu Davet Et"
                            // ile aynı satırda (o satır zaten burada, izinli katılımcılar için).
                            const canOrderNonOwner = !isOwner && !!item.venueId && (
                                participants.some(p => p?.id === myId) || senderTeamArr.some(p => p?.id === myId)
                                || unassignedArr.some(p => p?.id === myId) || item.receiverId === myId
                            );
                            // Kullanıcı isteği: maça zaten katılmış (mySentReq==='ACCEPTED') biri için
                            // Oyuncu Davet Et/Paylaş/Maçtan Ayrıl artık ayrı ayrı satırlarda değil,
                            // TEK satırda birlikte gösterilir — ayrıca "Kabul edildiniz" rozetine de
                            // gerek yok (aşağıdaki bu üçü zaten sadece kabul edilmiş birine çıkıyor).
                            const canLeaveHere = mySentReq === 'ACCEPTED';
                            return (canInviteHere || canInviteRefereeBtn || canShareHere || canOrderNonOwner || canLeaveHere) && (
                                <>
                                    {(canInviteRefereeBtn || canOrderNonOwner) && (
                                        <View style={{ flexDirection:'row', gap:6, marginBottom:6 }}>
                                            {canInviteRefereeBtn && (
                                                <TouchableOpacity
                                                    style={{ flex:1, backgroundColor:'#f59e0b20', borderWidth:1, borderColor:'#f59e0b50', borderRadius: moderateScale(8), paddingVertical: moderateScale(5), alignItems:'center' }}
                                                    onPress={() => { setInviteForReferee(true); setInviteModalVisible(true); }}
                                                >
                                                    <Text style={{ color:'#f59e0b', fontSize: moderateScale(11), fontWeight:'700' }} numberOfLines={1} adjustsFontSizeToFit minimumFontScale={0.75}>{noEmojiStr(t.inviteRefereeBtn)}</Text>
                                                </TouchableOpacity>
                                            )}
                                            {canOrderNonOwner && (
                                                <TouchableOpacity
                                                    style={[s.cancelBtn, { flex:1, backgroundColor:'#22c55e20', borderColor:'#22c55e50', borderRadius: moderateScale(8), paddingVertical: moderateScale(5) }]}
                                                    onPress={() => setOrderVenueId(item.venueId)}
                                                >
                                                    <Text style={[s.cancelBtnText, { color:'#22c55e', fontSize: moderateScale(11) }]} numberOfLines={1} adjustsFontSizeToFit minimumFontScale={0.75}>📋 Sipariş Ver</Text>
                                                </TouchableOpacity>
                                            )}
                                        </View>
                                    )}
                                    {(canInviteHere || canShareHere || canLeaveHere) && (
                                        <View style={{ flexDirection:'row', gap:6, marginBottom:6 }}>
                                            {canInviteHere && (
                                                <TouchableOpacity
                                                    style={[s.joinBtn, { flex:1, backgroundColor: cfg.color + '20', borderWidth:1, borderColor: cfg.color + '50', borderRadius: moderateScale(8), paddingVertical: moderateScale(5) }]}
                                                    onPress={() => setInviteModalVisible(true)}
                                                >
                                                    <Text style={[s.joinBtnText, { color: cfg.color, fontSize: moderateScale(11) }]} numberOfLines={1} adjustsFontSizeToFit minimumFontScale={0.75}>{t.inviteBtn}</Text>
                                                </TouchableOpacity>
                                            )}
                                            {canShareHere && (
                                                <TouchableOpacity
                                                    style={[s.cancelBtn, { flex:1, borderRadius: moderateScale(8), paddingVertical: moderateScale(5) }]}
                                                    onPress={() => shareRival(item, t)}
                                                >
                                                    <Text style={[s.cancelBtnText, { fontSize: moderateScale(11) }]} numberOfLines={1} adjustsFontSizeToFit minimumFontScale={0.75}>{t.shareBtn || '📤 Paylaş'}</Text>
                                                </TouchableOpacity>
                                            )}
                                            {canLeaveHere && (
                                                <TouchableOpacity disabled={leavingMatch} onPress={handleLeaveMatch}
                                                    style={[s.cancelBtn, { flex:1, borderRadius: moderateScale(8), paddingVertical: moderateScale(5), opacity: leavingMatch ? 0.6 : 1 }]}>
                                                    <Text style={[s.cancelBtnText, { fontSize: moderateScale(11) }]} numberOfLines={1} adjustsFontSizeToFit minimumFontScale={0.75}>✕ {t.leaveMatchBtn}{leaveWithinPenaltyWindow ? ' ⚠️' : ''}</Text>
                                                </TouchableOpacity>
                                            )}
                                        </View>
                                    )}
                                </>
                            );
                        })()}
                        {isOwner && !isRefereeAd && !isFull && (sub === 'tennis' || sub === 'padel' || sub === 'badminton' || sub === 'table_tennis') && (
                            <TouchableOpacity
                                disabled={seedingDemoRival}
                                style={[s.joinBtn, { backgroundColor:'#7c3aed20', borderWidth:1, borderColor:'#7c3aed50', marginBottom:6, borderRadius: moderateScale(8), paddingVertical: moderateScale(6), opacity: seedingDemoRival ? 0.6 : 1 }]}
                                onPress={async () => {
                                    if (seedingDemoRivalRef.current) return;
                                    seedingDemoRivalRef.current = true;
                                    setSeedingDemoRival(true);
                                    try {
                                        const { data } = await api.post('/demo/rival-join', { rivalId: item.id });
                                        Alert.alert('', `Demo başvuru gönderildi: ${data.joined.join(', ')}`);
                                    } catch (e) {
                                        Alert.alert('', e?.response?.data?.message || t.actionFailed);
                                    } finally {
                                        seedingDemoRivalRef.current = false;
                                        setSeedingDemoRival(false);
                                    }
                                }}
                            >
                                <Text style={[s.joinBtnText, { color:'#a78bfa', fontSize: moderateScale(12) }]}>{seedingDemoRival ? '...' : '🤖 Demo Başvuru Gönder'}</Text>
                            </TouchableOpacity>
                        )}
                        {item.ticketUrl && (
                            <TouchableOpacity
                                style={{ backgroundColor: cfg.color, borderRadius: moderateScale(8), paddingVertical: moderateScale(5), marginBottom: 3, alignItems:'center' }}
                                onPress={() => Linking.openURL(item.ticketUrl)}
                            >
                                <Text style={{ color:'#fff', fontWeight:'800', fontSize: moderateScale(12) }}>{t.buyTicketBtn}</Text>
                            </TouchableOpacity>
                        )}
                        {isOwner && isRefereeAd ? null : isOwner ? (
                            <>
                                {/* Kullanıcı isteği: Oyuncu Davet Et solda, Paylaş ortada, Düzenle
                                    sağda — aynı satırda. Oyuncu Davet Et artık yukarıdaki kendi
                                    satırında değil (ilan sahibi için), burada gösteriliyor. */}
                                {!isRefereeAd && (
                                    <View style={{ flexDirection: 'row', gap: 3, marginBottom: 3 }}>
                                        {!isFull && (
                                            <TouchableOpacity
                                                style={[s.joinBtn, { flex: 1, backgroundColor: cfg.color + '20', borderWidth:1, borderColor: cfg.color + '50', borderRadius: moderateScale(8), paddingVertical: moderateScale(5) }]}
                                                onPress={() => setInviteModalVisible(true)}
                                            >
                                                <Text style={[s.joinBtnText, { color: cfg.color, fontSize: moderateScale(11) }]} numberOfLines={1} adjustsFontSizeToFit minimumFontScale={0.75}>{t.inviteBtn}</Text>
                                            </TouchableOpacity>
                                        )}
                                        <TouchableOpacity
                                            style={[s.cancelBtn, { flex: 1, borderRadius: moderateScale(8), paddingVertical: moderateScale(5) }]}
                                            onPress={() => shareRival(item, t)}
                                        >
                                            <Text style={[s.cancelBtnText, { fontSize: moderateScale(11) }]} numberOfLines={1} adjustsFontSizeToFit minimumFontScale={0.75}>{t.shareBtn || '📤 Paylaş'}</Text>
                                        </TouchableOpacity>
                                        <TouchableOpacity
                                            style={[s.cancelBtn, { flex: 1, backgroundColor: colors.purple + '20', borderColor: colors.purple + '40', borderRadius: moderateScale(8), paddingVertical: moderateScale(5) }]}
                                            onPress={() => { onClose(); setTimeout(onEdit, 300); }}
                                        >
                                            <Text style={[s.cancelBtnText, { color: colors.purple, fontSize: moderateScale(11) }]}>✏️ Düzenle</Text>
                                        </TouchableOpacity>
                                    </View>
                                )}
                                {/* Kullanıcı isteği: Sipariş Ver, İptal Et'in solunda — aynı satırda —
                                    böylece ilan sahibi detaydan çıkmadan da tesis menüsünden sipariş
                                    verebilir (bkz. VenueMenuOrderModal, RivalCard'daki ile aynı akış). */}
                                <View style={{ flexDirection: 'row', gap: 3 }}>
                                    {item.venueId && (
                                        <TouchableOpacity
                                            style={[s.cancelBtn, { flex: 1, backgroundColor:'#22c55e20', borderColor:'#22c55e50', borderRadius: moderateScale(8), paddingVertical: moderateScale(5) }]}
                                            onPress={() => setOrderVenueId(item.venueId)}
                                        >
                                            <Text style={[s.cancelBtnText, { color:'#22c55e', fontSize: moderateScale(11) }]} numberOfLines={1} adjustsFontSizeToFit minimumFontScale={0.75}>📋 Sipariş Ver</Text>
                                        </TouchableOpacity>
                                    )}
                                    <TouchableOpacity style={[s.cancelBtn, { flex: 1, borderRadius: moderateScale(8), paddingVertical: moderateScale(5) }]} onPress={() => { onClose(); setTimeout(handleCancel, 300); }}>
                                        <Text style={[s.cancelBtnText, { fontSize: moderateScale(11) }]}>{t.cancelAdBtn}</Text>
                                    </TouchableOpacity>
                                </View>
                                {/* Kullanıcı isteği: Demo Botları Başlat artık Paylaş/Düzenle/İptal
                                    satırının ALTINDA — demo botları ilerleyen zamanlarda tamamen
                                    kaldırılacak, şimdilik burada kalıyor. */}
                                {!isRefereeAd && !isFull && sub === 'volleyball' && (
                                    <TouchableOpacity
                                        style={[s.joinBtn, { backgroundColor: demoSpamActive ? '#ef444420' : '#7c3aed20', borderWidth:1, borderColor: demoSpamActive ? '#ef444450' : '#7c3aed50', marginTop:6, borderRadius: moderateScale(8), paddingVertical: moderateScale(6) }]}
                                        onPress={() => {
                                            if (demoSpamRunningRef.current) {
                                                demoSpamRunningRef.current = false;
                                                if (demoSpamIntervalRef.current) { clearTimeout(demoSpamIntervalRef.current); demoSpamIntervalRef.current = null; }
                                                setDemoSpamActive(false);
                                                return;
                                            }
                                            demoSpamRunningRef.current = true;
                                            setDemoSpamActive(true);
                                            const sendOne = () => {
                                                api.post('/demo/volleyball-join', { rivalId: item.id }).catch(() => {}).finally(() => {
                                                    if (demoSpamRunningRef.current) demoSpamIntervalRef.current = setTimeout(sendOne, 2000);
                                                });
                                            };
                                            sendOne();
                                        }}
                                    >
                                        <Text style={[s.joinBtnText, { color: demoSpamActive ? '#f87171' : '#a78bfa', fontSize: moderateScale(12) }]}>{demoSpamActive ? '⏹ Demo Botları Durdur' : '🤖 Demo Botları Başlat (2sn/istek)'}</Text>
                                    </TouchableOpacity>
                                )}
                            </>
                        ) : isLinkedMatchPlayer ? (
                            <View style={[s.waitingBox, { borderRadius: moderateScale(8), paddingVertical: moderateScale(5) }]}>
                                <Text style={[s.waitingText, { fontSize: moderateScale(12) }]}>Bu maça oyuncu olarak katıldığınız için hakemlik başvurusu yapamazsınız.</Text>
                            </View>
                        ) : myInvite ? (
                            <View style={{ gap:3 }}>
                                {myInvite.isPartnerInvite && (
                                    <Text style={{ color:'#a78bfa', fontSize: moderateScale(11), fontWeight:'700', textAlign:'center' }}>🤝 Partner Daveti</Text>
                                )}
                                {(myInvite.offerPrice || myInvite.offerMessage) && (
                                    <View style={{ backgroundColor:'#f59e0b0d', borderRadius: moderateScale(8), borderWidth:1, borderColor:'#f59e0b30', paddingHorizontal:8, paddingVertical:6 }}>
                                        {myInvite.offerPrice && <Text style={{ color:'#f59e0b', fontSize: moderateScale(12), fontWeight:'800' }}>💰 {myInvite.offerPrice}</Text>}
                                        {myInvite.offerMessage && <Text style={{ color: colors.textSecondary, fontSize: moderateScale(11), marginTop:2 }}>{myInvite.offerMessage}</Text>}
                                    </View>
                                )}
                                <View style={{ flexDirection:'row', gap:3 }}>
                                    {/* acceptLocal/rejectLocal (bkz. yukarısı) — handleRespondJoin (üst bileşenden
                                        gelen prop) sadece onRefresh() ile tüm listeyi yeniden çekiyordu, bu da
                                        "kabul ettim ama buton hâlâ duruyor, ekrandan çıkıp girmem gerekti" hissine
                                        yol açıyordu. acceptLocal/rejectLocal API'nin döndürdüğü güncel veriyle
                                        (participants/senderTeam/joinRequests) anında local state'i güncelliyor. */}
                                    <TouchableOpacity style={[s.joinBtn, { flex:1, backgroundColor:'#16a34a', borderRadius: moderateScale(8), paddingVertical: moderateScale(6) }]} onPress={() => acceptLocal(myInvite.id)}>
                                        <Text style={[s.joinBtnText, { fontSize: moderateScale(12) }]}>{myInvite.isPartnerInvite ? 'Partner Ol' : t.inviteAcceptBtn}</Text>
                                    </TouchableOpacity>
                                    <TouchableOpacity style={[s.cancelBtn, { flex:1, borderRadius: moderateScale(8), paddingVertical: moderateScale(5) }]} onPress={() => rejectLocal(myInvite.id)}>
                                        <Text style={[s.cancelBtnText, { fontSize: moderateScale(11) }]}>{t.inviteRejectBtn}</Text>
                                    </TouchableOpacity>
                                </View>
                            </View>
                        ) : mySentReq === 'AWAITING_JOINER_CONFIRM' ? (
                            <View style={{ gap:6 }}>
                                <View style={[s.waitingBox, { backgroundColor:'#f59e0b20', borderColor:'#f59e0b50', borderRadius: moderateScale(8), paddingVertical: moderateScale(5) }]}>
                                    <Text style={[s.waitingText, { color:'#f59e0b', fontSize: moderateScale(12) }]}>⏰ {t.awaitingYourConfirm}</Text>
                                </View>
                                <View style={{ flexDirection:'row', gap:6 }}>
                                    <TouchableOpacity style={{ flex:1, backgroundColor:'#16a34a', borderRadius: moderateScale(8), paddingVertical: moderateScale(6), alignItems:'center' }} onPress={() => onConfirmLateJoin?.('confirm')}>
                                        <Text style={{ color:'#fff', fontSize: moderateScale(12), fontWeight:'700' }}>{t.confirmJoinBtn}</Text>
                                    </TouchableOpacity>
                                    <TouchableOpacity style={[s.cancelBtn, { flex:1, borderRadius: moderateScale(8), paddingVertical: moderateScale(6) }]} onPress={() => onConfirmLateJoin?.('cancel')}>
                                        <Text style={[s.cancelBtnText, { fontSize: moderateScale(12) }]}>{t.cancelJoinBtn}</Text>
                                    </TouchableOpacity>
                                </View>
                            </View>
                        ) : mySentReq === 'PENDING' ? (
                            <View style={{ gap:3 }}>
                                <View style={[s.waitingBox, { borderRadius: moderateScale(8), paddingVertical: moderateScale(5) }]}><Text style={[s.waitingText, { fontSize: moderateScale(12) }]}>{t.waitingReq}</Text></View>
                                <TouchableOpacity style={[s.cancelBtn, { borderRadius: moderateScale(8), paddingVertical: moderateScale(5) }]} onPress={handleWithdraw}>
                                    <Text style={[s.cancelBtnText, { fontSize: moderateScale(11) }]}>{t.withdrawReqBtn}</Text>
                                </TouchableOpacity>
                            </View>
                        ) : mySentReq === 'COUNTERED' ? (
                            <View style={{ gap:6 }}>
                                <View style={[s.waitingBox, { backgroundColor:'#f59e0b20', borderColor:'#f59e0b50', borderRadius: moderateScale(8), paddingVertical: moderateScale(5) }]}>
                                    <Text style={[s.waitingText, { color:'#f59e0b', fontSize: moderateScale(12) }]}>↔️ {t.refereeCounterReceivedMsg(item._myJoinCounterPrice)}</Text>
                                    {item._myJoinCounterMessage && (
                                        <Text style={{ color:'#f59e0b', fontSize: moderateScale(11), fontStyle:'italic', marginTop:3 }}>{item._myJoinCounterMessage}</Text>
                                    )}
                                </View>
                                <View style={{ flexDirection:'row', gap:6 }}>
                                    <TouchableOpacity style={{ flex:1, backgroundColor:'#16a34a', borderRadius: moderateScale(8), paddingVertical: moderateScale(6), alignItems:'center' }} onPress={() => { api.patch(`/rivals/join/${item._myJoinRequestId}`, { action: 'accept_counter' }).then(onRefresh).catch(e => Alert.alert(t.error, e?.response?.data?.message || t.actionFailed)); }}>
                                        <Text style={{ color:'#fff', fontSize: moderateScale(12), fontWeight:'700' }}>{t.inviteAcceptBtn}</Text>
                                    </TouchableOpacity>
                                    <TouchableOpacity style={[s.cancelBtn, { flex:1, borderRadius: moderateScale(8), paddingVertical: moderateScale(6) }]} onPress={() => { api.patch(`/rivals/join/${item._myJoinRequestId}`, { action: 'reject_counter' }).then(onRefresh).catch(e => Alert.alert(t.error, e?.response?.data?.message || t.actionFailed)); }}>
                                        <Text style={[s.cancelBtnText, { fontSize: moderateScale(12) }]}>{t.inviteRejectBtn}</Text>
                                    </TouchableOpacity>
                                </View>
                            </View>
                        ) : mySentReq === 'ACCEPTED' ? (
                            // Kullanıcı isteği: "Kabul edildiniz" rozeti kaldırıldı, Maçtan Ayrıl
                            // butonu artık yukarıda Oyuncu Davet Et/Paylaş ile aynı satırda
                            // (bkz. canLeaveHere) — burada tekrar göstermeye gerek yok.
                            null
                        ) : isFull ? (
                            <View style={{ gap:6 }}>
                                <View style={[s.waitingBox, { borderRadius: moderateScale(8), paddingVertical: moderateScale(5) }]}><Text style={[s.waitingText, { fontSize: moderateScale(12) }]}>{t.ilanFull || 'İlan doldu'}</Text></View>
                                {item.refereeRequested && !item.refereeUser && (
                                    <TouchableOpacity style={{ backgroundColor:'#f59e0b20', borderRadius: moderateScale(8), paddingVertical: moderateScale(6), alignItems:'center', borderWidth:1, borderColor:'#f59e0b70' }} onPress={() => setRefereeApplyVisible(true)}>
                                        <Text style={{ color:'#f59e0b', fontSize: moderateScale(12), fontWeight:'800' }}>{t.refereeApplyBtn}</Text>
                                    </TouchableOpacity>
                                )}
                            </View>
                        ) : Array.isArray(item.positions) && item.positions.includes('REFEREE') ? (
                            <TouchableOpacity style={{ backgroundColor:'#f59e0b20', borderRadius: moderateScale(8), paddingVertical: moderateScale(6), alignItems:'center', borderWidth:1, borderColor:'#f59e0b70' }} onPress={() => setRefereeApplyVisible(true)}>
                                <Text style={{ color:'#f59e0b', fontSize: moderateScale(12), fontWeight:'800' }}>{t.refereeApplyBtn}</Text>
                            </TouchableOpacity>
                        ) : item.matchType === 'DOUBLE' && item.teamFlexibility === 'STRICT' ? (() => {
                            const senderTeamArrStrict = Array.isArray(item.senderTeam) ? item.senderTeam : [];
                            const partnerStrict = senderTeamArrStrict[0] || null;
                            const opp1Strict = participants[0] || null;
                            const opp2Strict = participants[1] || null;
                            const gParenStrict = (g) => g === 'MALE' ? ' (Erkek)' : g === 'FEMALE' ? ' (Kadın)' : '';
                            const SlotPick = ({ slotKey, p, gReq, label }) => (
                                <TouchableOpacity
                                    disabled={!!p?.id}
                                    onPress={() => { onClose(); setTimeout(() => handleJoin(slotKey), 300); }}
                                    activeOpacity={p?.id ? 1 : 0.7}
                                    style={{ flex:1, backgroundColor: p?.id ? colors.surface2 : cfg.color+'12', borderRadius: moderateScale(8), padding: moderateScale(6), borderWidth:1, borderColor: p?.id ? colors.border : cfg.color+'60', borderStyle: p?.id ? 'solid' : 'dashed', alignItems:'center', minHeight: moderateScale(44), justifyContent:'center' }}>
                                    <Text style={{ color: colors.textMuted, fontSize: moderateScale(9), fontWeight:'700' }} numberOfLines={1}>{label}{gReq && gReq !== 'MIX' ? gParenStrict(gReq) : ''}</Text>
                                    {p?.id ? (
                                        <Text style={{ color:'#fff', fontSize: moderateScale(11), fontWeight:'700', marginTop:2 }} numberOfLines={1} adjustsFontSizeToFit minimumFontScale={0.75}>{playerDisplayName(p)}</Text>
                                    ) : (
                                        <Text style={{ color: cfg.color, fontSize: moderateScale(11), fontWeight:'800', marginTop:2 }}>+ {t.joinBtn}</Text>
                                    )}
                                </TouchableOpacity>
                            );
                            return (
                                <View style={{ gap:6 }}>
                                    <SlotPick slotKey="partner" p={partnerStrict} gReq={partnerGenderReq} label={t.founderTeamLabel} />
                                    <View style={{ flexDirection:'row', gap:6 }}>
                                        <SlotPick slotKey="opp1" p={opp1Strict} gReq={opp1GenderReq} label={t.opp1Label} />
                                        <SlotPick slotKey="opp2" p={opp2Strict} gReq={opp2GenderReq} label={t.opp2Label} />
                                    </View>
                                </View>
                            );
                        })() : (
                            <View style={{ flexDirection:'row', gap:6 }}>
                                <TouchableOpacity style={[s.joinBtn, { flex:1, backgroundColor: cfg.color, borderRadius: moderateScale(8), paddingVertical: moderateScale(6) }]} onPress={() => { onClose(); setTimeout(handleJoin, 300); }}>
                                    <Text style={[s.joinBtnText, { fontSize: moderateScale(12) }]}>{t.joinBtn}</Text>
                                </TouchableOpacity>
                                {item.refereeRequested && !item.refereeUser && (
                                    <TouchableOpacity style={{ flex:1, backgroundColor:'#f59e0b20', borderRadius: moderateScale(8), paddingVertical: moderateScale(6), alignItems:'center', justifyContent:'center', borderWidth:1, borderColor:'#f59e0b70' }} onPress={() => setRefereeApplyVisible(true)}>
                                        <Text style={{ color:'#f59e0b', fontSize: moderateScale(12), fontWeight:'800' }} numberOfLines={1} adjustsFontSizeToFit minimumFontScale={0.75}>{t.refereeApplyBtn}</Text>
                                    </TouchableOpacity>
                                )}
                            </View>
                        )}
                    </View>

                    {/* Kullanıcı isteği: bu sporda onaylı hakemliği olan biri, ilan sahibi hakem
                        istemese bile ilan detayından hakem olarak başvurabilsin. Yukarıdaki uzun
                        ternary zincirinde (isOwner/isFull/mySentReq PENDING-COUNTERED-ACCEPTED/
                        takım sporu roster'ı vb.) HER dala ayrı ayrı eklemek yerine, tüm dallardan
                        bağımsız TEK bir yerde gösteriliyor — böylece hangi dal aktif olursa olsun
                        (ör. voleybolde teamSize>1 roster akışı) kaybolmuyor. isOwner ve zaten
                        hakemi atanmış/kendi başvurusu olan durumlar hariç tutulur. */}
                    {!isOwner && !item.refereeUser && myRefereeListing?.approved &&
                     !refereeApplications.some(app => app.userId === myId) && (
                        <TouchableOpacity style={{ backgroundColor:'#f59e0b20', borderRadius: moderateScale(8), paddingVertical: moderateScale(6), alignItems:'center', borderWidth:1, borderColor:'#f59e0b70', marginBottom:14 }} onPress={() => setRefereeApplyVisible(true)}>
                            <Text style={{ color:'#f59e0b', fontSize: moderateScale(12), fontWeight:'800' }}>{t.refereeApplyBtn}</Text>
                        </TouchableOpacity>
                    )}

                    {/* Açıklama + Ödül — kullanıcı isteği: buraya, Yorumlar'ın hemen üstüne taşındı
                        (önceden üst bilgi satırının hemen altında, header'a yakın gösteriliyordu). */}
                    {item.message && <Text style={[s.cardMsg, { marginBottom:12, fontSize: moderateScale(13) }]}>{item.message}</Text>}
                    {item.wager && (
                        <View style={{ flexDirection:'row', alignItems:'center', gap:5, backgroundColor:'#f59e0b20', borderWidth:1, borderColor:'#f59e0b50', borderRadius:10, paddingHorizontal:8, paddingVertical:6, marginBottom:12 }}>
                            <Text style={{ fontSize:14 }}>🏆</Text>
                            <Text style={{ color:'#fbbf24', fontSize: moderateScale(12), fontWeight:'700', flex:1 }}>{item.wager}</Text>
                        </View>
                    )}

                    {/* Seyirci Listesi — sadece voleybolda: onaylı antrenörler ancak seyirci olarak
                        katıldıkları maçlardaki oyuncuları değerlendirebilir (bkz. resolveRaterRole). */}
                    {item.subCategory === 'volleyball' && (
                        <View style={det.section}>
                            <View style={{ flexDirection:'row', alignItems:'center', justifyContent:'space-between', marginBottom: spectators.length > 0 ? moderateScale(10) : 0 }}>
                                <Text style={det.sectionTitle}>👁 {t.spectatorListTitle}{spectators.length > 0 ? ` (${spectators.length})` : ''}</Text>
                                {/* Kullanıcı isteği: ilan sahibi, maçta oyuncu olarak yer alanlar VE atanmış
                                    hakem zaten kadroda/maçta görevli — onlara "seyirci olarak katıl" butonu
                                    saçma olur, sadece bunların dışındakilere gösterilir. */}
                                {!isMatchRosterMember && item.refereeUser?.id !== myId && (
                                    <TouchableOpacity
                                        disabled={spectatorActionLoading}
                                        onPress={toggleSpectator}
                                        style={{ backgroundColor: amISpectator ? colors.border : cfg.color, borderRadius:moderateScale(8), paddingHorizontal:moderateScale(10), paddingVertical:moderateScale(6), opacity: spectatorActionLoading ? 0.6 : 1 }}
                                    >
                                        <Text style={{ color: amISpectator ? colors.textMuted : '#fff', fontSize:moderateScale(11), fontWeight:'800' }}>
                                            {amISpectator ? t.spectatorLeaveBtn : t.spectatorJoinBtn}
                                        </Text>
                                    </TouchableOpacity>
                                )}
                            </View>
                            {spectators.length === 0 ? (
                                <Text style={det.emptyTxt}>{t.spectatorListEmpty}</Text>
                            ) : (
                                spectators.map(sp => (
                                    <View key={sp.id} style={[det.playerRow, { justifyContent:'space-between' }]}>
                                        {/* Kullanıcı isteği: antrenörse ad soyad, değilse voleybol dalındaki
                                            takma adı (alias) — yoksa kullanıcı adına düşer. */}
                                        <Text style={det.playerName}>{sp.isCoach ? (sp.user?.fullName || sp.user?.username) : (sp.alias || sp.user?.username)}</Text>
                                        {isMatchRosterMember && sp.user?.id !== myId && (
                                            <TouchableOpacity
                                                disabled={disputingSpectatorId === sp.user?.id}
                                                onPress={() => disputeSpectatorUser(sp.user.id)}
                                                style={{ opacity: disputingSpectatorId === sp.user?.id ? 0.5 : 1 }}
                                            >
                                                <Text style={{ color:'#f87171', fontSize:moderateScale(11), fontWeight:'700' }}>🚩 {t.spectatorDisputeBtn}</Text>
                                            </TouchableOpacity>
                                        )}
                                    </View>
                                ))
                            )}
                        </View>
                    )}

                    {/* Yorum yaz — kullanıcı isteği: eskiden ekranın en altına, klavyenin hemen
                        üstüne SABİT olarak yapıştırılmıştı; kadro kartındaki forma arama kutusuna
                        yazarken de alakasızca orada duruyordu. Artık normal kaydırılan akışın
                        içinde, doğrudan "Yorumlar" başlığının ÜSTÜNDE — sadece kullanıcı buraya
                        kadar kaydırınca görünür. */}
                    {item.refereeUser?.id !== myId && (
                        <View style={{ flexDirection:'row', gap:3, marginBottom:14 }}>
                            <TextInput
                                style={[s.fieldInput, { flex:1, height:moderateScale(44), marginBottom:0, fontSize:moderateScale(14) }]}
                                placeholder={t.matchCommentPlaceholder}
                                placeholderTextColor={colors.textMuted}
                                value={commentText}
                                onChangeText={setCommentText}
                                multiline={false}
                                returnKeyType="send"
                                onSubmitEditing={sendComment}
                            />
                            <TouchableOpacity
                                style={[s.joinBtn, { paddingHorizontal:15, height:moderateScale(44), justifyContent:'center', alignSelf:'center', borderRadius: moderateScale(10) }, sendingComment && { opacity:0.6 }]}
                                onPress={sendComment}
                                disabled={sendingComment}
                            >
                                <Text style={[s.joinBtnText, { fontSize: moderateScale(13) }]}>{t.matchCommentSend}</Text>
                            </TouchableOpacity>
                        </View>
                    )}

                    {/* Yorumlar bölümü */}
                    <Text style={{ color:'#fff', fontSize:moderateScale(15), fontWeight:'800', marginBottom:14 }}>
                        💬 {t.matchCommentsTitle}{comments.length > 0 ? ` (${comments.length})` : ''}
                    </Text>
                    {loadingComments ? (
                        <ActivityIndicator color={cfg.color} style={{ marginTop:16 }} />
                    ) : comments.length === 0 ? (
                        <Text style={{ color: colors.textMuted, textAlign:'center', marginTop:8, fontSize:moderateScale(13) }}>{t.matchCommentEmpty}</Text>
                    ) : (
                        comments.map(c => (
                            <View key={c.id} style={{ marginBottom:14, paddingBottom:11, borderBottomWidth:1, borderBottomColor: colors.border }}>
                                <View style={{ flexDirection:'row', justifyContent:'space-between', alignItems:'flex-start' }}>
                                    <View style={{ flex:1 }}>
                                        <Text style={{ color: cfg.color, fontSize:moderateScale(13), fontWeight:'700', marginBottom:3 }}>{c.user?.username}</Text>
                                        <Text style={{ color:'#fff', fontSize:moderateScale(14), lineHeight:moderateScale(21) }}>{c.content}</Text>
                                        <Text style={{ color: colors.textMuted, fontSize:moderateScale(11), marginTop:4 }}>
                                            {new Date(c.createdAt).toLocaleString(t.dateLocale, { day:'numeric', month:'short', hour:'2-digit', minute:'2-digit' })}
                                        </Text>
                                    </View>
                                    {canDeleteComment(c) && (
                                        <TouchableOpacity onPress={() => deleteComment(c.id)} style={{ padding:5, marginLeft:8 }}>
                                            <Text style={{ color:'#f87171', fontSize:moderateScale(14) }}>✕</Text>
                                        </TouchableOpacity>
                                    )}
                                </View>
                            </View>
                        ))
                    )}
                </ScrollView>

                {/* Oyuncu Davet Et — arama paneli. Ayrı bir <Modal> DEĞİL: bu View zaten
                    dış Modal'ın (yukarıdaki, visible={visible}) içinde — Android'de iç içe
                    Modal, klavye açılınca pencerenin çökmesine yol açıyordu (kullanıcı
                    raporu: "klavye formu kapatıyor ne yazdığımı göremiyorum"). Bunun yerine
                    aynı Modal'ın içinde mutlak konumlu tam ekran katman olarak render
                    ediliyor (bkz. showPartnerSearch / ekran-guvenli-alan.md). */}
                {inviteModalVisible && (
                    <View style={{ position:'absolute', top:0, left:0, right:0, bottom:0 }}>
                        <KeyboardAvoidingView behavior="padding" style={{ flex:1, justifyContent:'flex-end' }}>
                            <TouchableOpacity style={{ flex:1, backgroundColor:'#00000080', justifyContent:'flex-end' }} activeOpacity={1}
                                onPress={() => { setInviteModalVisible(false); setInviteQuery(''); setInviteResults([]); setInviteForReferee(false); }}>
                                <View onStartShouldSetResponder={() => true}
                                    style={{ backgroundColor: colors.surface, borderTopLeftRadius:24, borderTopRightRadius:24, paddingHorizontal:17, paddingTop:17, paddingBottom:37, maxHeight:'80%' }}>
                                    <View style={{ flexDirection:'row', alignItems:'center', marginBottom:14 }}>
                                        <Text style={{ color:'#fff', fontSize:moderateScale(16), fontWeight:'800', flex:1 }}>{inviteForReferee ? noEmojiStr(t.inviteRefereeBtn) : t.inviteBtn}</Text>
                                        <TouchableOpacity onPress={() => { setInviteModalVisible(false); setInviteQuery(''); setInviteResults([]); setInviteForReferee(false); }}>
                                            <Text style={{ color: colors.textMuted, fontSize:moderateScale(20) }}>✕</Text>
                                        </TouchableOpacity>
                                    </View>
                                    <TextInput
                                        style={[s.fieldInput, { fontSize: moderateScale(14), borderRadius: moderateScale(12), paddingHorizontal: moderateScale(14), paddingVertical: moderateScale(12) }]}
                                        value={inviteQuery}
                                        onChangeText={setInviteQuery}
                                        placeholder={t.inviteSearchPh}
                                        placeholderTextColor={colors.textMuted}
                                        autoFocus
                                    />
                                    {inviteSearching && <ActivityIndicator color={cfg.color} style={{ marginTop:12 }} />}
                                    <ScrollView style={{ marginTop:8 }} keyboardShouldPersistTaps="always">
                                        {inviteResults.map(u => (
                                            <View key={u.id} style={{ flexDirection:'row', alignItems:'center', gap:3, paddingVertical:7, borderBottomWidth:1, borderBottomColor: colors.border+'40' }}>
                                                <Avatar name={u.username} avatar={u.avatar} size={moderateScale(36)} color={cfg.color} />
                                                <View style={{ flex:1 }}>
                                                    <Text style={{ color:'#fff', fontWeight:'700', fontSize:moderateScale(13) }}>{u.interests?.[0]?.alias || u.fullName || u.username}</Text>
                                                    <Text style={{ color: colors.textMuted, fontSize:moderateScale(11) }}>
                                                        {inviteForReferee
                                                            ? `${u.username}${u.refereeListings?.[0]?.credentialLevel ? `  · ${u.refereeListings[0].credentialLevel}` : ''}${u.refereeListings?.[0]?.pricePerMatch ? `  ${u.refereeListings[0].pricePerMatch}₺` : ''}`
                                                            : `${u.username}${u.interests?.[0]?.skillRating != null ? `  ${Number(u.interests[0].skillRating).toFixed(2)} ★` : ''}`}
                                                    </Text>
                                                </View>
                                                {invitedUserIds.has(u.id) ? (
                                                    <Text style={{ color:'#4ade80', fontSize:moderateScale(12), fontWeight:'700' }}>✓ Davet Gönderildi</Text>
                                                ) : (
                                                    <TouchableOpacity
                                                        style={[s.joinBtn, { paddingHorizontal:moderateScale(14), paddingVertical:moderateScale(7), borderRadius: moderateScale(10) }, invitingUserId === u.id && { opacity:0.6 }]}
                                                        onPress={() => handleInvite(u)}
                                                        disabled={invitingUserId === u.id}
                                                    >
                                                        <Text style={[s.joinBtnText, { fontSize: moderateScale(13) }]}>{invitingUserId === u.id ? '...' : t.inviteSendBtn}</Text>
                                                    </TouchableOpacity>
                                                )}
                                            </View>
                                        ))}
                                        {!inviteSearching && inviteQuery.trim().length >= 2 && inviteResults.length === 0 && (
                                            <Text style={{ color: colors.textMuted, textAlign:'center', marginTop:16, fontSize:moderateScale(13) }}>{t.inviteNoResults}</Text>
                                        )}
                                    </ScrollView>
                                </View>
                            </TouchableOpacity>
                        </KeyboardAvoidingView>
                    </View>
                )}
            </View>
        </Modal>

        {/* Hakemlik İçin Başvur — fiyat teklifi / mesaj / CV */}
        <Modal visible={refereeApplyVisible} animationType="slide" transparent onRequestClose={() => setRefereeApplyVisible(false)} android_keyboardInputMode="adjustNothing">
            <View style={{ flex:1, backgroundColor:'#00000080', justifyContent:'flex-end' }}>
                <KeyboardAvoidingView behavior="padding">
                    <View style={{ backgroundColor: colors.surface, borderTopLeftRadius:24, borderTopRightRadius:24, paddingHorizontal:17, paddingTop:17, paddingBottom:37 }}>
                        <View style={{ flexDirection:'row', alignItems:'center', marginBottom:14 }}>
                            <Text style={{ color:'#fff', fontSize:moderateScale(16), fontWeight:'800', flex:1 }}>{t.refereeApplyBtn}</Text>
                            <TouchableOpacity onPress={() => setRefereeApplyVisible(false)}><Text style={{ color: colors.textMuted, fontSize:moderateScale(20) }}>✕</Text></TouchableOpacity>
                        </View>
                        <Text style={s.fieldLabel}>{t.refereePaymentLabel}</Text>
                        <TextInput style={s.fieldInput} value={refereeOfferPrice} onChangeText={v => setRefereeOfferPrice(v.replace(/[^0-9]/g, ''))}
                            placeholder="500" placeholderTextColor={colors.textMuted} keyboardType="numeric" />
                        <Text style={s.fieldLabel}>{t.messageFieldLabel}</Text>
                        <TextInput style={[s.fieldInput, { height:70, textAlignVertical:'top' }]}
                            value={refereeOfferMessage} onChangeText={setRefereeOfferMessage}
                            placeholder={t.refereeApplyMsgPh} placeholderTextColor={colors.textMuted} multiline />
                        {myRefereeListing?.cvUrl && (
                            <TouchableOpacity onPress={() => setRefereeSendCv(v => !v)} style={{ flexDirection:'row', alignItems:'center', gap:6, marginTop:4, marginBottom:10 }}>
                                <View style={{ width:20, height:20, borderRadius:5, borderWidth:2, borderColor: refereeSendCv ? '#f59e0b' : colors.border, backgroundColor: refereeSendCv ? '#f59e0b' : 'transparent', alignItems:'center', justifyContent:'center' }}>
                                    {refereeSendCv && <Text style={{ color:'#fff', fontSize:12, fontWeight:'900' }}>✓</Text>}
                                </View>
                                <Text style={{ color: colors.textSecondary, fontSize:moderateScale(12) }}>{t.refereeSendCvLabel}</Text>
                            </TouchableOpacity>
                        )}
                        <TouchableOpacity style={[s.submitBtn, { backgroundColor:'#f59e0b' }, refereeApplySubmitting && { opacity:0.6 }]}
                            onPress={submitRefereeApply} disabled={refereeApplySubmitting}>
                            <Text style={s.submitBtnText}>{refereeApplySubmitting ? t.submittingBtn : t.refereeApplySendBtn}</Text>
                        </TouchableOpacity>
                    </View>
                </KeyboardAvoidingView>
            </View>
        </Modal>

        {/* Kurucu/Rakip Takım ismi düzenle */}
        <Modal visible={!!teamNameEdit} animationType="fade" transparent onRequestClose={() => setTeamNameEdit(null)}>
            <View style={{ flex:1, backgroundColor:'#00000090', justifyContent:'center', paddingHorizontal:30 }}>
                <View style={{ backgroundColor: colors.surface, borderRadius:16, padding:16 }}>
                    <Text style={{ color:'#fff', fontSize:14, fontWeight:'900', marginBottom:10 }}>
                        {teamNameEdit?.side === 'founder' ? 'Kurucu Takım İsmi' : 'Rakip Takım İsmi'}
                    </Text>
                    <TextInput
                        value={teamNameEdit?.value || ''}
                        onChangeText={(v) => setTeamNameEdit(p => ({ ...p, value: v }))}
                        placeholder="Ör: Şimşekler"
                        placeholderTextColor={colors.textMuted}
                        maxLength={24}
                        style={{ backgroundColor:'#1e293b', borderRadius:10, borderWidth:1, borderColor:colors.border, color:'#fff', fontSize:14, paddingHorizontal:12, paddingVertical:9, marginBottom:12 }}
                    />
                    <View style={{ flexDirection:'row', gap:8 }}>
                        <TouchableOpacity onPress={() => setTeamNameEdit(null)} style={{ flex:1, alignItems:'center', paddingVertical:11, borderRadius:10, backgroundColor:'#ffffff10' }}>
                            <Text style={{ color: colors.textMuted, fontWeight:'700' }}>Vazgeç</Text>
                        </TouchableOpacity>
                        <TouchableOpacity onPress={saveTeamNameEdit} disabled={savingTeamNameEdit} style={{ flex:1, alignItems:'center', paddingVertical:11, borderRadius:10, backgroundColor: colors.purple, opacity: savingTeamNameEdit ? 0.6 : 1 }}>
                            <Text style={{ color:'#fff', fontWeight:'800' }}>{savingTeamNameEdit ? '...' : 'Kaydet'}</Text>
                        </TouchableOpacity>
                    </View>
                </View>
            </View>
        </Modal>

        {/* Kadro kartında "Değiştir/Çıkar" — bkz. promptSlotAction/SlotActionSheet */}
        <SlotActionSheet {...slotActionSheetProps} onClose={() => setSlotActionTarget(null)} />

        {/* Çiftler: partner davet picker — bireysel başvuranlar arasından seç */}
        <Modal visible={showJoinInvitePicker} animationType="fade" transparent onRequestClose={() => setShowJoinInvitePicker(false)}>
            <View style={{ flex:1, backgroundColor:'#00000080', justifyContent:'center', alignItems:'center', padding:21 }}>
                <View style={{ backgroundColor:'#1e293b', borderRadius:16, padding:17, borderWidth:1, borderColor: cfg.color+'40', width:'100%', maxHeight:'70%' }}>
                    <Text style={{ color:'#fff', fontSize:15, fontWeight:'800', marginBottom:12 }}>👥 Partner Davet Et</Text>
                    <ScrollView>
                        {joinInviteCandidates.length === 0 ? (
                            <Text style={{ color: colors.textMuted, fontSize:13, textAlign:'center', paddingVertical:3 }}>Davet edilebilecek bireysel başvuran yok</Text>
                        ) : joinInviteCandidates.map(c => (
                            <TouchableOpacity key={c.userId} onPress={() => setMyRivalJoinPartner(c.userId)} disabled={partnerActionLoading} style={{ flexDirection:'row', alignItems:'center', gap:3, paddingVertical:7, borderBottomWidth:1, borderBottomColor: colors.border+'40' }}>
                                <Avatar name={c.user?.username} avatar={c.user?.avatar} size={moderateScale(34)} color={cfg.color} />
                                <View style={{ flex:1 }}>
                                    <Text style={{ color:'#fff', fontSize:13, fontWeight:'700' }}>{c.user?.fullName || c.user?.username}</Text>
                                    <Text style={{ color: colors.textMuted, fontSize:11 }}>{c.user?.username}{c.user?.interests?.find(i => i.subCategory === sub)?.skillRating != null ? `  ${starEmoji(Number(c.user.interests.find(i => i.subCategory === sub).skillRating))} ${Number(c.user.interests.find(i => i.subCategory === sub).skillRating).toFixed(2)}` : ''}</Text>
                                </View>
                            </TouchableOpacity>
                        ))}
                    </ScrollView>
                    <TouchableOpacity onPress={() => setShowJoinInvitePicker(false)} style={{ marginTop:14, backgroundColor:'#334155', borderRadius:10, paddingVertical:8, alignItems:'center' }}>
                        <Text style={{ color:'#94a3b8', fontSize:13, fontWeight:'700' }}>Vazgeç</Text>
                    </TouchableOpacity>
                </View>
            </View>
        </Modal>

        <VenueMenuOrderModal
            visible={!!orderVenueId}
            venueId={orderVenueId}
            rivalId={item.id}
            onClose={() => setOrderVenueId(null)}
            onSuccess={() => {
                api.get(`/rivals/${item.id}`)
                    .then(({ data }) => setLocalOrderedUserIds(Array.isArray(data.orderedUserIds) ? data.orderedUserIds : []))
                    .catch(() => {});
            }}
        />
        <MyOrderStatusModal visible={showMyOrder} rivalId={item.id} onClose={() => setShowMyOrder(false)} />
        </>
    );
}

// ─── Rival Card ────────────────────────────────────────────────────────────────

function RivalCard({ item, myId, sub, onRefresh, navigation, autoOpen, onAutoOpened, myRating = 0, refereeListings = [], highlightSlot = null, autoOpenOrder = false }) {
    const t = useT();
    const cfg = getConfig(sub);
    const isVolleyball = sub === 'volleyball';
    const isOwner = item.senderId === myId;
    // Hakem Arıyorum ilanları (matchType PLAYER_WANTED, positions:['REFEREE']) — ilan
    // sahibi (asıl maçın kurucusuyla aynı kişi) olsa bile bu kart üzerinde asıl maça ait
    // Düzenle/İptal gibi aksiyonlar gösterilmez, sadece hakemlikle ilgili durum gösterilir.
    const isRefereeAd = item.matchType === 'PLAYER_WANTED' && Array.isArray(item.positions) && item.positions.includes('REFEREE');
    // Hakem Arıyorum ilanları (linkedRival dolu) için: asıl maça oyuncu olarak
    // katılmış biri (kurucu/partner/rakip) kendi maçına hakemlik başvurusu yapamaz.
    const isLinkedMatchPlayer = !!item.linkedRival && (
        item.linkedRival.senderId === myId
        || (Array.isArray(item.linkedRival.participants) && item.linkedRival.participants.some(p => p?.id === myId))
        || (Array.isArray(item.linkedRival.senderTeam) && item.linkedRival.senderTeam.some(p => p?.id === myId))
    );
    const participants = Array.isArray(item.participants) ? item.participants : [];
    const senderTeamArr = Array.isArray(item.senderTeam) ? item.senderTeam : [];
    // Kullanıcı isteği: tüm ilan kartları (Açık İlanlar/Bekleyen/Skor Bekleyen Maçlar) artık
    // önlü-arkalı bir "digimon kart" — sağ üst köşedeki 🔄 ile çevrilince arka yüzde katılan
    // oyuncular + elo puanları listeleniyor, ön yüz hiç değişmedi. Diğer digimon kartlarla
    // (DoubleRosterCard vb.) AYNI iki aşamalı çevirme deseni: 0→90'da içerik henüz eskisi,
    // kart tam yan (görünmez) olduğu anda içerik değişip 90→0'a devam ediyor — böylece
    // arka yüz "aynalı" görünüp yarım çevrilirken sızmıyor.
    const [cardFlipped, setCardFlipped] = useState(false);
    const cardFlipAnim = useRef(new Animated.Value(0)).current;
    const flipCard = () => {
        Animated.timing(cardFlipAnim, { toValue: 0.5, duration: 150, useNativeDriver: true }).start(() => {
            setCardFlipped(b => !b);
            Animated.timing(cardFlipAnim, { toValue: cardFlipped ? 0 : 1, duration: 150, useNativeDriver: true }).start();
        });
    };
    const cardFlipRotate = cardFlipAnim.interpolate({ inputRange: [0, 0.5, 1], outputRange: ['0deg', '90deg', '0deg'] });
    // Sipariş butonu: ilan sahibi ya da o ana kadar kabul edilmiş katılımcı/partner —
    // maç henüz eşleşmemiş (açık ilan) olsa bile, kort zaten rezerve edildiyse sipariş
    // verilebilir; maç saatinin gelmesi ya da eşleşmenin tamamlanması şart değil.
    const isRivalParticipant = isOwner || item.receiverId === myId
        || participants.some(p => p?.id === myId) || senderTeamArr.some(p => p?.id === myId);
    const [orderVenueId, setOrderVenueId] = useState(null);
    const required = item.matchType === 'DOUBLE'
        ? ((Array.isArray(item.senderTeam) && item.senderTeam.length > 0) ? 2 : 3)
        : (item.teamSize || 1);
    const filled = participants.filter(p => p?.id || p?.manualName).length;
    const isFull = filled >= required;
    const [localJoinStatus, setLocalJoinStatus] = useState(null);
    const mySentReq = localJoinStatus ?? item._myJoinStatus;
    const myInvite = (Array.isArray(item.joinRequests) ? item.joinRequests : []).find(jr => jr.userId === myId && jr.initiatedBy === 'OWNER');
    const [detailVisible, setDetailVisible] = useState(false);
    const [editVisible, setEditVisible] = useState(false);
    // Voleybol "Rakip Aranıyor" (player_wanted + teamSize>1): katılma tek başına değil,
    // tam takım doldurularak yapılıyor — bkz. TeamJoinRequestModal.
    const [showTeamJoinModal, setShowTeamJoinModal] = useState(false);
    const isTeamWantedAd = sub === 'volleyball' && item.matchType === 'PLAYER_WANTED' && (item.teamSize || 1) > 1;
    // Kullanıcı isteği: voleybol takım maçına katılım isteği gönderirken hangi pozisyonda
    // oynamak istediğini (öncelik sırasıyla, ör. önce Pasör olmazsa Smaçör) belirtebilsin —
    // ilan sahibi İstekler listesinde bunu görüp kabul/red kararını buna göre versin.
    const [showPositionPicker, setShowPositionPicker] = useState(false);
    const [selectedPositions, setSelectedPositions] = useState([]); // dokunma sırası = öncelik sırası
    const isVolleyballTeamMatch = sub === 'volleyball' && (item.teamSize || 1) > 1 && !isTeamWantedAd;
    const togglePositionPref = (pos) => {
        setSelectedPositions(prev => prev.includes(pos) ? prev.filter(p => p !== pos) : [...prev, pos]);
    };
    const confirmJoinWithPosition = () => {
        setShowPositionPicker(false);
        handleJoinPress(undefined, selectedPositions);
        setSelectedPositions([]);
    };
    // Düzenleme, ilan detayından mı yoksa karttaki ✏️ butonundan mı açıldı —
    // kapatınca (X veya telefonun geri tuşu) sadece detaydan açıldıysa detaya
    // geri dönülsün diye.
    const editOpenedFromDetailRef = useRef(false);
    const closeEdit = () => {
        setEditVisible(false);
        if (editOpenedFromDetailRef.current) setTimeout(() => setDetailVisible(true), 300);
    };
    // Kullanıcı isteği: ilan detayındayken (voleybolde maç saati gelip yetersiz oyuncu
    // nedeniyle) ilan otomatik kaldırılırsa, ölü bir detay ekranında kalınmasın — detay
    // kapanıp altındaki spor sayfasına dönülsün (backend artık bunu sadece ilan sahibine
    // değil, o ana kadar katılmış herkese de bildiriyor, bkz. cleanupRivals.js).
    useEffect(() => {
        const off = onSocket('rivalDeleted', ({ rivalId }) => {
            if (rivalId !== item.id) return;
            setDetailVisible(false);
            setEditVisible(false);
        });
        return off;
    }, [item.id]);

    // Hakemlik için hızlı başvuru — maç detayına hiç girmeden, kart üzerinden
    // doğrudan fiyat/mesaj ile başvurabilsin diye.
    const [refereeApplyVisible, setRefereeApplyVisible] = useState(false);
    const [refereeOfferPrice, setRefereeOfferPrice] = useState('');
    const [refereeOfferMessage, setRefereeOfferMessage] = useState('');
    const [refereeApplySubmitting, setRefereeApplySubmitting] = useState(false);
    const submitRefereeApply = async () => {
        setRefereeApplySubmitting(true);
        try {
            await api.post(`/rivals/${item.id}/respond`, {
                asReferee: true,
                offerPrice: refereeOfferPrice ? `${refereeOfferPrice}₺` : undefined,
                offerMessage: refereeOfferMessage || undefined,
            });
            setRefereeApplyVisible(false);
            setRefereeOfferPrice('');
            setRefereeOfferMessage('');
            onRefresh();
        } catch (e) {
            Alert.alert(t.error, e?.response?.data?.message || t.actionFailed);
        } finally {
            setRefereeApplySubmitting(false);
        }
    };

    useEffect(() => {
        // Kullanıcı raporu: bildirimden gelip ilan otomatik açılırken hemen ardından
        // tetiklenen bu onRefresh() — tüm ekranın verisini (rivals/PW/upcoming/posts/...)
        // baştan çekip modal AÇIKKEN item referansını değiştiriyordu, bu da üstteki özet
        // bilgi satırının bir kaç yüz ms sonra "kayması"na yol açıyordu. item burada zaten
        // autoOpen'ı tetikleyen load() çağrısından gelen taze veri — hemen tekrar çekmeye
        // gerek yok.
        if (autoOpen) { setDetailVisible(true); onAutoOpened?.(); }
    }, [autoOpen]);

    // Telefonun geri tuşu (Android donanım/gesture back) varsayılan olarak
    // ekranın tamamından çıkıp bir önceki sayfaya atıyordu — açık bir modal
    // varken önce SADECE o modalı kapatması için burada yakalanıyor.
    // isFocused şartı: kullanıcı ilan detayındayken kullanıcı avatarına dokunup
    // Profile'a gidince (navigation.push) bu kart hâlâ mount'lu kalıyor (React
    // Navigation ekranları push'ta unmount etmiyor) ve BackHandler dinleyicisi
    // global olduğu için Profile ekranındayken basılan geri tuşunu da bu kart
    // yakalayıp sessizce detailVisible'ı kapatıyordu — geri tuşu Profile'ı hiç
    // POP'lamıyor, kullanıcı ikinci kez geri basınca da artık detay kapanmış
    // olduğu için doğrudan açık ilanlar listesine düşüyordu (kullanıcı raporu).
    const isFocused = useIsFocused();
    useEffect(() => {
        if (!isFocused) return;
        const onBackPress = () => {
            if (editVisible) { closeEdit(); return true; }
            if (detailVisible) { setDetailVisible(false); return true; }
            return false;
        };
        const sub = BackHandler.addEventListener('hardwareBackPress', onBackPress);
        return () => sub.remove();
    }, [editVisible, detailVisible, isFocused]);

    // Sunucudan gelen veri local override'ı geçersiz kılar
    useEffect(() => { setLocalJoinStatus(null); }, [item._myJoinStatus]);

    useEffect(() => {
        const offRejected = onSocket('joinRejected', ({ rivalId }) => {
            if (rivalId !== item.id) return;
            setLocalJoinStatus(null);
            onRefresh();
        });
        const offAccepted = onSocket('joinAccepted', ({ rivalId }) => {
            if (rivalId !== item.id) return;
            setLocalJoinStatus('ACCEPTED');
            onRefresh();
        });
        const offLate = onSocket('joinLateAccepted', ({ rivalId }) => {
            if (rivalId !== item.id) return;
            setLocalJoinStatus('AWAITING_JOINER_CONFIRM');
            onRefresh();
        });
        return () => { offRejected(); offAccepted(); offLate(); };
    }, [item.id]);

    const handleConfirmLateJoin = async (action) => {
        try {
            const myReqId = item._myJoinRequestId;
            if (!myReqId) { onRefresh(); return; }
            const { data } = await api.patch(`/rivals/join/${myReqId}/confirm`, { action });
            if (action === 'confirm') {
                setLocalJoinStatus('ACCEPTED');
                // Kullanıcı isteği: "son onay bekleniyor" durumundaki birden fazla oyuncu
                // sırayla onaylanırken ana kadro dolarsa, dışarda kalan (yedek kontenjanı
                // varsa) yedeğe alınıyor — bu durumda sessizce geçmek yerine kullanıcıya
                // ayrıca haber verilir (createNotification zaten kalıcı bildirim de gönderiyor).
                if (data?.toSubstitute) Alert.alert('🔄', t.lateAcceptSubstitutedMsg || 'Onayınızı beklerken ana kadro doldu — yedek kadroya alındınız.');
                setTimeout(onRefresh, 1200);
            }
            else { setLocalJoinStatus(null); onRefresh(); }
        } catch (e) {
            if (e?.response) Alert.alert(t.error, e.response.data?.message || t.actionFailed);
            else onRefresh();
        }
    };

    const handleWithdraw = () => {
        Alert.alert(t.withdrawReqTitle, t.withdrawReqMsg, [
            { text: t.no },
            { text: t.withdrawReqConfirmBtn, style: 'destructive', onPress: async () => {
                try {
                    const myReqId = item._myJoinRequestId;
                    if (!myReqId) { onRefresh(); return; }
                    await api.delete(`/rivals/join/${myReqId}`);
                    setLocalJoinStatus(null);
                    onRefresh();
                } catch (e) {
                    if (e?.response) Alert.alert(t.error, e.response.data?.message || t.actionFailed);
                    else { setLocalJoinStatus(null); onRefresh(); }
                }
            }},
        ]);
    };

    const handleJoin = async (requestedSlot, positionPreferences) => {
        // Puan limiti kontrolü artık burada değil, sadece sunucuda yapılıyor — myRating
        // (Redux'taki auth.user.interests'ten) maç sonrası puan güncellemelerinde bayatlayabiliyordu,
        // bu da güncel puanı yeterli olan kullanıcıları yanlışlıkla "puanınız 0" diye engelliyordu.
        try {
            setLocalJoinStatus('PENDING'); // anlık göster
            await api.post(`/rivals/${item.id}/respond`, {
                ...(requestedSlot && { requestedSlot }),
                ...(Array.isArray(positionPreferences) && positionPreferences.length > 0 && { positionPreferences }),
            });
            onRefresh();
        } catch (e) {
            if (!e?.response) { onRefresh(); return; } // network drop — sunucu aldı, yenile
            setLocalJoinStatus(null); // hata varsa geri al
            const msg = e.response.data?.message || '';
            if (msg.toLowerCase().includes('already') || msg.toLowerCase().includes('no longer')) {
                onRefresh();
                if (msg.toLowerCase().includes('no longer')) Alert.alert(t.error, t.requestNoLongerOpen || 'Bu ilan artık açık değil.');
                return;
            }
            Alert.alert(t.error, msg || t.requestFailed);
        }
    };

    // Çiftlerde de doğrudan bireysel başvuru gönderilir — partner eşleştirme, başvuru
    // gönderildikten sonra İstekler bölümündeki takım kartlarından (davet et/kabul et) yapılır.
    // Takım Değiştirilemez (STRICT) çiftler maçında ise başvuran hangi tarafa katılacağını
    // (kurucu takımı / rakip takımı) en baştan seçmek zorunda — bkz. ilgili buton grupları.
    const handleJoinPress = (requestedSlot, positionPreferences) => {
        handleJoin(requestedSlot, positionPreferences);
    };


    const handleCancel = async () => {
        Alert.alert(t.cancelConfirmTitle, t.cancelConfirmMsg, [
            { text: t.no },
            { text: t.yes, style: 'destructive', onPress: async () => {
                try {
                    const { data } = await api.patch(`/rivals/${item.id}/cancel`, {});
                    // Bağlı bir kort rezervasyonu vardı ama işletmenin iptal/değişiklik
                    // politikasına uymadığı için otomatik iptal edilmediyse uyar (cancelMatch'teki
                    // aynı uyarı — kullanıcı isteği: "ilanı iptal ettiğimde rezervasyon da iptal
                    // olucaktı, uymuyorsa işletmeye talep gönderildi diye uyarı gelecekti").
                    if (data?.venuePolicyWarning) Alert.alert('', data.venuePolicyWarning);
                    onRefresh();
                }
                catch(e) {
                    if (e?.response) Alert.alert(t.error, e.response.data?.message || t.deleteFailed);
                    else onRefresh(); // network drop — server likely cancelled it
                }
            }}
        ]);
    };

    const handleRespondJoin = async (jrId, action) => {
        try {
            const res = await api.patch(`/rivals/join/${jrId}`, { action });
            if (action === 'accept' && res.data?.lateAccept) {
                Alert.alert(t.lateAcceptTitle, t.lateAcceptMsg);
                onRefresh();
            } else if (action === 'accept' && res.data?.matched) {
                setTimeout(onRefresh, 1200);
            } else {
                onRefresh();
            }
        } catch(e) {
            if (e?.response) Alert.alert(t.error, e.response.data?.message || t.actionFailed);
            onRefresh(); // her durumda yenile — iyimser güncellemeyi geri al
        }
    };

    const rival = { id:item.id, subCategory:item.subCategory, matchType:item.matchType, level:item.level, matchDate:item.matchDate, matchTime:item.matchTime, location:item.location, courtName:item.courtName, flexibleSchedule:item.flexibleSchedule };

    // Kullanıcı isteği: kadro kartı (arka yüz) — katılan herkes (kurucu + takım arkadaşları +
    // rakip taraf + henüz tarafa atanmamış kabul edilmişler), elo puanlarıyla birlikte.
    const backFacePlayers = [
        item.sender,
        ...senderTeamArr,
        ...participants,
        ...(Array.isArray(item.unassignedPlayers) ? item.unassignedPlayers : []),
    ].filter(p => p?.id);

    return (
        <>
        <Animated.View style={[s.card, { width:'48%', borderRadius: moderateScale(14), paddingHorizontal:0, paddingTop:0, paddingBottom:0, minHeight: moderateScale(230) }, item.flexibleSchedule && { borderColor:'#eab30840' }, { transform:[{ perspective:800 }, { rotateY: cardFlipRotate }] }]}>
            {/* 🔄 Çevir — kartın geri kalanından ayrı, kendi dokunma hedefi (ilan detayını açmaz). */}
            <TouchableOpacity onPress={flipCard} hitSlop={{ top:8, bottom:8, left:8, right:8 }}
                style={{ position:'absolute', top:6, right:6, zIndex:10, backgroundColor:'#00000060', borderRadius:12, width:22, height:22, alignItems:'center', justifyContent:'center' }}>
                <Text style={{ fontSize:12 }}>🔄</Text>
            </TouchableOpacity>
            {cardFlipped ? (
                // Kullanıcı isteği: arka yüzden (oyuncu listesi) de dokununca ilan detayı açılsın —
                // önceden sadece ön yüz açıyordu, arka yüzde dokunmanın hiçbir etkisi yoktu. İçindeki
                // "istek"/"Sipariş Ver" gibi kendi onPress'i olan öğeler yine kendi işlevini korur.
                <TouchableOpacity activeOpacity={0.85} style={{ padding: moderateScale(9), flex:1 }} onPress={() => setDetailVisible(true)}>
                    <Text style={{ color:'#fff', fontSize:moderateScale(12), fontWeight:'800', marginBottom:8 }}>👥 {t.rosterPoolLabel}</Text>
                    {backFacePlayers.length === 0 ? (
                        <Text style={{ color: colors.textMuted, fontSize:moderateScale(11) }}>{t.noPlayersYet || 'Henüz katılan yok'}</Text>
                    ) : (
                        <ScrollView showsVerticalScrollIndicator={false}>
                            {backFacePlayers.map((p, i) => {
                                const r = p.skillRating ?? p.interests?.[0]?.skillRating;
                                return (
                                    <View key={p.id || i} style={{ flexDirection:'row', alignItems:'center', gap:3, marginBottom:6 }}>
                                        <Avatar name={p.username} avatar={p.avatar} size={moderateScale(20)} color={cfg.color} />
                                        <Text style={{ color:'#fff', fontSize:moderateScale(11), flex:1, minWidth:0 }} numberOfLines={1} adjustsFontSizeToFit minimumFontScale={0.75}>{playerDisplayName(p)}</Text>
                                        {/* Kullanıcı isteği: elo/derece puanı artık ilan sahibi dahil HERKESE
                                            görünsün — önceki "sahip görmesin" kısıtı kaldırıldı. */}
                                        {r != null && <Text style={{ color:'#facc15', fontSize:moderateScale(10), fontWeight:'800' }}>{Number(r).toFixed(2)} ★</Text>}
                                    </View>
                                );
                            })}
                        </ScrollView>
                    )}
                    {/* Kullanıcı isteği: liste kartında (detaya girmeden) "istek" rozeti ve
                        "Sipariş Ver" artık ön yüzde değil, dıgımon kartın ARKA yüzünde, oyuncu
                        listesinin ALTINDA — ön yüz sadece ilan bilgisi. */}
                    {isOwner && (item.joinRequests||[]).filter(jr => jr.initiatedBy !== 'OWNER').length > 0 && (
                        <TouchableOpacity onPress={() => setDetailVisible(true)} style={{ marginTop:6 }}>
                            <Text style={{ color: colors.purple, fontSize:moderateScale(11), fontWeight:'700' }} numberOfLines={1}>
                                📬 {item.joinRequests.filter(jr => jr.initiatedBy !== 'OWNER').length} {t.requests || 'istek'}
                            </Text>
                        </TouchableOpacity>
                    )}
                    {item.venueId && isRivalParticipant && (
                        <TouchableOpacity onPress={() => setOrderVenueId(item.venueId)} style={{ marginTop:6 }}>
                            <Text style={{ color:'#22c55e', fontSize: moderateScale(11), fontWeight:'600' }}>📋 Sipariş Ver</Text>
                        </TouchableOpacity>
                    )}
                </TouchableOpacity>
            ) : (
            <>
            {/* ── Tappable info area → opens detail modal ──
                 Not: burada ayrıca onRefresh() (tüm liste yenileme) ÇAĞRILMIYOR —
                 modal zaten kendi içinde tek ilan için taze veri çekiyor
                 (bkz. RivalDetailModal'daki useEffect), listeyi de yenilemek
                 gereksiz bir ağ isteği + yeniden render'a (algılanan ~1sn
                 gecikmeye) yol açıyordu. */}
            <TouchableOpacity activeOpacity={0.85} onPress={() => setDetailVisible(true)}>

                {/* Avatar + isim/puan + mod/format */}
                <View style={{ flexDirection:'row', alignItems:'flex-start', gap:3, marginBottom:3 }}>
                    <Avatar name={item.sender?.username} avatar={item.sender?.avatar} size={moderateScale(34)} color={cfg.color} onPress={() => item.senderId && navigation.push('Profile', { userId: item.senderId })} />
                    <View style={{ flex:1, minWidth:0 }}>
                        <View style={{ flexDirection:'row', alignItems:'center', gap:4 }}>
                            <Text style={[s.cardName, { fontSize: moderateScale(13), flexShrink:1 }]} numberOfLines={1} adjustsFontSizeToFit minimumFontScale={0.75}>{senderAlias(item.sender)}</Text>
                            {item.sender?.interests?.[0]?.assessmentCompleted && (
                                <Text style={[s.ratingText, { color: cfg.color, fontSize: moderateScale(10) }]}>
                                    {Number(item.sender.interests[0].skillRating).toFixed(2)} ★
                                </Text>
                            )}
                        </View>
                        {/* Mod + 1v1/2v2 — fotoğrafın sağına, isimle aynı hizada */}
                        <View style={{ flexDirection:'row', alignItems:'center', gap:3, marginTop:3, flexWrap:'wrap' }}>
                            <ModeBadge mode={item.matchMode} noEmoji={isVolleyball} />
                            <View style={[s.modeBadge, { backgroundColor: cfg.color+'20', borderColor: cfg.color+'40', borderRadius: moderateScale(8), paddingHorizontal:0, paddingVertical:0 }]}>
                                <Text style={[s.modeBadgeText, { color: cfg.color, fontSize: moderateScale(10) }]}>
                                    {TEAM_SPORTS.has(sub) ? `${item.teamSize||1}v${item.teamSize||1}` : (item.matchType==='DOUBLE' ? '2v2' : '1v1')}
                                </Text>
                            </View>
                            {/* Kullanıcı isteği: takım büyüklüğünün ("6v6") hemen sağında kadronun
                                şu an kaçta kaç dolduğu (ör. 4/12) — kart açılmadan görülsün. */}
                            {TEAM_SPORTS.has(sub) && (() => {
                                const teamSizeN = item.teamSize || 1;
                                const filledCount = 1 // kurucu
                                    + senderTeamArr.filter(p => p?.id || p?.manualName).length
                                    + participants.filter(p => p?.id || p?.manualName).length
                                    + (Array.isArray(item.oppTeamManualNames) ? item.oppTeamManualNames.length : 0)
                                    + (Array.isArray(item.unassignedPlayers) ? item.unassignedPlayers.filter(p => p?.id || p?.manualName).length : 0);
                                return (
                                    <Text style={{ color: colors.textMuted, fontSize: moderateScale(10), fontWeight:'700' }}>
                                        {filledCount}/{teamSizeN * 2}
                                    </Text>
                                );
                            })()}
                        </View>
                    </View>
                </View>
                {Array.isArray(item.positions) && (item.positions.includes('REFEREE') || item.positions.includes('REFEREE_OFFER')) && (
                    <View style={{ flexDirection:'row', alignItems:'center', gap:3, marginBottom:3 }}>
                        <View style={{ backgroundColor:'#f59e0b20', borderRadius:6, paddingHorizontal:5, paddingVertical:0, borderWidth:1, borderColor:'#f59e0b50', flexShrink:1 }}>
                            <Text style={{ color:'#f59e0b', fontSize:moderateScale(10), fontWeight:'700' }} numberOfLines={1} adjustsFontSizeToFit minimumFontScale={0.75}>
                                {item.positions.includes('REFEREE_OFFER') ? t.refereeOfferingLabel : t.refereeSeekingLabel}
                            </Text>
                        </View>
                        {item.refereePayment && <Text style={{ color:'#f59e0b', fontSize:moderateScale(10), fontWeight:'700' }} numberOfLines={1} adjustsFontSizeToFit minimumFontScale={0.75}>{item.refereePayment}</Text>}
                    </View>
                )}
                {item.linkedRivalId && (
                    <Text style={{ color:'#fbbf24', fontSize:moderateScale(10), fontWeight:'700', marginBottom:3 }} numberOfLines={2}>
                        {t.refereeForMatchLabel}
                    </Text>
                )}
                {/* Tarih / Saat / Süre */}
                {!item.flexibleSchedule && (item.matchDate || item.matchTime || item.duration) && (
                    <View style={{ gap:3, marginBottom:3 }}>
                        {item.matchDate && <Text style={[s.metaItemText, { fontSize: moderateScale(11) }]} numberOfLines={2}>{isVolleyball ? '' : '📅 '}{new Date(item.matchDate).toLocaleDateString(t.dateLocale,{day:'numeric',month:'long',weekday:'long'})}</Text>}
                        {(item.matchTime || item.duration) && (
                            <Text style={[s.metaItemText, { fontSize: moderateScale(11) }]} numberOfLines={1} adjustsFontSizeToFit minimumFontScale={0.75}>
                                {item.matchTime ? (() => { const [h,m]=item.matchTime.split(':').map(Number); const dur=parseInt(item.duration||0); const tot=h*60+m+dur; const endT=dur>0?`–${String(Math.floor(tot/60)%24).padStart(2,'0')}:${String(tot%60).padStart(2,'0')}`:''; return `${isVolleyball ? '' : '🕐 '}${item.matchTime}${endT}`; })() : ''}{item.matchTime && item.duration ? '  ·  ' : ''}{item.duration ? `${item.duration} ${t.timeMinSuffix}` : ''}
                            </Text>
                        )}
                    </View>
                )}
                {(() => {
                    // ratingGenderSplit seçiliyse minRating/maxRating boş kalır, gösterge minRatingMale/
                    // Female'e bakmalı — aksi halde "derece kısıtlaması koydum ama görünmüyor" oluyordu.
                    const hasRatingRange = item.ratingGenderSplit
                        ? (item.minRatingMale != null || item.maxRatingMale != null || item.minRatingFemale != null || item.maxRatingFemale != null)
                        : (item.minRating != null || item.maxRating != null);
                    const hasSingleGenderReq = item.genderReq && item.genderReq !== 'MIX';
                    const hasDoubleGenderReq = item.matchType === 'DOUBLE' && (item.partnerGenderReq !== 'MIX' || item.opp1GenderReq !== 'MIX' || item.opp2GenderReq !== 'MIX');
                    const hasGenderCount = item.subCategory === 'volleyball' && item.teamSize > 1 && hasGenderCountInfo(item);
                    const hasCancelPenalty = item.subCategory === 'volleyball' && item.cancelPenaltyHours != null;
                    if (!hasRatingRange && !hasSingleGenderReq && !hasDoubleGenderReq && !hasGenderCount && !hasCancelPenalty) return null;
                    return (
                        <View style={{ flexDirection:'row', alignItems:'center', gap:5, marginBottom:3, flexWrap:'wrap' }}>
                            {hasRatingRange && (
                                <Text style={{ color:'#facc15', fontSize:moderateScale(10), fontWeight:'700' }}>
                                    {item.ratingGenderSplit
                                        ? `⭐ 👨${item.minRatingMale ?? 0}-${item.maxRatingMale ?? 5}  👩${item.minRatingFemale ?? 0}-${item.maxRatingFemale ?? 5}`
                                        : `⭐ ${item.minRating ?? '0'}–${item.maxRating ?? '5'}`}
                                </Text>
                            )}
                            {hasGenderCount && (
                                <Text style={{ color:'#a855f7', fontSize:moderateScale(10), fontWeight:'700' }}>
                                    {genderCountDisplayLabel(item)}
                                </Text>
                            )}
                            {hasCancelPenalty && (
                                <Text style={{ color:'#f87171', fontSize:moderateScale(9), fontWeight:'700' }} numberOfLines={1} adjustsFontSizeToFit minimumFontScale={0.75}>
                                    {t.cancelPenaltyBadge(item.cancelPenaltyHours)}
                                </Text>
                            )}
                            {hasSingleGenderReq && (
                                <View style={{ backgroundColor: item.genderReq === 'MALE' ? '#3b82f620' : '#ec489920', borderColor: item.genderReq === 'MALE' ? '#3b82f6' : '#ec4899', borderWidth:1, borderRadius: moderateScale(8), paddingHorizontal: moderateScale(5), paddingVertical: moderateScale(1) }}>
                                    <Text style={{ color: item.genderReq === 'MALE' ? '#3b82f6' : '#ec4899', fontSize: moderateScale(9), fontWeight:'800' }}>
                                        {item.genderReq === 'MALE' ? '👨' : '👩'}
                                    </Text>
                                </View>
                            )}
                            {hasDoubleGenderReq && (() => {
                                const gL = (g) => g === 'MALE' ? '♂' : g === 'FEMALE' ? '♀' : '⚥';
                                // Kullanıcı isteği: detay ekranındaki gibi burada da ilanı açan kişinin
                                // (kurucu) GERÇEK cinsiyeti dahil edildi — 2v2'de 4 kişi olduğu için 4
                                // emoji gösterilmesi lazım, önceden sadece 3 slotun kısıtlaması
                                // gösteriliyordu (bkz. RivalDetailModal'daki aynı isim ve gerekçeli
                                // düzeltme, orada "hepsi aynı" tek-sembol kısayolu da aynı sebeple
                                // kaldırıldı).
                                const label = `${gL(item.sender?.gender)}${gL(item.partnerGenderReq)}${gL(item.opp1GenderReq)}${gL(item.opp2GenderReq)}`;
                                return (
                                    <View style={{ backgroundColor:'#a855f715', borderColor:'#a855f740', borderWidth:1, borderRadius: moderateScale(8), paddingHorizontal: moderateScale(5), paddingVertical: moderateScale(1) }}>
                                        <Text style={{ color:'#a855f7', fontSize: moderateScale(9), fontWeight:'800' }} numberOfLines={1}>{label}</Text>
                                    </View>
                                );
                            })()}
                        </View>
                    );
                })()}

                {/* Voleybol türü (Salon/Plaj/Çim/Mahalle/Toprak) artık ayrı filtre sekmesi değil,
                    kort bilgisinin hemen üstünde bilgi satırı olarak gösteriliyor (kullanıcı isteği). */}
                {item.subCategory === 'volleyball' && !!VOLLEYBALL_SURFACES.find(v => v.id === item.surface) && (
                    <Text style={{ fontSize:moderateScale(10), marginBottom:2, color: colors.textMuted, fontWeight:'700' }} numberOfLines={1}>
                        {(() => { const v = VOLLEYBALL_SURFACES.find(v => v.id === item.surface); return `${v.emoji} ${t.lang === 'tr' ? v.label : v.labelEn}`; })()}
                    </Text>
                )}
                {item.courtName && (
                    <TouchableOpacity onPress={() => openCourtMap(item.courtName, item.courtLat, item.courtLng, item.courtAddress)}>
                        <Text style={{ fontSize:moderateScale(11), marginBottom:3, color:'#60a5fa', textDecorationLine:'underline' }} numberOfLines={1} adjustsFontSizeToFit minimumFontScale={0.75}>{isVolleyball ? '' : '🏟️ '}{item.courtName}</Text>
                    </TouchableOpacity>
                )}
                {/* Hakem — kullanıcı isteğiyle salon adının altında, "rezerve edildi" satırının
                    üstünde (önceden kartın en üstünde, tarih/derece bilgisinden bile önce çıkıyordu). */}
                {item.refereeRequested && (
                    <View style={{ flexDirection:'row', alignItems:'center', gap:3, marginBottom:3, flexWrap:'wrap' }}>
                        <View style={{ backgroundColor:'#f59e0b20', borderRadius:6, paddingHorizontal:5, paddingVertical:0, borderWidth:1, borderColor:'#f59e0b50', flexShrink:1 }}>
                            <Text style={{ color:'#f59e0b', fontSize:moderateScale(10), fontWeight:'700' }} numberOfLines={1} adjustsFontSizeToFit minimumFontScale={0.75}>
                                {t.refereeSlotLabel}: {item.refereeUser ? (item.refereeUser.fullName || item.refereeUser.username) : item.manualRefereeName ? item.manualRefereeName : t.refereeSlotSearching}
                            </Text>
                        </View>
                        {item.refereePayment && <Text style={{ color:'#f59e0b', fontSize:moderateScale(10), fontWeight:'700' }} numberOfLines={1} adjustsFontSizeToFit minimumFontScale={0.75}>{item.refereePayment}</Text>}
                    </View>
                )}
                {/* Kullanıcı isteği: as kadro dolup sadece yedek kadroda boşluk kaldığında
                    (ilan bu yüzden hâlâ "açık" sayılıyor) — hakem durumu gibi kaç yedek
                    yeri kaldığı da kartta görünsün, detaya girmeden. */}
                {item.subCategory === 'volleyball' && (item.substituteCount || 0) > (Array.isArray(item.substitutePlayers) ? item.substitutePlayers.length : 0) && (
                    <View style={{ flexDirection:'row', alignItems:'center', gap:3, marginBottom:3 }}>
                        <View style={{ backgroundColor:'#0ea5e920', borderRadius:6, paddingHorizontal:5, paddingVertical:0, borderWidth:1, borderColor:'#0ea5e950' }}>
                            <Text style={{ color:'#38bdf8', fontSize:moderateScale(10), fontWeight:'700' }} numberOfLines={1} adjustsFontSizeToFit minimumFontScale={0.75}>
                                🪑 {t.substituteOpenSlotsLabel((item.substituteCount || 0) - (item.substitutePlayers?.length || 0))}
                            </Text>
                        </View>
                    </View>
                )}
                <Text style={{ fontSize:moderateScale(11), marginBottom:3, color: item.isCourtReserved ? '#4ade80' : '#f87171' }} numberOfLines={1} adjustsFontSizeToFit minimumFontScale={0.75}>
                    {item.isCourtReserved ? `${isVolleyball ? '' : '✅ '}${isVolleyball ? t.volleyballHallReservedLabel : t.courtReservedLabel}` : `${isVolleyball ? '' : '❌ '}${t.courtNotReserved}`}
                </Text>
                {item.courtFeePerPerson > 0 && (() => {
                    // Kullanıcı isteği: kart üzerinde tüm ödeme yöntemlerinin ayrı bir satırda
                    // dökümü yerine (o detayda zaten var), sadece kredi kartı fiyatı aynı satıra
                    // eklensin — kart için iki fiyat (nakit + kredi kartı) yeterli, detayda hepsi
                    // görünmeye devam ediyor (bkz. RivalDetailModal'daki feeByMethodEntries).
                    const ccPrice = item.courtFeePerPersonByMethod?.CREDIT_CARD;
                    const showCc = ccPrice > 0 && ccPrice !== item.courtFeePerPerson;
                    return (
                        <Text style={{ fontSize:moderateScale(11), marginBottom:3, color:'#4ade80' }} numberOfLines={1} adjustsFontSizeToFit minimumFontScale={0.75}>
                            {isVolleyball ? '' : '💰 '}{item.courtFeePerPerson}{item.refereeFeePerPerson > 0 ? `+${item.refereeFeePerPerson}` : ''}₺{item.refereeRequested && !item.refereeFeePerPerson && !item.refereeFeeIncluded ? ` +${t.refereeFeeHint}` : ''} / {t.perPerson}
                            {showCc && ` · 💳 ${ccPrice}₺`}
                        </Text>
                    );
                })()}

                {/* Kullanıcı isteği: "Sipariş Ver" artık burada (ön yüz) değil, arka yüzde
                    oyuncu listesinin altında (bkz. cardFlipped bloğu yukarıda) — modal
                    (VenueMenuOrderModal) paylaşılan orderVenueId state'i sayesinde hangi
                    yüzden açıldığından bağımsız çalışıyor. */}
                <VenueMenuOrderModal
                    visible={!!orderVenueId}
                    venueId={orderVenueId}
                    rivalId={item.id}
                    onClose={() => setOrderVenueId(null)}
                />

                {item.flexibleSchedule && (
                    <View style={[s.flexBanner, { borderRadius: moderateScale(10), padding:0, marginBottom:3 }]}>
                        <Text style={[s.flexTitle, { fontSize: moderateScale(11), marginBottom:3 }]}>{t.flexibleBanner}</Text>
                        <Text style={[s.flexDesc, { fontSize: moderateScale(10) }]}>{t.flexibleBannerDesc}</Text>
                    </View>
                )}
                {(item.level || item.levelDetail) && (
                    <View style={[s.levelRow, { gap:3, marginBottom:3 }]}>
                        {item.level && <Text style={[s.levelBadge, { borderRadius: moderateScale(8), paddingHorizontal:3, paddingVertical:3, fontSize: moderateScale(10) }]} numberOfLines={1} adjustsFontSizeToFit minimumFontScale={0.75}>{LEVEL_EMOJI[item.level]} {t.levelTr[item.level] || item.level}</Text>}
                        {item.levelDetail && <Text style={[s.levelDetail, { borderRadius: moderateScale(8), paddingHorizontal:3, paddingVertical:3, fontSize: moderateScale(10) }]} numberOfLines={1} adjustsFontSizeToFit minimumFontScale={0.75}>{item.levelDetail}</Text>}
                    </View>
                )}
                {item.message && <Text style={[s.cardMsg, { fontSize: moderateScale(12), marginBottom:3 }]} numberOfLines={2}>{item.message}</Text>}
                {item.wager && (
                    <Text style={{ color:'#fbbf24', fontSize: moderateScale(11), fontWeight:'700', marginBottom:4 }} numberOfLines={1} adjustsFontSizeToFit minimumFontScale={0.75}>
                        🏆 {item.wager}
                    </Text>
                )}
                {/* Kullanıcı isteği: kabul edilen oyuncuların listesi ön yüzden kaldırıldı —
                    kart artık önlü-arkalı "digimon kart" (bkz. backFacePlayers/cardFlipped
                    yukarıda), aynı liste zaten 🔄 ile çevrilince arka yüzde görünüyor, ön
                    yüzde tekrar göstermek gereksiz tekrar oluyordu. */}
                {/* Kullanıcı isteği: istek rozeti artık burada (ön yüz) değil, 🔄 ile
                    çevrilince açılan arka yüzde, oyuncu listesinin altında (bkz. cardFlipped
                    bloğu yukarıda) — ön yüz sadece yorum sayısını gösterir. */}
                <View style={{ flexDirection:'row', alignItems:'center', gap:6, marginBottom:3 }}>
                    <Text style={{ color: colors.textMuted, fontSize:moderateScale(11) }}>
                        💬 {item.commentCount ?? 0}
                    </Text>
                </View>
            </TouchableOpacity>

            {/* Aksiyon alanı — kullanıcı isteği: kompakt kartta Düzenle/İptal Et/İstek At
                (Katıl) artık YOK — kullanıcı önce detaya girip kadroyu vs. inceleyip ona göre
                istek atsın. Kart zaten tıklanınca detayı açıyor, tüm bu aksiyonlar orada var. */}
            <View>
                {isOwner ? null : isLinkedMatchPlayer ? (
                    <Text style={{ color: colors.textMuted, fontSize:moderateScale(10), textAlign:'center' }} numberOfLines={2}>Bu maça oyuncu olarak katıldığınız için hakemlik başvurusu yapamazsınız.</Text>
                ) : myInvite ? (() => {
                    // Kullanıcı isteğiyle davet rozeti artık hangi takıma/role davet edildiğini
                    // açıkça yazıyor — önceden hepsi aynı genel "Davet Edildi" yazısıydı, oyuncu
                    // Kurucu mu Rakip mi olacağını ancak detaya girip bakınca anlayabiliyordu.
                    const teamHint = (item.teamSize || 1) > 1
                        ? (myInvite.isPartnerInvite ? ` (${t.founderTeamShortLabel})`
                            : myInvite.isSubstituteInvite ? ` (${t.subsLabel})`
                            : myInvite.isUnassignedInvite ? ''
                            : ` (${t.opponentTeamShortLabel})`)
                        : (myInvite.isPartnerInvite ? ` (${t.founderTeamShortLabel})` : '');
                    return (
                        <TouchableOpacity
                            style={{ backgroundColor:'#16a34a', borderRadius:moderateScale(8), paddingVertical:moderateScale(5), alignItems:'center' }}
                            onPress={() => setDetailVisible(true)}
                        >
                            <Text style={{ color:'#fff', fontSize:moderateScale(11), fontWeight:'700' }} numberOfLines={1} adjustsFontSizeToFit minimumFontScale={0.75}>{t.invitedBadge}{teamHint}</Text>
                        </TouchableOpacity>
                    );
                })() : mySentReq === 'AWAITING_JOINER_CONFIRM' ? (
                    <View style={{ gap:3 }}>
                        <Text style={{ color:'#f59e0b', fontSize:moderateScale(9), textAlign:'center', marginBottom:2 }} numberOfLines={1} adjustsFontSizeToFit minimumFontScale={0.75}>{t.awaitingYourConfirm}</Text>
                        <View style={{ flexDirection:'row', gap:3 }}>
                            <TouchableOpacity style={{ flex:1, backgroundColor:'#16a34a', borderRadius:moderateScale(8), paddingVertical:moderateScale(5), alignItems:'center' }} onPress={() => handleConfirmLateJoin('confirm')}>
                                <Text style={{ color:'#fff', fontSize:moderateScale(11), fontWeight:'700' }} numberOfLines={1} adjustsFontSizeToFit minimumFontScale={0.75}>{t.confirmJoinBtn}</Text>
                            </TouchableOpacity>
                            <TouchableOpacity style={{ flex:1, backgroundColor:'#ef444420', borderRadius:moderateScale(8), paddingVertical:moderateScale(5), alignItems:'center', borderWidth:1, borderColor:'#ef444440' }} onPress={() => handleConfirmLateJoin('cancel')}>
                                <Text style={{ color:'#f87171', fontSize:moderateScale(11), fontWeight:'700' }} numberOfLines={1} adjustsFontSizeToFit minimumFontScale={0.75}>{t.cancelJoinBtn}</Text>
                            </TouchableOpacity>
                        </View>
                    </View>
                ) : mySentReq === 'PENDING' ? (
                    <View style={{ flexDirection:'row', alignItems:'center', justifyContent:'center', gap:6 }}>
                        <TouchableOpacity onPress={handleWithdraw} style={{ flexShrink:0 }}>
                            <Text style={{ color:'#f87171', fontSize:moderateScale(9), fontWeight:'700', textAlign:'center' }} numberOfLines={1} adjustsFontSizeToFit minimumFontScale={0.75}>{t.withdrawReqBtn}</Text>
                        </TouchableOpacity>
                        <Text style={{ color:colors.textMuted, fontSize:moderateScale(10), textAlign:'center', flexShrink:1 }} numberOfLines={1} adjustsFontSizeToFit minimumFontScale={0.75}>
                            {Array.isArray(item.positions) && item.positions.includes('REFEREE') ? 'İsteğiniz Bekleniyor' : t.waitingReq}
                        </Text>
                    </View>
                ) : mySentReq === 'ACCEPTED' ? (
                    <Text style={{ color:'#4ade80', fontSize:moderateScale(10), fontWeight:'700', textAlign:'center' }} numberOfLines={1} adjustsFontSizeToFit minimumFontScale={0.75}>✓ Kabul</Text>
                ) : isFull ? (
                    <Text style={{ color:colors.textMuted, fontSize:moderateScale(10), textAlign:'center' }} numberOfLines={1} adjustsFontSizeToFit minimumFontScale={0.75}>{t.ilanFull || 'Dolu'}</Text>
                ) : null}
            </View>
            </>
            )}
        </Animated.View>

        <RivalDetailModal
            visible={detailVisible}
            item={item}
            myId={myId}
            sub={sub}
            cfg={cfg}
            t={t}
            onClose={() => setDetailVisible(false)}
            navigation={navigation}
            handleJoin={(slot) => { setDetailVisible(false); setTimeout(() => isTeamWantedAd ? setShowTeamJoinModal(true) : handleJoinPress(slot), 300); }}
            handleCancel={() => { setDetailVisible(false); setTimeout(handleCancel, 300); }}
            handleRespondJoin={handleRespondJoin}
            handleWithdraw={() => { setDetailVisible(false); setTimeout(handleWithdraw, 300); }}
            onRefresh={onRefresh}
            onEdit={() => { editOpenedFromDetailRef.current = true; setDetailVisible(false); setTimeout(() => setEditVisible(true), 300); }}
            myRefereeListing={refereeListings.find(r => r.userId === myId)}
            onConfirmLateJoin={handleConfirmLateJoin}
            highlightSlot={highlightSlot}
            autoOpenOrder={autoOpenOrder}
        />
        {isTeamWantedAd && (
            <TeamJoinRequestModal
                visible={showTeamJoinModal}
                onClose={() => setShowTeamJoinModal(false)}
                rival={item}
                sub={sub}
                category={item.category}
                cfg={cfg}
                navigation={navigation}
                onSent={onRefresh}
                t={t}
            />
        )}
        {/* Kullanıcı isteği: voleybol takım maçına katılmadan önce hangi pozisyonda oynamak
            istediğini (öncelik sırasıyla, dokunma sırası = öncelik) seçebilsin — ilan sahibi
            İstekler listesinde bunu görüp kabul/red kararını buna göre versin. */}
        <Modal visible={showPositionPicker} animationType="fade" transparent onRequestClose={() => setShowPositionPicker(false)}>
            <View style={{ flex:1, backgroundColor:'#00000090', justifyContent:'center', paddingHorizontal:30 }}>
                <View style={{ backgroundColor: colors.surface, borderRadius:16, padding:16 }}>
                    <Text style={{ color:'#fff', fontSize:14, fontWeight:'900', marginBottom:4 }}>Pozisyon Tercihi</Text>
                    <Text style={{ color: colors.textMuted, fontSize:11, marginBottom:12 }}>
                        İstersen oynamak istediğin pozisyon(lar)ı öncelik sırasıyla seç (dokunduğun sıra önceliğin olur) — dilersen hiç seçmeden de katılabilirsin.
                    </Text>
                    <View style={{ flexDirection:'row', gap:6, marginBottom:16 }}>
                        {[['SETTER', t.positionSetter], ['SPIKER', t.positionSpiker], ['LIBERO', t.positionLibero]].map(([pos, label]) => {
                            const idx = selectedPositions.indexOf(pos);
                            const selected = idx !== -1;
                            return (
                                <TouchableOpacity key={pos} onPress={() => togglePositionPref(pos)}
                                    style={{ flex:1, alignItems:'center', paddingVertical:9, borderRadius:10, borderWidth:1, borderColor: selected ? cfg.color : colors.border, backgroundColor: selected ? cfg.color+'20' : colors.surface2 }}>
                                    {selected && <Text style={{ color: cfg.color, fontSize:10, fontWeight:'900', marginBottom:2 }}>{idx + 1}</Text>}
                                    <Text style={{ color: selected ? cfg.color : colors.textSecondary, fontSize:11, fontWeight:'700' }} numberOfLines={1} adjustsFontSizeToFit minimumFontScale={0.75}>{label}</Text>
                                </TouchableOpacity>
                            );
                        })}
                    </View>
                    <View style={{ flexDirection:'row', gap:8 }}>
                        <TouchableOpacity onPress={() => { setShowPositionPicker(false); setSelectedPositions([]); }} style={{ flex:1, alignItems:'center', paddingVertical:11, borderRadius:10, backgroundColor:'#ffffff10' }}>
                            <Text style={{ color: colors.textMuted, fontWeight:'700' }}>Vazgeç</Text>
                        </TouchableOpacity>
                        <TouchableOpacity onPress={confirmJoinWithPosition} style={{ flex:1, alignItems:'center', paddingVertical:11, borderRadius:10, backgroundColor: cfg.color }}>
                            <Text style={{ color:'#fff', fontWeight:'800' }}>{t.joinBtn}</Text>
                        </TouchableOpacity>
                    </View>
                </View>
            </View>
        </Modal>
        {editVisible && (
            <CreateRivalModal
                visible
                onClose={closeEdit}
                category={item.category}
                sub={sub}
                onCreated={onRefresh}
                editItem={item}
            />
        )}

        {/* Hakemlik İçin Başvur — maç detayına girmeden, kart üzerinden doğrudan */}
        <Modal visible={refereeApplyVisible} animationType="slide" transparent onRequestClose={() => setRefereeApplyVisible(false)} android_keyboardInputMode="adjustNothing">
            <View style={{ flex:1, backgroundColor:'#00000080', justifyContent:'flex-end' }}>
                <KeyboardAvoidingView behavior="padding">
                    <View style={{ backgroundColor: colors.surface, borderTopLeftRadius:24, borderTopRightRadius:24, paddingHorizontal:17, paddingTop:17, paddingBottom:37 }}>
                        <View style={{ flexDirection:'row', alignItems:'center', marginBottom:14 }}>
                            <Text style={{ color:'#fff', fontSize:moderateScale(16), fontWeight:'800', flex:1 }}>{t.refereeApplyBtn}</Text>
                            <TouchableOpacity onPress={() => setRefereeApplyVisible(false)}><Text style={{ color: colors.textMuted, fontSize:moderateScale(20) }}>✕</Text></TouchableOpacity>
                        </View>
                        <Text style={s.fieldLabel}>{t.refereePaymentLabel}</Text>
                        <TextInput style={s.fieldInput} value={refereeOfferPrice} onChangeText={v => setRefereeOfferPrice(v.replace(/[^0-9]/g, ''))}
                            placeholder="500" placeholderTextColor={colors.textMuted} keyboardType="numeric" />
                        <Text style={s.fieldLabel}>{t.messageFieldLabel}</Text>
                        <TextInput style={[s.fieldInput, { height:70, textAlignVertical:'top' }]}
                            value={refereeOfferMessage} onChangeText={setRefereeOfferMessage}
                            placeholder={t.refereeApplyMsgPh} placeholderTextColor={colors.textMuted} multiline />
                        <TouchableOpacity style={[s.submitBtn, { backgroundColor:'#f59e0b' }, refereeApplySubmitting && { opacity:0.6 }]}
                            onPress={submitRefereeApply} disabled={refereeApplySubmitting}>
                            <Text style={s.submitBtnText}>{refereeApplySubmitting ? t.submittingBtn : t.refereeApplySendBtn}</Text>
                        </TouchableOpacity>
                    </View>
                </KeyboardAvoidingView>
            </View>
        </Modal>

        </>
    );
}

// Tarih seçimi artık paylaşılan components/CalendarPickerModal.js üzerinden yapılıyor
// (uygulama genelinde aynı takvim görünümü için) — bkz. yukarıdaki import.

// ─── Text Post Card ────────────────────────────────────────────────────────────

function TextPostCard({ post, cfg }) {
    const t = useT();
    const [liked, setLiked] = useState(Array.isArray(post.likes) && post.likes.length > 0);
    const [likesCount, setLikesCount] = useState(post._count?.likes || 0);
    const [showComments, setShowComments] = useState(false);
    const [comments, setComments] = useState(post.comments || []);
    const [commentText, setCommentText] = useState('');
    const [sendingComment, setSendingComment] = useState(false);

    const toggleLike = async () => {
        const next = !liked;
        setLiked(next);
        setLikesCount(c => next ? c + 1 : Math.max(0, c - 1));
        try { await api.post(`/posts/${post.id}/like`); }
        catch { setLiked(!next); setLikesCount(c => next ? Math.max(0, c - 1) : c + 1); }
    };

    const openComments = async () => {
        setShowComments(v => !v);
        if (!showComments && comments.length === 0) {
            try {
                const { data } = await api.get(`/posts/${post.id}/comments`);
                setComments(data);
            } catch {}
        }
    };

    const sendComment = async () => {
        const text = commentText.trim();
        if (!text) return;
        setSendingComment(true);
        try {
            const { data } = await api.post(`/posts/${post.id}/comment`, { content: text });
            setCommentText('');
            setComments(prev => [...prev, data]);
        } catch {}
        finally { setSendingComment(false); }
    };

    const timeAgo = (dateStr) => {
        const diff = Date.now() - new Date(dateStr).getTime();
        const m = Math.floor(diff / 60000);
        if (m < 1) return t.timeNow;
        if (m < 60) return `${m}${t.timeMinSuffix}`;
        const h = Math.floor(m / 60);
        if (h < 24) return `${h}${t.timeHourSuffix}`;
        return `${Math.floor(h / 24)}${t.timeDaySuffix}`;
    };

    return (
        <View style={s.card}>
            <View style={s.cardHeader}>
                <Avatar name={post.user?.username} size={38} color={cfg.color} />
                <View style={{ flex: 1 }}>
                    <Text style={s.cardName}>{post.user?.fullName || post.user?.username}</Text>
                    <Text style={s.cardSub}>{post.user?.username} · {timeAgo(post.createdAt)}</Text>
                </View>
            </View>
            <Text style={[s.cardMsg, { marginBottom: 12, lineHeight: 20 }]}>{post.content}</Text>
            <View style={{ flexDirection: 'row', gap: 3, marginBottom: showComments ? 10 : 0 }}>
                <TouchableOpacity onPress={toggleLike} style={{ flexDirection: 'row', alignItems: 'center', gap: 3 }}>
                    <Text style={{ color: liked ? '#f43f5e' : colors.textMuted, fontSize: 16 }}>♥</Text>
                    <Text style={{ color: colors.textMuted, fontSize: 12, fontWeight: '700' }}>{likesCount}</Text>
                </TouchableOpacity>
                <TouchableOpacity onPress={openComments} style={{ flexDirection: 'row', alignItems: 'center', gap: 3 }}>
                    <Text style={{ color: showComments ? cfg.color : colors.textMuted, fontSize: 14 }}>💬</Text>
                    <Text style={{ color: colors.textMuted, fontSize: 12, fontWeight: '700' }}>{comments.length || post._count?.comments || 0}</Text>
                </TouchableOpacity>
            </View>
            {showComments && (
                <View style={{ borderTopWidth: 1, borderTopColor: colors.border, paddingTop: 5 }}>
                    {comments.map((c, i) => (
                        <View key={c.id || i} style={{ flexDirection: 'row', gap: 3, marginBottom: 5 }}>
                            <Text style={{ color: cfg.color, fontSize: 12, fontWeight: '800' }}>{c.user?.username}</Text>
                            <Text style={{ color: colors.textSecondary, fontSize: 12, flex: 1 }}>{c.content}</Text>
                        </View>
                    ))}
                    <View style={{ flexDirection: 'row', gap: 3, marginTop: 6 }}>
                        <TextInput
                            style={{ flex: 1, backgroundColor: colors.surface, borderRadius: 8, paddingHorizontal: 7, paddingVertical: 3, color: '#fff', fontSize: 12, borderWidth: 1, borderColor: colors.border }}
                            placeholder="Yorum yaz..."
                            placeholderTextColor={colors.textMuted}
                            value={commentText}
                            onChangeText={setCommentText}
                        />
                        <TouchableOpacity onPress={sendComment} disabled={sendingComment || !commentText.trim()}
                            style={{ backgroundColor: cfg.color, borderRadius: 8, paddingHorizontal: 11, justifyContent: 'center', opacity: !commentText.trim() ? 0.4 : 1 }}>
                            <Text style={{ color: '#fff', fontWeight: '900', fontSize: 14 }}>{sendingComment ? '…' : '↑'}</Text>
                        </TouchableOpacity>
                    </View>
                </View>
            )}
        </View>
    );
}

// ─── Upcoming Match Card ────────────────────────────────────────────────────────

